WITH payload AS (SELECT $archive_payload$[{"id":"e8d88300-3371-5d11-a340-1acf84c15ad7","document_type":"judgment","category":"judicial","subcategory":"general","title":"بيع أجهزة استقبال قنوات خليعة (إباحية) -لم يقدم املدعي العام البينة -البينة يف األصل تطلب من املدعي سواء يف احلق العام أو اخلاص وللمحكمة اخليار يف طلبها مباشرة -صرف النظر عن دعوى املدعى العام لعدم ثبوت التهمة.","document_number":"33391127","case_number":"33349638","judgment_number":null,"decision_number":null,"circular_number":null,"court":null,"circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1433/8/24","year":"1434","subject":"بيع أجهزة استقبال قنوات خليعة (إباحية) -لم يقدم املدعي العام البينة -البينة يف األصل تطلب من املدعي سواء يف احلق العام أو اخلاص وللمحكمة اخليار يف طلبها مباشرة -صرف النظر عن دعوى املدعى العام لعدم ثبوت التهمة.","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"     ‫رقم الصك ‪ 33391127 :‬تاريخه‪1433/8/24 :‬هـ‬\n                        ‫رقم الدعوى‪33349638 :‬‬\n         ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n                ‫‪ 34218817‬تاريخه‪1434/5/21 :‬هـ‬\n\n\n     ‫بيــع أجهــزة اســتقبال قنــوات خليعــة (إباحيــة) ‪ -‬لــم يقــدم املدعــي العــام‬\n     ‫البينــة ‪ -‬البينــة يف األصــل تطلــب مــن املدعــي ســواء يف احلــق العــام أو‬\n     ‫اخلــاص وللمحكمــة اخليــار يف طلبهــا مباشــرة ‪ -‬صــرف النظــر عــن‬\n                                         ‫دعــوى املدعــى العــام لعــدم ثبــوت التهمــة‪.‬‬\n\n\n\n                                  ‫‪ -‬املادة (‪ )165‬من نظام االجراءات اجلزائية ‪.‬‬\n\n\n\n\n     ‫جــرى توجيــه االتهــام مــن املدعــي العــام للمدعــى عليــه ببيــع أجهــزة‬\n     ‫اســتقبال لفــك شــفرة القنــوات اخلليعــة اإلباحيــة وطلبــت إيقــاع العقوبــة‬\n     ‫التعزيريــة عليــه ومصــادرة مــا ضبــط بحوزتــه حيــث هــرب حــن رؤيتــه‬\n     ‫أعضــاء الهيئــة فلمــا قبــض عليــه تبــن أنــه يقــوم ببيــع جهــاز اســتقبال‬\n     ‫قنــوات اباحيــة (خليعــة) ‪ ،‬أنكــر املدعــى عليــه التهمــة املوجهــة إليــه ‪،‬‬\n     ‫طلبــت البينــة مــن املدعــي العــام فأمهــل أكثــر مــن ثــاث جلســات لــم‬\n     ‫يحضــر يف أحدهــا بينــة عليــه فقــد قــررت احملكمــة احلكــم بصــرف‬\n     ‫النظــر عــن دعــوى املدعــي العــام لعــدم ثبــوت التهمــة ‪ ،‬قــرر املدعــى العــام‬\n     ‫عــدم القناعــة وطلــب رفــع القضيــة لالســتئناف بــدون تقــدمي الئحــة ‪-‬‬\n     ‫عــادت القضيــة مــن محكمــة االســتئناف مشــفوع ًة بالتنويــه أن املــادة‬\n\n‫‪39‬‬\n\f‫(‪ )165‬مــن نظــام اإلجــراءات اجلزائيــة جعلــت للمحكمــة اســتدعاء أي‬\n‫شــاهد ورأت حاجــة يف ســماع أقوالــه وطلبــت مــن احملكمــة اســتدعاء‬\n‫معــدي محضــر القبــض مــن قبلهــا ‪ ،‬أجابــت احملكمــة بــأن املــادة علــى‬\n‫التخييــر وليــس للوجــوب وهــو املتوافــق مــع قواعــد الفقــه اإلســامي بــأن‬\n‫جعلــت البينــة علــى املدعــي وجعلــت لــه ثــاث مهــل ثــم يحكــم بعجــزه‬\n‫وهــو األصــل يف النظــام الســعودي لــذا لــم تــر موجبــا لهــذا اإلجــراء ولــم‬\n‫تــر العــدول عمــا حكمــت بــه ‪ ،‬عــادت القضيــة بعــد ذلــك مصدقــة مــن‬\n                                                          ‫محكمــة االســتئناف‪.‬‬\n\n\n\n‫احلمــد هلل وحــده وبعــد فلــدي أنــا ‪...........‬القاضــي يف احملكمــة اجلزئيــة‬\n‫بالريــاض وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة رئيــس احملكمــة‬\n‫اجلزئيــة بالريــاض برقــم ‪ 33955306‬يف ‪1433/5/19‬ه ـ احملالــة برقــم‬\n‫‪ 33349638‬يف ‪1433/5/9‬ه ـ ففــي يــوم األحــد ‪1433/6/8‬ه ـ افتتحــت‬\n‫اجللســة الســاعة احلاديــة عشــر وفيهــا حضــر املدعــي العــام ‪...........‬ادعــي‬\n‫على ‪ 38 ،........... /‬ســنة‪ ،‬بنجالديشــي اجلنســية مبوجب رخصة اإلقامة‬\n‫رقــم (‪ )...........‬غيــر محصــن ‪ ،‬يقيــم مبدينــة الريــاض ‪ ،‬مفــرج عنــه‬\n‫بتاريــخ ‪1433/4/30‬ه ـ اســتنادا إلــى املــادة (‪.)120‬مــن نظــام اإلجــراءات‬\n‫اجلزائيــة ‪ .‬حيــث إنــه بتاريــخ ‪1433/4/29‬ه ـ قبــض علــى املذكــور مــن‬\n‫قبــل هيئــة األمــر باملعــروف والنهــي عــن املنكــر ‪ /‬مركــز هيئــة ‪...........‬‬\n‫وذلــك بعــد أن شــاهد أعضــاء الفرقــة املذكــور يــزاول البيــع داخــل أحــد‬\n‫محــات االطبــاق الفضائيــة ومبشــاهدته جلهــة القبــض حــاول الهــرب‬\n‫فتــم القبــض عليــه وضبــط بحوزتــه علــى رســيفرين تســتقبل القنــوات‬\n\n                                                                                     ‫‪40‬‬\n\f     ‫االباحيــة وقــد أســفرت إجــراءات التحقيــق عــن اتهامــه بترويــج أجهــزة‬\n     ‫رســيفرات لفــك شــفرات القنــوات اإلباحية‪.‬وذلــك لألدلــة والقرائــن‬\n                                                                              ‫التالــي‪:‬‬\n                             ‫‪ -1‬ما ورد يف محضر الكشف املرفق لفة رقم (‪.)2‬‬\n                               ‫‪ -2‬ما ورد يف محضر القبض السابق لفة رقم (‪.)3‬‬\n     ‫وببحــث ســوابقه اتضــح عــدم وجــود ســوابق عليــه حتــى تاريخــه ‪ .‬وحيــث‬\n     ‫إن مــا اقــدم عليــه املذكــور فعــل محــرم ومعاقــب عليــه شــرع ًا لــذا‬\n     ‫أطلــب إثبــات مــا أســند إليــه واحلكــم عليــه بعقوبــة تعزيريــة لقــاء مــا‬\n     ‫ســند اليــه ومصــادرة مــا ضبــط بحوزتــه‪ .‬وبعــرض الدعــوى علــى املدعــى‬\n     ‫عليــه ‪...........‬وهــو يعــرف اللغــة العربيــة بشــكل كاف أجــاب قائــا مــا‬\n     ‫ذكــره املدعــي العــام غيــر صحيــح وبســؤال املدعــي العــام عــن بينتــه‬\n     ‫قــال لــدي شــهود القبــض ومســتعد بإحضارهــم وأجلــت اجللســة الــى يــوم‬\n     ‫الســبت املوافــق ‪ 6/21‬الســاعة التاســعة وصلــى اهلل وســلم علــى نبينــا‬\n     ‫محمــد وآلــه وصحبــه وســلم حــرر يف ‪1433/6/8‬ه ـ احلمــد هلل وحــده‬\n     ‫وبعــد ففــي يــوم الســبت املوافــق‪ 1433/06/21‬ه ـ افتتحــت اجللســة‬\n     ‫الســاعة ‪ 01 : 37‬وفيهــا حضــر املدعــي العــام ولــم يحضــر بينتــه وطلــب‬\n     ‫مهلــة أخــرى وأجلــت اجللســة ليــوم األحــد ‪1433/7/6‬ه ـ الســاعة التاســعة‬\n     ‫والنصــف وبــاهلل التوفيــق ‪ ،‬وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه‬\n                                        ‫وصحبــه وســلم ‪ .‬حــرر يف ‪1433/6/21‬ه ـ‬\n     ‫احلمــد هلل وحــده ففــي يــوم االحــد املوافــق ‪ 1433/07/6‬ه ـ افتتحــت‬\n     ‫اجللســة الســاعة ‪ 9‬وفيهــا حضــر املدعــي العــام ولــم يحضــر بينتــه وطلــب‬\n     ‫مهلــة أخــرى عليــه رفعــت اجللســة وأجلت إلــى يوم االثنــن ‪1433/7/21‬هـ‬\n     ‫الســاعة التاســعة والنصــف وبــاهلل التوفيــق ‪ ،‬وصلــى اهلل علــى نبينــا‬\n\n\n‫‪41‬‬\n\f                ‫محمــد وعلــى آلــه وصحبــه وســلم ‪ .‬حــرر يف ‪1433/7/7‬ه ـ‬\n‫احلمــد هلل وحــده وبعــد ففــي يــوم األربعــاء املوافــق‪ 1433/07/23‬ه ـ‬\n‫افتتحــت اجللســة الســاعة‪ 08 :45‬وفيهــا حضــر املدعــي العــام ولــم‬\n‫يحضــر بينتــه وطلــب مهلــة أخــرى عليــه رفعــت اجللســة وأجلــت الــى يــوم‬\n‫األحــد ‪ 08/04‬الســاعة التاســعة والنصــف وبــاهلل التوفيــق ‪ ،‬وصلــى اهلل‬\n‫علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم ‪ .‬حــرر يف ‪1433/7/23‬ه ـ‬\n‫احلمــد هلل وحــده وبعــد ففــي يوم األحد املوافق‪ 1433/08/04‬هـ افتتحت‬\n‫اجللســة الســاعة ‪ 01 :00‬وفيهــا حضــر املدعــي العــام ولــم يحضــر بينتــه‬\n‫وطلــب مهلــة أخــرى عليــه أجلــت اجللســة ليــوم الثالثــاء ‪1433/8/20‬ه ـ‬\n‫الســاعة العاشــرة وبــاهلل التوفيــق‪ ،‬وصلــى اهلل علــى نبينــا محمــد وعلــى‬\n                                   ‫آلــه وصحبــه وســلم ‪ .‬حــرر يف ‪1433/8/4‬ه ـ‬\n‫احلمــد هلل وحــده وبعــد ففــي يــوم األربعــاء املوافــق‪ 1433/08/21‬ه ـ‬\n‫افتتحــت اجللســة الســاعة ‪ 10 :15‬وفيهــا حضــر املدعــي العــام ولــم يحضر‬\n‫بينتــه وحيــث ان هــذه هــي املهلــة اخلامســة ولــم يحضــر املدعــي العــام‬\n‫شــهوده واملدعــى عليــه منكــر لذلــك فقــد حكمــت بصــرف النظــر عــن‬\n‫دعــوى املدعــي العــام لعــدم الثبــوت وبعــرض احلكــم علــى املدعــي العــام‬\n‫قــرر عــدم القناعــة وطلــب االســتئناف مكتفيــا مبــا يف املعاملــة وبــاهلل‬\n‫التوفيــق ‪ ،‬وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم ‪.‬‬\n                                                   ‫حــرر يف ‪1433/8/21‬ه ـ ‪.‬‬\n‫احلمــد هلل وحــده وبعــد ففــي يــوم الثالثــاء املوافــق‪ 1434/03/17‬ه ـ‬\n‫افتتحــت اجللســة الســاعة ‪ 01 : 00‬وقــد عــادت املعاملــة مــن محكمــة‬\n‫االســتئناف وبرفقتهــا قرارهــا رقــم ‪ 33462468‬يف ‪1434/11/22‬ه ـ‬\n‫ويتضمــن املالحظــة بــأن املــادة رقــم ‪ 165‬مــن نظــام اإلجــراءات اجلزائيــة‬\n\n\n                                                                                  ‫‪42‬‬\n\f     ‫جعلــت للمحكمــة اســتدعاء أي شــاهد ورأت حاجتــه يف ســماع أقوالــه‬\n     ‫فعلــي اســتدعاء معــدي محضــر القبــض وأجيــب أصحــاب الفضيلــة‬\n     ‫وفقهــم اهلل تعالــي بــأن املــادة املذكــورة جعلــت هــذا األمــر حــق‬\n     ‫للمحكمــة وليــس عليهــا أي إذا طلبــت ذلــك وحــث إجابهــا وإن لــم‬\n     ‫تطالــب فــا جتبــر ولــو قيــل باإلجبــار لــكان القاضــي مدعــي عــام وامــا‬\n     ‫قواعــد الفقــه االســامي فقــد جعلــت البينــة علــى املدعــي وجعلــت لــه‬\n     ‫فــات مهــل ثــم يحكــم بعجــزه وهــو األصــل يف النظــام الســعودي لذلــك‬\n     ‫لــم ار مــا يوجــب عدولــي عمــا حكمــت بــه وبــاهلل التوفيــق ‪ ،‬وصلــى اهلل‬\n     ‫علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم ‪ .‬حــرر يف ‪1434/3/17‬ه ـ ‪.‬‬\n     ‫احلمــد هلل وحــده وبعــد ‪ ...‬فقــد اطلعنــا نحــن قضــاة الدائــرة الثانيــة لتمييز‬\n     ‫القضايــا اجلزائيــة مبحكمــة االســتئناف بالريــاض علــى املعاملــة الــواردة‬\n     ‫مــن فضيلــة رئيــس احملكمــة اجلزائيــة بالريــاض برقــم ‪332202317‬‬\n     ‫وتاريــخ ‪1434/3/24‬ه ـ املرفــق بهــا القــرار الصــادر مــن فضيلــة القاضــي‬\n     ‫باحملكمــة الشــيخ‪ .........../‬املســجل برقــم ‪ 33391127‬وتاريــخ‬\n     ‫‪ 1433/8/24‬ه ـ اخلــاص بدعــوى املدعــي العــام ضــد ‪....................../‬‬\n     ‫(بنجالديشــي اجلنســية) التهامــه بترويــج أجهــزة رســيفرات تســتقبل‬\n     ‫القنــوات اإلباحيــة علــى النحــو املوضــح بالقرار املتضمــن حكم فضيلته‬\n     ‫مبــا هــو مــدون ومفصــل بــه‪ .‬وحيــث ســبق دراســة القــرار وصــورة ضبطــه‬\n     ‫وأوراق املعاملــة وباالطــاع علــى مــا أجــاب بــه فضيلتــه علــى قرارنــا رقــم‬\n     ‫‪ 33462468‬وتاريــخ ‪1433/11/22‬ه ـ املصادقــة علــى احلكــم بعــد‬\n     ‫اجلــواب مــن فضيلتــه‪ .‬واهلل املوفــق وصلــى اهلل علــى نبينــا محمــد وعلــى‬\n                                                                   ‫آلــه وصحبــه وســلم‬\n\n\n\n‫‪43‬‬\n\f44\n\f45\n\f46\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"d790af0e-7af1-509b-8d33-8ecc09f91096","source_page_start":39,"source_page_end":46,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"cdff5ab004150b9220db61753b774775d405e48643d205ef86d9c4bf699e7501","normalized_text_hash":"8f91a2fae3ed486600064b91875e1ab98d3c020c15b2d2b5af66236a9810f7c3","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v25-p39-33391127"},{"id":"3b4ef58d-c939-5d51-ab32-015cd3169aa1","document_type":"judgment","category":"judicial","subcategory":"general","title":"سرقة -سرقة سيارة بوضع التشغيل -سرقة بعض محتويات السيارة -التعزير بالسجن واجللد العلني .","document_number":"34194066","case_number":"342326","judgment_number":null,"decision_number":null,"circular_number":null,"court":"محكمة الاستئناف","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/04/21","year":"1434","subject":"سرقة -سرقة سيارة بوضع التشغيل -سرقة بعض محتويات السيارة -التعزير بالسجن واجللد العلني .","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"     ‫رقم الصك‪ 34194066 :‬تاريخه‪1434/04/21 :‬هـ‬\n                           ‫رقم الدعوى‪342326 :‬‬\n         ‫رقم قرار التصديق من محكمة االستئناف ‪:‬‬\n               ‫‪ 34262153‬تاريخه ‪1434/07/08 :‬هـ‬\n\n\n\n     ‫ســرقة ‪ -‬ســرقة ســيارة بوضــع التشــغيل ‪ -‬ســرقة بعــض محتويــات‬\n                       ‫الســيارة ‪ -‬التعزيــر بالســجن واجللــد العلنــي ‪.‬‬\n\n\n\n\n                                  ‫‪ -‬املادة (‪ )163‬من نظام اإلجراءات اجلزائية‪.‬‬\n                                     ‫‪ -‬املادة (‪ )3‬من نظام اإلجراءات اجلزائية‪.‬‬\n\n\n\n\n     ‫توجيــه االتهــام للمدعــى عليــه بســرقة ســيارتني بوضع التشــغيل ‪ ،‬بداخل‬\n     ‫الســيارتني أجهــزة جــوال وجهــاز حاســب آلــي محمــول و‪ ، ...‬ومبلــغ مالــي‬\n     ‫‪ ،‬حيــث ورد بالغــان ملركــز الشــرطة ‪ ...‬عــن تعــرض ســيارتي املبلغــن‬\n     ‫للســرقة وهــي بوضــع التشــغيل أثنــاء نزولهمــا للشــراء مــن بعــض احملــات‬\n     ‫‪ ،‬ذكــر املبلغــان مايوجــد يف الســيارتني مــن أغــراض ‪ ،‬مت القبــض علــى‬\n     ‫شــخص مــن قبــل إدارة التحريــات والبحــث اجلنائــي أثنــاء وجــوده يف‬\n     ‫ســوق للجــواالت وبحوزتــه اجلــوال املســروق والــذي أفــاد أنــه اســتحصل‬\n     ‫علــى هــذا اجلــوال مــن شــخص آخــر ‪ ،‬جــرى متابعــة سلســلة تنقــل اجلــوال‬\n     ‫وبيعــه حتــى وصــل للمدعــى عليــه ‪ ،‬مت القبــض علــى املدعــى عليــه بعــد‬\n     ‫هروبــه علــى قدميــه وضبــط بحوزتــه علــى جهــاز حاســب آلــي محمــول‬\n     ‫مســروق وطلــب املدعــي العــام إثبــات مــا أســند للمدعــى عليــه واحلكــم‬\n‫‪47‬‬\n\f‫عليــه بعقوبــه تعزيريــة ‪ ،‬أنكــر املدعــى عليــه مــا نســب إليــه ‪ ،‬أحضــر‬\n‫املدعــي العــام بيناتــه التــي رأت احملكمــة أنهــا توجــه التهمــة القويــة‬\n‫للمدعــى عليــه ‪ ،‬صــدر احلكــم بتوجــه التهمــه القويــة للمدعــى عليــه‬\n‫بســرقة جهــاز احلاســب اآللــي احملمــول واجلــوال دون غيرهــا ‪ ،‬قضــت‬\n‫احملكمــة بتعزيــر املدعــى عليــه بالســجن واجللــد يف مــكان عــام ‪،‬‬\n                               ‫وصــدق احلكــم مــن محكمــة االســتئناف ‪.‬‬\n\n\n\n\n‫احلمــدهلل وحــده وبعــد فلــدي انــا القاضــي املنــدوب للمحكمــة اجلزئيــة‬\n‫بالريــاض واملكلــف بعمــل املكتــب القضائــي رقــم (‪ )00‬مبوجــب‬\n‫خطــاب التكليــف الصــادر مــن رئيــس احملكمــة اجلزائيــة بالريــاض‬\n‫املكلــف برقــم ‪ 00000000‬يف ‪0000/00/0‬ه ـ املبنــي علــى قــرار‬\n‫املجلــس االعلــى للقضــاء رقــم ‪ 3321434‬يف ‪0000/00/00‬ه ـ ويف يــوم‬\n‫االحــد ‪0000/0/0‬ه ـ ويف متــام الســاعة (‪ )02،00‬افتتحــت اجللســة‬\n‫اخلاصــة بدعــوى املدعــي العــام ضــد املدعــى عليــه وفيهــا حضــر املدعــى‬\n‫عليــه وادعــى املدعــي العــام قائــا مدعي ـ ًا عام ـ ًا يف دائ ــرة االدع ــاء الع ــام‬\n‫مبدين ــة الري ــاض أدع ــي علــى ‪ ...................... /‬العمــر ‪ ....‬ســنة ســعودي‬\n‫اجلنســية مبوجــب الهويــة رقــم (‪ ).................‬أوقــف بتاريــخ ‪..../../..‬ه ـ‬\n‫وأحيــل إلــى ســجن امللــز بأمــر التوقيــف رقــم (بــدون) وتاريــخ ‪..../../..‬ه ـ‬\n‫‪ .‬وبتاريــخ ‪..../../..‬ه ـ أبلــغ ‪ ....................... /‬أنــه أثنــاء نزولــه مــن ســيارته‬\n‫نــوع ‪ .....‬لوحــة رقــم (‪ )........‬ملطعــم ‪ .........‬بحــي ‪ .....‬تــارك ًا الســيارة‬\n‫بوضــع التشــغيل وعنــد خروجــه لــم يجدهــا وكان بداخلهــا عــدد (‪)2‬‬\n‫جــوال األول ‪ ....‬والثانــي نــوع ‪ .....‬وجهــاز الب تــوب نــوع ‪ . .....‬بتاريــخ‬\n\n                                                                                                 ‫‪48‬‬\n\f     ‫‪..../../..‬ه ـ أبلــغ ‪ ............ /‬أنــه أثنــاء نزولــه مــن ســيارته نــوع ‪ ....‬اللــون‬\n     ‫‪ ...‬لوحــة رقــم (‪ )......‬ودخولــه أحــد الصيدليــات علــى شــارع ‪................‬‬\n     ‫بحــي ‪ .....‬تــارك ًا الســيارة بوضــع التشــغيل وبعــد خروجــه لــم يجدهــا‬\n     ‫وكان بداخلهــا عــدد (‪ )2‬جهــاز ‪ ...‬وجهــاز جــوال نــوع ‪ ....‬بــه شــريحة رقــم‬\n     ‫(‪ )000000000‬ومبلــغ مالــي قــدره اثنــا عشــر ألــف وأربعمائــة وخمســون‬\n                                                                                        ‫ريــال ‪.‬‬\n     ‫وبتاريــخ ‪..../../..‬ه ـ ورد خطــاب إدارة التحريــات والبحــث اجلنائــي‬\n     ‫رقــم ‪ 0000‬وتاريــخ ‪..../../.‬ه ـ املتضمــن القبــض علــى ‪....................... /‬‬\n     ‫مبحــل االتصــاالت وبحوزتــه جهــاز اجلــوال املســروق نــوع ‪ ....‬مــن الســيارة‬\n     ‫األولــى والــذي أفــاد أنــه اســتحصل علــى جهــاز اجلــوال املســروق مــن ‪/‬‬\n     ‫‪ ........................‬مينــي اجلنســية ‪ .‬وبتاريــخ ‪....../../..‬ه ـ ورد خطــاب إدارة‬\n     ‫التحريــات والبحــث اجلنائــي رقــم (‪ )0000‬وتاريــخ ‪..../../..‬ه ـ املتضمــن‬\n     ‫أنــه بتاريــخ ‪..../../..‬ه ـ مت القبــض علــى ‪( ............................... /‬مينــي‬\n     ‫اجلنســية ال يحمــل إقامــة) والــذي قــام بإعطــاء اجلــوال املســروق نــوع ‪...‬‬\n     ‫للبائــع ‪ ...................... /‬مينــي اجلنســية وأفــاد أنــه حصــل علــى هــذا اجلــوال‬\n     ‫مــن ‪ ........................... /‬وجــرى أحضــار املتهــم ‪.......................... /‬‬\n     ‫والــذي أفــاد ايض ـ ًا أنــه اســتحصل علــى جهــاز اجلــوال املســروق مــن‬\n     ‫املدعــى عليــه ‪ ........................ /‬وبتاريــخ ‪..../../..‬ه ـ قبــض علــى املدعــى‬\n     ‫عليــه بعــد هروبــه علــى األقــدام وضبــط بحوزتــه علــى جهــاز الب تــوب‬\n     ‫والــذي اتضــح أنــه املســروق مــن الســيارة الثانيــة كمــا ضبــط علــى قطعة‬\n     ‫حشــيش بحوزتــه (فــرزت أوراق مســتقلة لقضيــة املخــدرات) ‪ .‬وبســماع‬\n     ‫أقــوال ‪ ........................ /‬مينــي اجلنســية أفــاد بحضــور شــخص مــن‬\n     ‫اجلنســية اليمنيــة ويدعــى‪ .................... /‬لــه يف محلــه ومعــه اجلهــاز اجلــوال‬\n\n\n‫‪49‬‬\n\f‫وطلــب بيعــه وقــام بشــرائه بقيمــة (ألــف وخمســمائة وخمســون ريــال) ولــم‬\n‫يــدون هويتــه كونــه يعــرف والــده وال يعــرف ســكنه ‪ .‬وبســماع أقــوال ‪/‬‬\n‫‪ ........................‬مينــي اجلنســية (لــم يوجــه االتهــام لــه بشــي وجــرى إطــاق‬\n‫ســراحه) أفــاد بأنــه حضــر لــه ‪ ..........................‬وطلــب منــه بيــع جــوال‬\n‫نــوع ‪ ....‬لــه مقابــل اعطائــه مبلــغ مائــة ريــال كونــه ســبق وأن عمــل يف‬\n                                       ‫محــات االتصــاالت وذهــب ألحــد زمالئــه‬\n‫ويدعــى ‪ ........................ /‬مينــي اجلنســية وطلــب منــه بيــع اجلــوال وقــام‬\n‫بشــرائه منــه مببلــغ (الــف وخمســمائة وخمســون ريــال) وهــو ال يعلــم أنــه‬\n‫مســروق (لــم يوجــه االتهــام لــه بشــي وجــرى إحالتــه للجهــة املختصــة‬\n‫ملعاجلــة اإلقامــة غيــر النظاميــة لــه يف البــاد) ‪ .‬وبســماع أقــوال ‪/‬‬\n‫‪ .............................‬أفــاد بانــه مت االتصــال عليــه مــن قبــل ‪.....................‬‬\n‫وطلــب منــه احلضــور ألحــد الشــقق علــى ‪ ....‬العطائــه هديــة ‪ .‬وحضــر‬\n‫لــه وكان املتهــم ينتظــره علــى ســيارة نــوع ‪ ....‬وهــي الســيارة املســروقة‬\n‫وقــام بإعطائــه جــوال نــوع ‪ ....‬وقــال لــه هــذا بشــأن زعلــك علــي ولديــه‬\n‫شــاهدين علــى ذلــك (لــم يوجــه االتهــام لــه بشــي وجــرى إطــاق ســراحه)‬\n‫‪ .‬وباســتجواب املدعــى عليــه ‪ ............................. /‬أقــر بأنــه أهــدى إلــى‬\n‫زميلــه ‪ ..... /‬جــوال ‪ .‬وبضبــط شــهادة الشــاهد ‪............................... /‬‬\n‫أفــاد بالذهــاب ألحــد الشــقق بحــي ‪ ....‬برفــق زميلــه ‪..................... /‬‬\n‫ملقابلــة املدعــى عليــه ‪ ....... /‬الــذي قــام بإعطــاء اجلــوال املســروق ‪ /‬لزميلــه‬\n‫‪ .................‬وبضبط شهادة الشاهد ‪ .......................... /‬مصري اجلنسية‬\n‫أفــاد بالذهــاب ألحــد الشــقق بحــي ‪ ....‬برفــق زميلــه ‪......................... /‬‬\n‫ملقابلــة املدعــى عليــه والــذي قــام بإعطــاء زميلــه اجلــوال املســروق ‪ .‬وجــرى‬\n‫عــرض املدعــى عليــه ضمــن طابــور عرض نظامــي على املدعى ‪ /‬صاحب‬\n\n\n                                                                                                   ‫‪50‬‬\n\f     ‫‪ ..............‬واســتطاع التعــرف عليــه‪ .‬وانتهــى التحقيــق إلــى توجيــه االتهــام‬\n     ‫للمدعــى عليــه بســرقة ســيارة نــوع ‪ .....‬املنــوه عنهــا وبداخلهــا (‪ )2‬جهــازي‬\n     ‫جــوال نــوع ‪ ....‬واألخــر ‪ ....‬وجهــاز حاســب آلــي الب تــوب وســيارة نــوع ‪.....‬‬\n     ‫املنــوه عنهــا وبداخلهــا (‪ )2‬جهــاز ‪ ...‬وجهــاز جــوال ‪ ....‬ومبلــغ مالــي قــدره‬\n                                                                            ‫(‪12450‬ريــال) ‪.‬‬\n                                                            ‫وذلك لألدلة والقرائن التالية‪:‬‬\n     ‫‪ -1‬مــا جــاء يف أقوالــه بأنــه أعطــى اجلــوال املســروق إلــى زميلــه ‪........ /‬‬\n     ‫كهديــة وبســبب أنــه بينهمــا ســوء تفاهــم املدونــة علــى ص (‪ )...‬مــن دفتــر‬\n                                                                         ‫التحقيــق لفــة (‪. )...‬‬\n     ‫‪ -2‬محضــر القبــض عليــه مــن قبــل دوريــات األمــن وبحوزتــه جهــاز الب‬\n     ‫تــوب الــذي كان موجــود ًا يف الســيارة املســروقة نــوع ‪ ....‬املرفــق لفــة (‪)...‬‬\n                                                                              ‫بداخــل الطــرد ‪.‬‬\n     ‫‪ -3‬إفــادة صاحــب الســيارة املســروقة نــوع ‪ .....‬املبلــغ ‪ /‬املتضمنــة تعرفــه‬\n     ‫علــى املدعــى عليــه أثنــاء عرضــه عليــه يف إدارة البحــث اجلنائيــة املدونــة‬\n                                           ‫علــى ص (‪ )..‬مــن دفتــر التحقيــق لفــة (‪. )..‬‬\n     ‫‪ -4‬إقــرار زميلــه ‪ ......................... /‬املتضمنــة أنــه حصــل علــى اجلــوال‬\n     ‫نــوع ‪ .....‬كهديــة مــن املدعــى عليــه وأنــه شــاهده علــى ســيارة نــوع ‪.....‬‬\n                               ‫املــدون علــى ص (‪ )...‬مــن دفتــر التحقيــق لفــة (‪. )..‬‬\n     ‫‪ -5‬مــا أفــاد بــه زميلــه ‪ .......... /‬أنــه عنــد حضــوره لــه عنــد أحــد الشــقق‬\n     ‫كان بقيادتــه ســيارة نــوع ‪ ....‬املبلــغ عــن ســرقتها املدونــة علــى ص (‪)...‬‬\n                                                  ‫مــن دفتــر التحقيــق املرفــق لفــة (‪. )...‬‬\n     ‫‪ -6‬شــهادة الشــاهدين املنــوه عنهــا املــدون علــى ص (‪ )...‬مــن دفتــر‬\n                                                                      ‫التحقيــق لفــة (‪. )...‬‬\n\n\n‫‪51‬‬\n\f               ‫‪ -7‬محاولته الهرب من فرق دوريات األمن عند القبض عليه ‪.‬‬\n‫وببحــث ســوابقه اتضــح وجــود ســابقة مســجلة عليــه وهــي حيــازة‬\n                                                                        ‫مخــدرات ‪.‬‬\n‫وحيــث أن مــا أقــدم عليــه املدعــى عليــه فعــل محــرم ومعاقــب عليــه شــرعا‬\n‫أطلــب إثبــات مــا أســند إليــه واحلكــم عليــه بعقوبــة تعزيريــة تردعــه‬\n‫وتزجــره غيــره (علمــا بــان احلــق اخلــاص ال يــزال قائم ـاً) ‪ .‬هــذه دعــواي‬\n‫وبســؤال املدعــى عليــه عــن ماجــاء يف دعــوى املدعــي العــام قــال ماذكــره‬\n‫املدعــي العــام يف دعــواه كلــه غيــر صحيــح جملــه وتفصيــا هكــذا‬\n‫اجــاب فجــرى ســؤال املدعــي العــام هــل لديــة البينــة علــى ماجــاء يف‬\n‫دعــواه فقــال نعــم وســوف احضرهــا يف اجللســة القادمــة هكــذا اجــاب‬\n‫وعليــه قــررت رفــع اجللســة الــى يــوم الثالثــاء ‪..../../..‬ه ـ الســاعة التاســعة‬\n‫صباحــا وعليــه مت قفــل اجللســة يف متــام الســاعة (‪ )02،30‬وجــرى التوقيــع‬\n‫وبــاهلل التوفيــق وصلــى اهلل وســلم علــى نبينــا محمــد والــه وصحبــه‬\n                                                   ‫اجمعــن حــرر يف ‪...../../..‬ه ـ‬\n‫احلمــد هلل وحــده وبعــد يف يــوم االحــد ‪..../../..‬ه ـ ومتــام الســاعة (‪)11،00‬‬\n‫افتتحــت اجللســة اخلاصــة بدعــوى املدعــي العام ضــد ‪ ......................‬والتي‬\n‫ســبق وأن حــدد لهــا موعــدا يف يــوم الثالثــاء ‪..../../..‬ه ـ ولعــدم احضــار‬\n‫الســجني مت حتديــد هــذا املوعــد الســتكمال نظــر هــذه الدعــوى وفيهــا‬\n‫حضــر املدعــي العــام وقــرر قائــا لقــد احضــرت بينتــي التــي وعــدت بهــا‬\n‫يف اجللســة الســابقة فمعــي العســكري ‪ .......................‬ســعودي بالهويــة‬\n‫رقــم ‪....................‬وتاريــخ ميــاده ‪..../../..‬ه ـ والعســكري ‪....................‬‬\n‫ســعودي بالهويــة رقــم ‪ ..............‬وتاريــخ ميــاده ‪..../../..‬ه ـ واطلــب ســماع‬\n‫مالديهــم مــن شــهادة هكــذا قــرر وبســؤالهما عــن مالديهمــا شــهد كل‬\n\n\n                                                                                           ‫‪52‬‬\n\f     ‫ا لقــد كلفنــا مــن العمليــات بالتنســيق مــع املبلــغ بــأن‬        ‫واحــد منهمــا قائـ ً‬\n     ‫نقبــض علــى الشــخص املدعــى عليــه حيــث أنــة متهــم بســرقة جهــاز الب‬\n     ‫تــوب وانتقلنــا الــى املوقــع أســواق ‪ ....‬لالتصــاالت والحظنــا الشــخص‬\n     ‫أمــام احملــل وكان معــه اجلهــاز وأثنــاء مشــاهدته إلــى الدوريــه حــاول‬\n     ‫ارتــكاب الفــرار علــى االقــدام ولكــن مت ضبطــه داخــل احلــي ومعــه‬\n     ‫جهــاز الــاب تــوب اخلــاص بصاحــب ‪ .....‬وبعــد مقابلــة صاحــب اجلهــاز‬\n     ‫أفــاد بــأن جهــازه كان موجــود يف ســيارته ‪ ....‬هــذا مــا لــدي مــن شــهاده‬\n     ‫هكــذا شــهد كل واحــد منهمــا وجــرى تعديلهمــا مــن قبــل ‪................‬‬\n     ‫ســعودي بالهويــة‪ ..........................‬وتاريــخ امليــاد ‪..../../..‬ه ـ و‪..............‬‬\n     ‫ســعودي بالهوية‪..........‬وتاريــخ امليــاد ‪..../../..‬ه ـ وشــهد كل واحــد‬\n     ‫منهمــا قائــا اننــي اعــرف‪ ...............‬و‪ ...............‬وازكيهمــا وأعدلهمــا‬\n     ‫وهمــا مــن أهــل الصــاة هكــذا شــهد كل واحــد منهمــا فجــرى ســؤال‬\n     ‫املدعــي العــام هــل لديــه زيــادة بينــة علــى مــا أحضــر فقــال نعــم وســوف‬\n     ‫احضرهــا يف اجللســة القادمــة وعليــه قــررت رفــع اجللســة الــى يــوم االحــد‬\n     ‫‪..../../..‬ه ـ الســاعة التاســعة صباحــا وعليــه جــرى اجــرى قفــل اجللســة يف‬\n     ‫متــام الســاعة (‪ )11،30‬ومت التوقيــع وبــاهلل التوفيــق وصلــى اهلل وســلم‬\n     ‫علــى نبينــا محمــد والــه وصحبــه اجمعــن حــرر يف ‪..../../..‬ه ـ احلمــدهلل‬\n     ‫وحــده وبعــد ويف يــوم االربعــاء ‪..../../..‬ه ـ ومتــام الســاعة (‪)10،00‬‬\n     ‫افتتحــت اجللســة اخلاصــة بدعــوى املدعــي العــام ضــد املدعــى عليــه وفيهــا‬\n     ‫حضــر املدعــي العــام وقــرر قائــا لقــد أحضــرت بينتــي التــي وعــدت بهــا‬\n     ‫يف اجللســة الســابقة فمعــي ‪................‬ســعودي بالهويــة (‪)...................‬‬\n     ‫وتاريــخ امليــاد ‪..../../..‬ه ـ ويعمــل يف ‪ ....‬وأطلــب ســماع مالديــه هكــذا‬\n     ‫قــرر وبســؤاله عــن مالديــة شــهد قائــا أشــهد هلل تعالــى أنــه يف شــهر‬\n\n\n‫‪53‬‬\n\f‫رمضــان ويف منتصفــه تقريبــا كنــت أنــا و‪.......................‬و‪.....................‬‬\n‫مصــري اجلنســية يف مطعــم وجبــات ســريعه وبعــد خروجنــا مــن املطعــم‬\n‫وركوبنــا ســيارة ‪ .........‬ورد اتصــال هاتفــي علــى‪ ........‬مــن ‪................‬‬\n‫وقــد رأيــت رقــم جوالــه وطلــب مــن ‪ ..............‬احلضــور لتســليمه هديــة‬\n‫مــن ‪ .....‬وحــن وصولنــا خــرج ‪ ..........‬مــن شــقق مفروشــة وقــام بتســليم‬\n‫‪ ...........‬جهــاز جــوال نــوع ‪ ......‬وبعدهــا ركــب معنــا ‪ ...........‬وبعــد ثالثــة‬\n‫أيــام تقابلنــا انــا و‪ .....................‬وكان ‪ ......‬يســأل ‪..............‬عــن اجلــوال‬\n‫وكيفــه وعســاه مبســوط فيــه فشــكره ‪ ............‬علــى ذلــك هــذا مالــدي‬\n‫يف شــهادة هكــذا شــهد فجــرى ســؤال املدعــي العــام عــن مــن يعــدل‬\n‫الشــاهد فأحضــر ‪..............‬ســعودي بالهويــة (‪ )....................‬و‪.............‬‬\n‫ســعودي بالهويــة (‪ )..............‬وشــهد كل واحــد منهمــا بقولــه أننــي‬\n‫أزكــي الشــاهد وأشــهد أنــه مــن أهــل الصــاة وعــدل يف قولــه هكــذا‬\n‫شــهد كل واحــد منهمــا فجــرى ســؤال املدعــي العــام هــل لديــه زيــادة‬\n‫بينــة فقــال ليــس لــدي ســوى مــايف أوراق املعاملــة هــذا أجــاب وعليــه‬\n‫قــررت رفــع اجللســة حلــن احضــار الســجني يف يــوم االحــد ‪1434/4/7‬ه ـ‬\n‫الســاعة العاشــرة صباحــا ومت قفــل اجللســة يف متــام الســاعة (‪)10،30‬‬\n‫وجــرى التوقيــع وبــاهلل التوفيــق وصلــى اهلل وســلم علــى نبينــا محمــد والــه‬\n                                                   ‫وصحبــه اجمعــن حــرر يف ‪..../../..‬ه ـ‬\n‫احلمدهلل وحده وبعد يف يوم االربعاء ‪...../../..‬هـ ومتام الســاعة (‪)11،00‬‬\n‫افتتحــت اجللســة اخلاصــة بدعــوى املدعــي العام ضــد ‪ ......................‬وفيها‬\n‫حضــر املدعــي العــام وقــرر قائــا لقــد احضــرت بينتــي التــي وعــدت بهــا‬\n‫يف اجللســة الســابقة فمعــي الشــاهد ‪ ...................‬مصــري اجلنســية اقامــة‬\n‫رقــم (‪ ).......................‬واطلــب ســماع مالديــه مــن شــهادة هكــذا قــرر‬\n\n\n                                                                                               ‫‪54‬‬\n\f     ‫وبســؤاله عــن مالديــه مــن شــهاده فشــهد قائــا انــه يف احــد الليالــي‬\n     ‫ال أذكــر تاريخهــا خرجــت انــا وزميلــي ‪........‬و‪.............‬و‪...........‬للعشــاء‬\n     ‫يف أحــد املطاعــم وبعــد خروجنــا مــن املطعــم اتصــل ‪...............‬علــى‬\n     ‫زميلــي ‪ .............‬وطلــب ‪ ...........‬أن يقابــل ‪ ..............‬إلعطائــه هديــة جــوال‬\n     ‫وتواعــدا عنــد أحــد الشــقق بجــوار ‪.....‬وفعــا توجهنــا إلــى ‪ .......‬وقابلــه‬\n     ‫‪ .........‬واســتلم منــه اجلــوال ولــم أرى االســتالم والتســليم وبعدهــا ركــب‬\n     ‫‪ .............‬معنــا ثــم طلبــت مــن ‪ ....‬االتصــال علــى ‪ .............‬ملعرفــة مــن‬\n     ‫أيــن أحضــر اجلــوال ألن األجهــزه احلديثــة البــد أن يكــون معهــا كــرت‬\n     ‫ضمــان وهويــة اجلــوال الــذي بــه يبرمــج فاتصــل ‪ .........‬وســأل ‪ ..........‬عــن‬\n     ‫اجلــوال ‪ ...‬مــن ايــن حصــل عليــه فقــال ‪ ..........‬ان وضــع اجلهــاز يف الســليم‬\n     ‫ثــم انتهــت املكاملــة هــذا مالــدي مــن شــهادة هكــذا شــهد وجــرى تعديــل‬\n     ‫الشــاهد مــن قبــل ‪..................‬ســعودي بالهويــة رقــم (‪ ).............‬و‪..........‬‬\n     ‫ســعودي بالهويــة رقــم (‪ )..................‬وشــهد كل واحــد منهمــا قائــا‬\n     ‫اننــي أعــرف الشــاهد وهــو عــدل يف قولــه وأزكيــه ومــن أهــل الصــاة‬\n     ‫هكــذا شــهد كل واحــد منهمــا وجــرى ســؤال املدعــي العــام هــل لديــه‬\n     ‫زيــادة بينــة فقــال الزيــادة لــدي علــى مــا أحضــرت هكــذا أجــاب وعليــه‬\n     ‫قــررت رفــع اجللســة الــى يــوم االثنــن ‪..../../..‬ه ـ ومت قفــل هــذه اجللســة‬\n     ‫يف الســاعة (‪ )11،30‬ومت التوقيــع وبــاهلل التوفيــق وصلــى اهلل وســلم‬\n     ‫علــى نبينــا محمــد والــه وصحبــه اجمعــن حــرر يف ‪..../../..‬ه ـ احلمــدهلل‬\n     ‫وحــده وبعــد ويف يــوم االحــد ‪...../../..‬ه ـ ومتــام الســاعة (‪ )01،00‬افتتحت‬\n     ‫اجللســة اخلاصــة بدعــوى املدعــي العــام ضــد ‪ .................‬وفيهــا حضــر‬\n     ‫املدعــى عليــه ‪ ..............‬والــذي ســبق وان طلــب احضــاره مــن الســجن يــوم‬\n     ‫االحــد ‪..../../..‬ه ـ ويــوم االثنــن ‪..../../..‬ه ـ ولــم يتــم احضــاره ومت حتديــد‬\n\n\n‫‪55‬‬\n\f‫هــذا املوعــد الســتكمال نظــر هــذه الدعــوى فجــرى عــرض الشــهود‬\n‫وشــهادتهم علــى املدعــى عليــه والتــي ضبطــت يف اجللســات الســابقة‬\n‫فقــال امــا الشــهود فــا اعرفهــم وال اقــول فيهــم شــيء وامــا شــهادتهم‬\n‫غيــر صحيحــه هكــذا اجــاب وعليــه وبنــاء علــى ماتقــدم مــن الدعــوى‬\n‫واالجابــة ومــا احضــر املدعــي العــام مــن بينــة وبنــاء علــى املــادة رقــم ‪163‬‬\n‫مــن نظــام االجــراءات اجلزائيــة فقــد جــرى اطالعــي علــى اوراق املعاملــة‬\n‫فلــم اجــد فيهــا مــا يديــن املدعــى عليــه وان مــا احضــره املدعــي العــام‬\n‫مــن بينــة توصــل الــى التهمــة القويــة للمدعــى عليــه بســرقة جهــاز الــاب‬\n‫تــوب و‪ ....‬دون غيرهــا وبنــاء علــى املــادة رقــم ‪ 3‬مــن نظــام االجــرءات‬\n‫اجلزائيــة فقــد ثبــت لــدي ادانــة املدعــى عليــه بتوجــه التهمــة القويــة عليــه‬\n‫بســرقة اجلهــاز الالبتــوب وااليفــون املوصوفــة يف الدعــوى دون غيرهــا‬\n‫وحكمــت علــى املدعــى عليــه بجلــده ثالثمائــة جلــدة مفرقــة علــى فتــرات‬\n‫كل فتــرة خمســن جلــده بــن الفتــرة واألخــرى مــدة التقــل عــن اســبوع‬\n‫علــى أن يكــون عالنيــة ويف مجمــع ســوق ‪ .....‬وســجنه ثمانيــة أشــهر تبــدأ‬\n‫مــن تاريــخ ايقافــه وذلــك تعزيــرا لــه لقــاء مــا أديــن بــه وبعــرض احلكــم‬\n‫عليهمــا قــرر املدعــى عليــه القناعــة باحلكــم واملدعــي العــام عدمهــا‬\n‫وطلــب رفــع احلكــم حملكمــة االســتئناف مكتفيــا بالئحــة الدعــوى‬\n‫وعليــه جــرى فقــل اجللســة يف الســاعة (‪ )01،30‬ومت التوقيــع وبــاهلل‬\n‫التوفيــق وصلــى اهلل وســلم علــى نبينــا محمــد والــه وصحبــه اجمعــن‬\n                                                         ‫حــرر يف ‪1434/4/21‬ه ـ‬\n‫احلمــد هلل وحــده وبعــد ‪ ...‬فقــد اطلعنــا نحــن قضــاة الدائــرة الثانيــة‬\n‫لتمييــز القضايــا اجلزائيــة مبحكمــة االســتئناف بالريــاض علــى املعاملــة‬\n‫الــواردة مــن فضيلــة رئيــس احملكمــة اجلزائيــة بالريــاض برقــم ‪349603‬‬\n\n\n                                                                                        ‫‪56‬‬\n\f     ‫وتاريــخ ‪1434/6/12‬ه ـ املرفــق بهــا القــرار الصــادر مــن فضيلــة القاضــي‬\n     ‫باحملكمــة الشــيخ‪ .............../‬املســجل برقــم ‪ ......................‬وتاريــخ‬\n     ‫‪1434/4/21‬ه ـ اخلــاص بدعــوى املدعــي العــام ضــد ‪....................... /‬‬\n     ‫التهامــه بقضيــة ســرقة علــى النحــو املوضــح بالقــرار املتضمــن حكــم‬\n     ‫فضيلتــه مبــا هــو مــدون ومفصــل بــه وبدراســة القــرار وصــورة ضبطــه‬\n     ‫وأوراق املعاملــة قررنــا باألكثريــة املصادقــة علــى احلكــم مــع تنبيــه‬\n     ‫فضيلتــه خلتــم القــرار الشــرعي بختمــه الشــخصي ‪ .‬وبــاهلل التوفيــق‬\n                           ‫وصلــى اهلل علــى نبيــا محمــد وعلــى آلــه وصحبــه وســلم‪.‬‬\n\n\n\n\n‫‪57‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"d790af0e-7af1-509b-8d33-8ecc09f91096","source_page_start":47,"source_page_end":57,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"36b808d0e988ee539ddcc53a2ffdc36843f6e3e14f3583a49776a16c71819839","normalized_text_hash":"22288e423a68b93c717db4be277f67f09ddc6f6add7d2792bfbfda08c3fce267","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v25-p47-34194066"},{"id":"03bc4edc-46d4-5821-8b8f-1c7e305d61d2","document_type":"judgment","category":"judicial","subcategory":"general","title":"سرقة -سرقة جوال من املسجد النبوي -عدم وجود سوابق قضائية -مراعاة كبر السن والندم وإبداء التوبة يف التعزير -اعتبار حرمة املكان يف التعزير -ثبوت إدانة -تعزير بالسجن وأخذ التعهد -نصح وتوجيه اجلاني.","document_number":"35109290","case_number":"356163","judgment_number":null,"decision_number":null,"circular_number":null,"court":"محكمة الاستئناف","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1435/1/8","year":"1434","subject":"سرقة -سرقة جوال من املسجد النبوي -عدم وجود سوابق قضائية -مراعاة كبر السن والندم وإبداء التوبة يف التعزير -اعتبار حرمة املكان يف التعزير -ثبوت إدانة -تعزير بالسجن وأخذ التعهد -نصح وتوجيه اجلاني.","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"   ‫رقم الصك‪ 35109290:‬تاريخه ‪1435/1/8:‬هـ‬\n                       ‫رقم الدعوى ‪356163:‬‬\n     ‫رقم قرار التصديق من محكمة االستئناف ‪:‬‬\n            ‫‪ 35125668‬تاريخه ‪1435/01/24:‬هـ‬\n\n\n\n‫ســرقة ‪ -‬ســرقة جوال من املســجد النبوي ‪ -‬عدم وجود ســوابق قضائية‬\n‫‪ -‬مراعــاة كبــر الســن والنــدم وإبــداء التوبــة يف التعزيــر‪ -‬اعتبــار حرمــة‬\n‫املــكان يف التعزيــر‪ -‬ثبــوت إدانــة ‪ -‬تعزيــر بالســجن وأخــذ التعهــد‪ -‬نصــح‬\n                                                              ‫وتوجيــه اجلاني‪.‬‬\n\n\n\n\n‫‪ -‬قولــه صلــى اهلل عليــه وســلم ( كل املســلم علــى املســلم حــرام دمــه‬\n                                           ‫ومالــه وعرضــه )رواه مســلم‪.‬‬\n     ‫‪-‬الشريعة اإلسالمية جاءت بحفظ الكليات اخلمس ومنها املال ‪.‬‬\n\n\n\n\n‫الئحــة الدعــوى ضــد املدعــى عليــه مقيــم بطلــب اثبــات إدانتــه بســرقة‬\n‫جــوال مــن نــوع ‪ ....‬ألحــد األشــخاص أثنــاء نومــه باملســجد النبــوي‪،‬‬\n‫وطلــب تعزيــره‪،‬مت ضبــط املدعــى عليــه واعتــرف بالســرقة‪ ،‬تبــن عــدم‬\n‫وجــود ســوابق للمدعــى عليــه وهذاســبب يف تخفيــف العقوبــة ‪ ،‬اعتبــار‬\n‫حرمــة املــكان‪ ،‬وكبــر ســن املدعــى عليــه‪ ،‬ونــدم املدعــى عليــه وإبــداء‬\n‫توبتــه‪ ،‬تعزيــر املدعــى عليــه بالســجن وأخــذ التعهدمــع نصــح املدعــى‬\n‫عليــه وتوجيهــه مبــا يناســب املقــام‪ ،‬ومت تصديــق احلكــم مــن محكمــة‬\n                                                                ‫االســتئناف ‪.‬‬\n\n                                                                                   ‫‪58‬‬\n\f     ‫احلمــد هلل وحــده وبعــد فلــدي أنــا ‪ .................‬مســاعد رئيــس احملكمــة‬\n     ‫اجلزائيــة باملدينــة املنــورة افتتحــت اجللســة األولــى يف هــذا اليــوم اإلثنــن‬\n     ‫ـاء‬\n     ‫‪1435/01/08‬ه ـ يف متــام الســاعة الثالثــة والربــع بعــد الظهــر بنـ ً‬\n     ‫علــى املعاملــة احملالــة إلينــا بشــرح فضيلــة رئيــس احملكمــة اجلزائيــة‬\n     ‫برقــم (‪ )356163‬وتاريــخ ‪1435/01/02‬ه ـ واملقيــدة باحملكمــة‬\n     ‫برقــم (‪ )3529971‬وتاريــخ ‪1435/01/02‬ه ـ وفيهــا حضــر املدعــي‬\n     ‫العــام ‪ .................‬وقــدم الئحــة دعــواه ضــد املدعــى عليــه ‪.................‬‬\n     ‫باكســتاني اجلنســية مبوجــب رخصــة اإلقامــة رقــم (‪).................‬‬\n     ‫البالــغ مــن العمــر ‪ 74‬عام ـ ًا موقــوف منــذ تاريــخ القبــض عليــه يف‬\n     ‫‪1434/09/15‬هـ ـ وأحيــل للســجن العــام اســتناد ًا للقــرار الــوزاري رقــم‬\n     ‫ا يف دعــواه انتهــى التحقيــق‬       ‫(‪ )1900‬وتاريــخ ‪1428/07/09‬هـ ـ قائ ـ ً‬\n     ‫إلــى توجيــه االتهــام للمدعــى عليــه‪ ............‬بســرقة جــوال مــن نــوع ‪.....‬‬\n     ‫ألحــد األشــخاص أثنــاء نومــه باملســجد النبــوي وذلــك لألدلــة والقرائــن‬\n     ‫التاليــة ‪ /1 -:‬مــا جــاء بإعترافــه املــدون ص (‪ )1.10‬لفــة (‪ /2 )1‬مــا جــاء‬\n     ‫يف محضــر القبــض املــدون لفــة (‪ )2‬ص (‪ /3 )6‬مــا جــاء يف محضــر‬\n     ‫تنفيــذ املهمــة املرفــق لفــة رقــم (‪ )3‬وبالبحــث عــن ســوابقه لــم يعثــر لــه‬\n     ‫علــى ســوابق مســجلة عليــه وحيــث أن مــا أقــدم عليــه املتهــم املذكــور‬\n     ‫فعــل محــرم ومعاقــب عليــه شــرع ًا أطلــب إثبــات مــا أســند إليــه واحلكــم‬\n     ‫عليــه بعقوبــة تعزيريــة هكــذا ادعــى وبتــاوة دعــوى املدعــي العــام علــى‬\n     ‫املدعــى عليــه احلاضــر وبعــد التأكــد مــن هويتــه املشــار إليهــا أعــاه‬\n     ‫ا وهــو ينطــق بلغــة عربيــة مفهومــة مــا ذكــره املدعــي العــام‬‫أجــاب قائ ـ ً‬\n\n‫‪59‬‬\n\f‫مــن اتهامــي بســرقة جــوال مــن نــوع ‪ .....‬ألحــد األشــخاص أثنــاء نومــه‬\n‫باملســجد النبــوي فهــذا صحيــح وقــد أغوانــي الشــيطان وأنــا تائــب ونــادم‬\n‫ال إن شــاء اهلل هــذه إجابتــي هــذا‬     ‫علــى فعلــي و لــن أعــود ملثلــه مســتقب ً‬\n‫وقــد جــرى م ّنــا اإلطــاع علــى محضــر القبــض املــدون علــى صفحــة رقــم‬\n‫(‪ )6‬مــن دفتــر تقريــر األحــوال األمنيــة املوحــد املرفــق باملعاملــة لفــة رقــم‬\n‫(‪ )1‬وليــس كمــا ذكــره املدعــي العــام مــن وقوعــه علــى صفحــة رقــم‬\n‫(‪ )6‬مــن لفــة رقــم (‪ )2‬وعلــى مــا جــاء يف محضــر تنفيــذ املهمــة املرفــق‬\n‫ـاء علــى‬‫باملعاملــة لفــة رقــم (‪ )3‬فوجــدا كمــا ذكــر املدعــي العــام فبنـ ً‬\n‫مــا تقــدم مــن ســماع الدعــوى واإلجابــة ومــا قــرره الطرفــان ونظــر ًا إلــى‬\n‫أن املدعــى عليــه صــادق علــى مــا جــاء يف دعــوى املدعــي العــام والشــريعة‬\n‫اإلســامية جــأت بحفــظ الكليــات اخلمــس ومنهــا املــال ويف احلديــث‬\n‫(كل املســلم علــى املســلم حــرام دمــه ومالــه وعرضــه) رواه مســلم ونظــر ًا‬\n‫إلــى أن هــذا الفعــل وقــع يف املســجد النبــوي وهــو مــكان لــه شــرفه‬\n‫وحرمتــه ونظــر ًا إلــى كبــر ســن املدعــى عليــه وإبدائــه التوبــة والنــدم‬\n‫وخللـ ّـو صحيفتــه مــن الســوابق اجلنائيــة وجلميــع مــا تقــدم قــررت اآلتــي‬\n‫ـدي إدانــة املدعــى عليــه ‪ .................‬بســرقة جــوال مــن نــوع‬ ‫أو ًال ثبــت لـ ّ‬\n‫‪ ....‬ألحــد األشــخاص أثنــاء نومــه باملســجد النبــوي ثاني ـ ًا ســجن املدعــى‬\n‫عليــه مــدة ثالثــة أشــهر يحتســب منهــا مــدة إيقافــه بســبب هــذه الدعــوى‬\n‫ال‬‫وأخــذ التعهــد املشــدد عليــه وإنــذاره مــن العــود ملثــل مــا بــدر منه مســتقب ً‬\n‫تعزيــر ًا لــه علــى مــا أديــن بــه املنصــوص عليــه يف أو ًال مــن ســرقته جــوال‬\n‫مــن نــوع ‪ .....‬ألحــد األشــخاص أثنــاء نومــه باملســجد النبــوي هــذا مــا‬\n‫ظهــر لــي وبــه حكمــت ألجــل احلــق العــام وجــرى نصــح وتوجيــه املدعــى‬\n‫عليــه مبــا يناســب املقــام وبإعــان احلكــم قــرر املدعــى عليــه القناعــة بــه‬\n\n\n                                                                                            ‫‪60‬‬\n\f     ‫وأبــدى املدعــي العــام إعتراضــه علــى احلكــم وطلــب رفعــه إلــى محكمة‬\n     ‫اإلســتئناف بــدون الئحــة إعتراضيــة وأمــرت برفــع احلكــم مــع كامــل‬\n     ‫متعلقاتــه إلــى محكمــة اإلســتئناف لتدقيقــه حســب املتبــع وأقفلــت‬\n     ‫اجللســة يف متــام الســاعة الثالثــة والنصــف بعــد الظهــر وعلــى مــا تقــدم‬\n     ‫حصــل التوقيــع وصلــى اهلل وســلم علــى نبينــا محمــد وعلــى الــه وصحبــه‬\n                                                 ‫أجمعــن حــرر يف ‪1435/01/08‬هــ‪.‬‬\n     ‫احلمــد هلل وحــده والصــاة والســام علــى مــن ال نبــي بعــده ‪ :‬وبعــد‬\n     ‫بنــاء علــى املعاملــة الــواردة مــن احملكمــة اجلزائيــة باملدينــة املنــورة‬\n     ‫برقــم ‪ 35115353‬وتاريــخ ‪1435/1/17‬ه ـ واحملالــة لنــا مــن فضيلــة‬\n     ‫رئيــس محكمــة االســتئناف باملدينــة املنــورة برقــم ‪ 3547896‬وتاريــخ‬\n     ‫‪1435/1/22‬ه ـ فقــد جــرى منــا نحــن رئيــس وأعضــاء الدائــرة اجلزائيــة‬\n     ‫األولــى يف محكمــة االســتئناف مبنطقــة املدينــة املنــورة االطــاع علــى‬\n     ‫القــرار الشــرعي رقــم ‪ 35109290‬وتاريــخ ‪1435/ 1/8‬ه ـ الصــادر مــن‬\n     ‫فضيلــة الشــيخ ‪ ................./‬القاضــي يف احملكمــة اجلزائيــة باملدينــة‬\n     ‫املتضمــن دعــوى املدعــي العــام ضــد ‪ ................. /‬املتهــم يف قضيــة ســرقة‬\n     ‫مــال خــاص احملكــوم فيــه مبــا دون باطنــه ‪ ،‬وبدراســة القــرار وصــورة‬\n     ‫ضبطــه تقــررت املوافقــة علــى احلكــم واهلل املوفــق وصلــى اهلل علــى‬\n                                          ‫نبينــا محمــد وعلــى آلــه وصحبــه وســلم ‪.‬‬\n\n\n\n\n‫‪61‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"d790af0e-7af1-509b-8d33-8ecc09f91096","source_page_start":58,"source_page_end":61,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"21dcc2d9a8b2082fc2f236cff02e6e8f22d1366a7520240e9bcde9e6e49b199a","normalized_text_hash":"32086ec1d7cc7676f8147f2acd87453b6337a14a534db8081713d953647c39f8","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v25-p58-35109290"},{"id":"fae07ee2-70f3-51df-baf2-4feec37df094","document_type":"judgment","category":"judicial","subcategory":"general","title":"سرقة -سرقة محل جتاري -سرقة مبلغ مالي وبطاقات اتصال مسبقة الدفع -اقرار حتقيق ا -رجوع عن إقرار -طلب إقامة حد السرقة -درء حد السرقة -تعزير بالسجن واجللد.","document_number":"33481065","case_number":"3333634","judgment_number":null,"decision_number":null,"circular_number":null,"court":"المحكمة العامة بالباحة و","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1433/12/28","year":"1434","subject":"سرقة -سرقة محل جتاري -سرقة مبلغ مالي وبطاقات اتصال مسبقة الدفع -اقرار حتقيق ا -رجوع عن إقرار -طلب إقامة حد السرقة -درء حد السرقة -تعزير بالسجن واجللد.","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"   ‫رقم الصك‪ 33481065 :‬تاريخه ‪1433/12/28:‬هـ‬\n                         ‫رقم الدعوى‪3333634:‬‬\n‫رقم قرار التصديق من محكمة االستئناف ‪3450181:‬‬\n                        ‫تاريخه ‪1434/02/30:‬ه‬\n\n\n\n    ‫ســرقة ‪ -‬ســرقة محــل جتــاري ‪ -‬ســرقة مبلــغ مالــي وبطاقــات اتصــال‬\n    ‫مســبقة الدفــع ‪ -‬اقــرار حتقيق ـ ًا‪ -‬رجــوع عــن إقــرار‪ -‬طلــب إقامــة حــد‬\n                     ‫الســرقة‪ -‬درء حــد الســرقة‪ -‬تعزيــر بالســجن واجللــد‪.‬‬\n\n\n\n\n    ‫‪ -‬قولــه صلــى اهلل عليــه وســلم ( كل املســلم علــى املســلم حــرام دمــه‬\n                                                           ‫ومالــه وعرضــه ) ‪.‬‬\n\n\n\n\n    ‫دعــوى املدعــي العــام ضــد املدعــى عليــه بســرقة مبلــغ مالــي وعــدد مــن‬\n    ‫بطاقــات االتصــال املســبقة الدفــع وطلــب إقامــة حــد الســرقة ‪،‬لــذا مت‬\n    ‫القبــض علــى املدعــى عليــه بعــد اإلبــاغ مــن أحــد األشــخاص يفيــد‬\n    ‫بتعــرض محلــه التجــاري للســرقة وبعــد البحــث والتحــري قبــض علــى‬\n    ‫املدعــى عليــه وباســتجوابه أقــر بالســرقة املنســوبة إليــه ‪ ،‬وأنكر املدعى‬\n    ‫عليــه الدعــوى ‪،‬وأحضــر املدعــى العــام شــهود ًا أفــادوا برؤيتهــم للمدعــى‬\n    ‫عليــه أثنــاء الســرقة‪ ،‬ولوجــود إقــرار حتقيق ـ ًا للمدعــى عليــه‪ ،‬ولرجــوع‬\n    ‫املدعــى عليــه عــن إقــراره ‪ ،‬فقــد تقــرر لــدى ناظــري القضيــة أن البينــات‬\n    ‫املقدمــة مــن املدعــى العــام غيــر موصلــة إلثبــات اإلدانــة وإمنــا تفيــد توجيــه‬\n    ‫التهمــة للمدعــى عليــه‪ ،‬لذلــك مت درء حــد الســرقة عــن املدعــى عليــه ‪،‬‬\n\n                                                                                              ‫‪62‬‬\n\f     ‫وتعزيــر املدعــى عليــه بالســجن واجللــد ‪ ،‬وتصديــق احلكــم مــن محكمــة‬\n                                                                 ‫االســتئناف ‪.‬‬\n\n\n\n\n     ‫احلمــد هلل وحــده والصــاة والســام علــى مــن ال نبــي بعــده وبعــد لدينــا‬\n     ‫نحــن ‪ .......‬باحملكمــة العامــة بالباحــة و‪ ......‬القاضــي باحملكمــة العامــة‬\n     ‫بالباحــة و‪.......‬القاضــي باحملكمــة العامــة بالباحــة وبنــاء علــى املعاملــة‬\n     ‫الــواردة إلينــا مــن هيئــة التحقيــق واالدعــاء العــام بالباحــة برقــم ه ـ‬\n     ‫ب‪ 3484/2/1‬يف ‪1433/5/10‬هـ واملقيدة باحملكمة برقم ‪33906628‬‬\n     ‫يف ‪1433/5/15‬ه ـ واحملالــة إلينــا مــن فضيلــة الرئيس برقم ‪33333634‬‬\n     ‫يف ‪1433/5/15‬ه ـ ويف يــوم الســبت املوافــق ‪1433/5/17‬ه ـ افتتحــت‬\n     ‫اجللســة األولــى الســاعة العاشــرة وفيهــا حضــر املدعــي العــام ‪ ........‬حامــل‬\n     ‫الســجل املدنــي رقــم (‪ )......‬مبوجــب التكليــف رقــم ه ـ ‪ 1/5978/8‬يف‬\n     ‫‪1430/12/28‬ه ـ وقــدم الئحــة الدعــوى العامــة رقــم ‪ 201‬لعــام ‪1433‬ه ـ‬\n     ‫واملرفقــة باملعاملــة علــى شــريط ســي دي والتــي جــاء فيهــا مــا نصــه أدعــي‬\n     ‫علــى ‪ ......‬باكســتاني اجلنســية مبوجــب اإلقامــة رقــم ‪2302267352‬‬\n     ‫العمــر ‪ 29‬عامــا ومهنتــه عامــل زراعــي موقــوف مبوجــب األمــر رقــم ‪159‬‬\n     ‫وتاريــخ ‪1432/12/29‬ه ـ بالســجن العــام بالباحــة ويف صباح يوم األربعاء‬\n     ‫املوافــق ‪1432/12/27‬ه ـ وعنــد متــام الســاعة الثامنــة والربــع تلقــت‬\n     ‫شــرطة الباحــة بــاغ املواطــن‪ ..... /‬املتضمــن تعــرض املتجــر العائــد‬\n     ‫ملكيتــه لــه واملعــروف باســم(‪ )............‬للســرقة حيــث أبلغــه العامــل‬\n     ‫باحملــل أنــه عنــد حضــوره للمحــل صباح ـ ًا وجــده قــد تعــرض للســرقة‬\n     ‫وكان درج حفــظ املبالــغ املاليــة مكســور ًا وســرق منــه مبلــغ مالــي يقــدر‬\n\n‫‪63‬‬\n\f‫بحوالــي خمســة وأربعــن ألــف ريــال وعــدد مــن بطاقــات الشــحن مســبقة‬\n‫الدفــع وكان قفــل البــاب الســحاب اخلارجــي مــن اجلهــة الغربيــة‬\n‫مكســور ًا وكذلــك زجــاج البــاب الداخلــي وباالنتقــال واملعاينــة للموقــع‬\n‫تبــن أنــه متجــر باســم(‪ )...............‬ويقــع علــى الشــارع العــام مبدينــة ‪.....‬‬\n‫مقابــل فنــدق‪ ......‬وهــو متجــر متوســط احلجــم لــه ثــاث فتحــات األولــى‬\n‫والثانيــة مقفلتــان والثالثــة مدخــل رئيســي للمتجــر ومبعاينتــه تبــن أن‬\n‫الفتحــة األولــى تعــرض ســياجها احلديــدي لنــزع القفــل وســحب الســياج‬\n‫احلديــدي ومــن ثــم متكــن اجلانــي مــن الدخــول بعــد تكســير زجــاج تلــك‬\n‫الفتحــة وبالتوجــه إلــى طاولــة احملاســبني تبــن ان اجلانــي قــام بعتــل‬\n‫اإلدراج بآلــة حــادة ومتكــن مــن فتــح الــدرج األول وســرقة بطاقــات‬\n‫الشــحن الهاتفيــة (حســب إفــادة املبلــغ) ومتكــن بعــد ذلــك مــن عتــل الدرج‬\n‫الثانــي والثالــث وســرق منهــا مبلــغ خمســة وأربعــن ألــف ريــال (حســب‬\n‫إفــادة املبلــغ) ولــم يعثــر علــى القفــل الــذي مت قصــه ووجــدت آثــار تهشــيم‬\n‫الزجــاج داخــل احملــل ومت تصويــر املوقــع ورفــع آثــار البصمــات مــن قبــل‬\n‫اخلبــراء باألدلــة اجلنائيــة وبتاريــخ ‪1432/12/28‬ه ـ حضــر لشــرطة مدينــة‬\n‫الباحــة املبلــغ ومعــه شــاهد علــى قيــام أحــد األشــخاص بســرقة احملــل‬\n‫وبســماع أقــوال الشــاهد ويدعــي ‪ .....‬هنــدي اجلنســية مســلم الديانــة‬\n‫مبوجــب رخصــة اإلقامــة رقــم ‪ ......‬والــذي يعمــل مبطعــم الريــان القريــب‬\n‫مــن الســوبر ماركــت حيــث أفــاد أن عملــه يبــدأ مــن الســاعة الثامنــة‬\n‫ـاء وحتــى الســاعة الواحــدة والنصــف صباحـ ًا وأنــه أثنــاء خروجــه مــن‬      ‫مسـ ً‬\n‫املطعــم وانتظــاره ملديــر املطعــم خارج ـ ًا ليقــوم بإيصالــه للمنــزل الحــظ‬\n‫شــخصا يرتــدي الــزي الباكســتاني وبيــده مطرقــة (شــاكوش) ويقــوم‬\n‫بتكســير زجــاج ســوبر ماركــت ‪ ......‬فقــام بالصيــاح عليــه وهــرب ونــزل‬\n\n\n                                                                                          ‫‪64‬‬\n\f     ‫مــن درج مالصــق لنفــس مبنــى الســوبر ماركــت املســروق يــؤدي إلــى‬\n     ‫البــدروم وقــد كان ذلــك الباكســتاني يعــرج حيــث إن إحــدى قدميــه‬\n     ‫بهــا كســر أو مــا شــابه ذلــك ويف اليــوم التالــي قــام بإبــاغ الوافــد‪..... /‬‬\n     ‫هنــدي اجلنســية والــذي يعمــل يف نفــس الســوبر ماركــت وعندمــا قابــل‬\n     ‫صاحــب الســوبر ماركــت أحضــر شــخصا باكســتاني اجلنســية وطلــب‬\n     ‫منــه إصــاح أعطــال يف احملــل وتأكــد لــه أنــه هــو الشــخص الــذي قــام‬\n     ‫بتكســير زجــاج احملــل وقــد تبــن أنــه املتهــم املذكــور وبســماع أقــوال‬\n     ‫املتهــم املذكــور أنكــر التهمــه املنســوبة إليــة كمــا أنكر صحة شــهادة‬\n     ‫الشــاهد وباســتجواب املتهــم ‪ .....‬أنكــر مــا نســب إليــه وعــدم صحــة‬\n     ‫شــهادة الشــاهد ومبواجهتــه بالشــاهد اســتطاع التعــرف عليــه وبعــد‬\n     ‫نصحــه إلــى قــول احلقيقــة ومخافــة اهلل عــدل عــن إنــكاره وأقــر بســرقة‬\n     ‫احملل ومبشــاركة أحد األشــخاص له ويدعى ‪ ......‬باكســتاني اجلنســية‬\n     ‫وبإعــادة اســتجوابه أقــر أنــه يف يــوم الثالثــاء املوافــق ‪1432/12/26‬ه ـ‬\n     ‫اتفــق مــع ‪ .....‬باكســتاني اجلنســية علــى ســرقة ســوبر ماركــت ‪ ......‬علــى‬\n     ‫أن يقــوم هــو بكســر البــاب و‪ .....‬يقــوم بالدخــول بعــد ذلــك والســرقة‬\n     ‫وعنــد متــام الســاعة الواحــدة والنصــف مــن فجــر يــوم األربعــاء املوافــق‬\n     ‫‪1432/12/27‬ه ـ قــام بالصعــود للســوبر ماركــت وباشــر كســر قفــل‬\n     ‫البــاب احلديــدي الســحاب مبطرقــة كانــت معــه وزجــاج البــاب الداخلــي‬\n     ‫ثــم نــزل بعــد أن شــاهده أحــد األشــخاص وقــام بالصيــاح وقــام رفيقــه ‪.....‬‬\n     ‫بإكمــال دوره حيــث صعــد إلــى احملــل وقــام بســرقة مبالــغ ماليــة ال يعلــم‬\n     ‫مقدارهــا وكذلــك بطاقــات اتصــال مســبقة الدفــع وســلمها لــه وقــام هــو‬\n     ‫بــدوره بوضعهــا يف كيــس وربطهــا وســلمها لــ‪ .....‬الــذي أخفاهــا يف‬\n     ‫مزرعــة بالقــرب مــن ســكنهما واســتعد بالداللــة علــى مــكان إخفــاء‬\n\n\n‫‪65‬‬\n\f‫املســروقات حســب مــا ذكــر لــه ‪ .......‬وباالنتقــال مــع املتهــم ملوقــع املزرعة‬\n‫الــذي ذكــره مت الدخــول للمزرعــة عبــر بــاب خشــبي وتبــن أنهــا مزرعــة‬\n‫خضــروات وبهــا غرفــة مهجــورة علــى ميــن املدخــل وبها خــردوات وبجانب‬\n‫البــاب مــن اخلــارج يوجــد ثالجــة ال تعمــل متوســطة احلجــم وبتفتيــش املوقع‬\n‫تفتيش ـ ًا دقيق ـ ًا عثــر علــى كيــس بالســتيك بداخــل الثالجــة يف الــدرج‬\n‫الســفلي ومت إحضــار فرقــة مــن األدلــة اجلنائيــة ومت رفــع اآلثــار مــن املوقــع‬\n‫وإخــراج الكيــس مــن داخــل الثالجــة وتفريغــه يف كيــس آخــر بعــد أن‬\n‫مت حتريــز الكيــس املضبوطــة بداخلــة املســروقات وقــد عثــر بداخــل‬\n‫الكيــس علــى مبلــغ مــن املــال مقــداره ‪ 36.370‬ســتة وثالثــون الف ًا وثالث‬\n‫مائــه وســبعون ريــا ًال وعلــى ‪ 321‬ثــاث مائــة وواحــدة وعشــرين بطاقــة‬\n‫اتصــال مســبقة الدفــع وبتاريــخ ‪1433/1/4‬ه ـ مت القبــض علــى املتهــم‬\n‫‪ ......‬باكســتاني اجلنســية وباســتجوابه أنكــر جميــع مــا نســب إليــه‬\n‫وذكــر أنــه وقــت وقــوع الســرقة احملــدد كان موجــود ًا يف غرفتــه مــع‬\n‫شــخصني مــن نفــس اجلنســية ومســتعد بإحضارهمــا ومبناصحتــه أصــر‬\n‫علــى إنــكاره صــدر بحقــه أمــر حفــظ االتهــام لعــدم كفايــة األدلــة ضــده‬\n‫وبســماع شــهادة كل مــن ‪ ..... /‬اجلنســية مبوجــب رخصــة اإلقامــة رقــم‬\n‫(‪ )....‬و ‪.....‬باكســتاني اجلنســية مبوجــب رخصــة اإلقامــة رقــم (‪)......‬‬\n‫شــهدا بــأن ‪ ....‬يســكن معهمــا يف غرفــة واحــدة ولــم يغــادر غرفتهــم وقــت‬\n‫وقــوع الســرقة حتــى صبــاح اليــوم التالــي وقــد ورد التقريــر الفنــي‬\n‫للبصمــات رقــم (‪ )1/3‬لعــام ‪1433‬ه ـ املتضمــن أنــه مبضاهــاة بصمــات‬\n‫املتهمــن املذكوريــن علــى أثــر البصمــة الصالــح للمقارنــة اتضــح أنهــا ال‬\n‫تنطبــق كمــا ورد تقريــر الفحــوص احليويــة رقــم (‪/294‬فحــوص وراثيــة)‬\n‫لعــام ‪1433‬ه ـ املتضمــن عــدم وجــود تطابــق جنائــي مــع أي قضايــا‬\n\n\n                                                                                        ‫‪66‬‬\n\f     ‫للعينتــن القياســيتني للمتهمــن وبالبحــث عــن ســوابقه لــم يعثــر لــه علــى‬\n     ‫ســوابق مســجله وقــد انتهــى التحقيــق إلــى اتهــام ‪ .....‬بســرقة مبلــغ يقــدر‬\n     ‫بحوالــي خمســة وأربعــون ألــف ريــال وعــدد مــن بطاقات االتصال مســبقة‬\n     ‫الدفــع وذلــك لألدلــة والقرائــن التاليــة‪1:‬ـ اعترافــه املنــوه عنــه املــدون ص‬\n     ‫(‪ )3‬مــن دفتــر التحقيــق رقــم (‪ )4‬املرفــق لفــة رقــم (‪2 )93‬ـ مــا جــاء يف‬\n     ‫شــهادة ‪ ..... /‬ومواجهتــه باملتهــم املنــوه عنهــا املدونــة ص (‪ )4‬مــن دفتــر‬\n     ‫التحقيــق اجلنائــي لفــة (‪ )9‬وص(‪ )6‬مــن دفتــر التحقيــق رقــم(‪ )1‬املرفــق‬\n     ‫لفــة (‪3 )16‬ـ مــا جــاء مبحضــر االنتقــال واملعاينــة املنــوه عنــه أعــاه املــدون‬\n     ‫ص (‪ 2‬ــ‪ )3‬مــن ملــف التحقيــق اجلنائــي املرفــق لفــة (‪4 )1‬ـ مــا جاء مبحضر‬\n     ‫االنتقــال واملعاينــة والداللــة واإلرشــاد علــى مــكان املســروقات وضبطهــا‬\n     ‫املنــوه عنــه أعــاه املــدون ص (‪ 5‬ــ‪ )6‬مــن دفتــر التحقيــق رقــم (‪ )2‬املرفــق‬\n     ‫لفــة (‪5 )20‬ـ مــا جــاء بالتقاريــر اجلنائيــة املصــورة املرفقــة لفــه(‪)32-24‬‬\n     ‫ولفــه (‪ )96-88‬وحيــث إن مــا أقــدم عليــه املذكــور وهــو بكامــل أهليتــه‬\n     ‫املعتبــرة شــرع ًا فعــل محــرم ومعاقــب عليــه شــرع ًا وهــو ســرقة مــال‬\n     ‫محتــرم مــن حــرزه بعــد هتكــه يزيــد عــن النصــاب ال شــبهة لــه فيــه لــذا‬\n     ‫أطلــب إثبــات إدانتــه شــرع ًا مبــا أســند إليــه واحلكــم عليــه بحــد الســرقة‬\n     ‫الــوارد يف اآليــة الكرميــة رقــم (‪ )38‬مــن ســورة املائــدة علم ـ ًا أن احلــق‬\n     ‫اخلــاص انتهــى باســتالم املدعــي باحلــق اخلــاص جلميــع املســروقات وتنازلــه‬\n     ‫عــن حقــه اخلــاص وعــدم رغبتــه مواصلــة دعــواه وبــاهلل التوفيــق هكــذا‬\n     ‫ادعــى وبعــرض مــا جــاء يف دعــوى املدعــي العــام علــى املدعــى عليــه‬\n     ‫وســؤاله عنهــا عــن طريــق املترجــم املتعــاون مــع احملكمــة املدعــو ‪.....‬‬\n     ‫هنــدي اجلنســية مبوجــب رخصــة اإلقامــة الصــادرة مــن الباحــة رقــم (‪).....‬‬\n     ‫أجــب قائــا مــا جــاء يف دعــوى املدعــي العــام مــن اتهامــي بســرقة مبلــغ‬\n\n\n‫‪67‬‬\n\f‫يقــدر بحوالــي خمســة وأربعــون ألــف ريــال وعــدد مــن بطاقــات االتصــال‬\n‫مســبقة الدفــع وأننــي قمــت بســرقة احملــل املذكــور بالدعــوى كلــه غيــر‬\n‫صحيــح وأنــا كنــت يف مكــة وقدمــت إلــى الباحــة يف يــوم األربعــاء‬\n‫الســاعة العاشــرة مســاء ولــم أكــن وقــت الســرقة موجــودا باملنطقــة هــذه‬\n‫إجابتــي وبســؤال املدعــي العــام هــل لديــك بينــة أجــاب قائــا لــدي شــهود‬\n‫أطلــب إمهالــي إلحضارهــم ومــا يف أوراق املعاملــة هكــذا أجــاب ثــم‬\n‫رفعــت اجللســة إلمهالــه إلــى يــوم األثنــن املوافــق ‪1433/5/24‬ه ـ الســاعة‬\n‫العاشــرة ويف املوعــد احملــدد افتتحــت اجللســة وفيهــا حضــر املدعــي العــام‬\n‫واملدعــى عليــه واملترجــم ‪ ......‬وبســؤال املدعــي العــام عــن بينتــه التــي وعــد‬\n‫بهــا أحضــر للشــهادة املدعــو ‪ ......‬هنــدي اجلنســية مبوجب رخصــة اإلقامة‬\n‫الصــادرة مــن جــوازات الريــاض برقــم (‪ ).....‬وبســؤاله عمــا لديــه مــن‬\n‫شــهادة عــن طريــق املترجــم عــرف بنفســه بأنــه هنــدي اجلنســية ومــن‬\n‫مواليــد عــام ‪1986‬ه ـ ويعمــل بــإدارة ســجون املنطقــة عامــل نظافــة ويف‬\n‫املســاء يعمــل يف مطعــم ‪ ......‬وال يعــرف املدعــى عليــه وليــس لــه بــه أي‬\n‫عالقــة ثــم شــهد قائــا أشــهد أنــه يف أحــد األيــام ال أتذكــر التاريــخ‬\n‫كنــت خارجــا مــن مطعــم ‪ ......‬الســاعة الواحــدة والنصــف مســاء فرأيــت‬\n‫شــخصا يقــوم بكســر بــاب البقالــة املجــاورة للمطعــم بحديــدة أو‬\n‫شــاكوش فتوجهــت إليــه ألمســك بــه فهــرب ولــم أمتكــن مــن رؤيــة وجهــه‬\n‫إال أننــي رأيتــه يعــرج يف مشــيته هكــذا شــهد وبعــرض مــا جــاء يف شــهادة‬\n‫الشــاهد علــى املدعــى عليــه عــن طريــق املترجــم أجــاب بقولــه مــا جــاء يف‬\n‫شــهادته كلــه غيــر صحيــح وأمــا الشــاهد فــا يعرفــه هكــذا أجــاب‬\n‫عــن طريــق املترجــم كمــا أحضــر املدعــي العــام للشــهادة املدعــو ‪......‬‬\n‫ســعودي اجلنســية مبوجــب الســجل املدنــي رقــم (‪ ).....‬وبســؤاله عمــا لديــه‬\n\n\n                                                                                         ‫‪68‬‬\n\f     ‫من شــهادة عرف بنفســه بأنه من مواليد عام ‪1403‬هـ ويعمل بالدوريات‬\n     ‫األمنيــة بالباحــة برتبــة عريــف ويســكن مبحافظــة ‪ .......‬وال يعــرف‬\n     ‫املدعــى عليــه وليــس لــه بــه عالقــة ثــم شــهد قائــا أشــهد أنــه يف أحــد‬\n     ‫األيــام وردنــا بــاغ عــن تعــرض أحــد احملــات للســرقة فانتقلــت مــع أحــد‬\n     ‫ضبــاط امليــدان للمحــل فوجدنــا أحــد أبــواب احملــل غيــر البــاب الرئيســي‬\n     ‫قــد كســر زجاجــه والقفــل غيــر موجــود وبالدخــول اتضــح أن درج‬\n     ‫احملاســب املعــد مــن األملنيــوم مكســور وليــس فيــه شــيء هــذا مــا لــدي‬\n     ‫وبــه أشــهد وبعــرض مــا جــاء يف شــهادته علــى املدعــى عليــه أجــاب عــن‬\n     ‫طريــق املترجــم قائــا مــا جــاء يف الشــهادة ال أعلــم عنــه ألننــي لــم أســرق‬\n     ‫احملــل ولــم أتعــرض لــه هكــذا أجــاب وبســؤال املدعــي العــام هــل لديــك‬\n     ‫مزيــد بينــة أجــاب قائــا نعــم لــدي شــهادة‪ .....‬و ‪ ........‬علمــا بأنــه بطلــب‬\n     ‫الشــاهد الثانــي وردنــا خطــاب مديــر شــرطة املدينــة املتضمــن أن‬\n     ‫املذكــور لديــه دورة ملــدة إحــدى عشــر شــهرا يف مدينــة الريــاض مــن‬\n     ‫بدايــة هــذا العــام ولــذا فإننــي أطلــب الرجــوع إلــى شــهادته املدونــة‬\n     ‫باملعاملــة وإمهالــي إلحضــار الشــاهد اآلخــر هكــذا أجــاب ثــم رفعــت‬\n     ‫اجللســة إلمهالــه إلــى يــوم األثنــن املوافــق ‪1433/6/9‬ه ـ الســاعة التاســعة‬\n     ‫ويف اليــوم احملــدد افتتحــت اجللســة وفيهــا حضــر املدعــي العــام واملدعــى‬\n     ‫عليــه ولــم يحضــر املترجــم ثــم أحضــر املدعــي العــام للشــهادة املدعــو ‪.....‬‬\n     ‫ســعودي اجلنســية مبوجــب الســجل املدنــي رقــم (‪ )......‬وبســؤاله عمــا لديه‬\n     ‫مــن شــهادة عــرف بنفســه بأنــه مــن مواليــد عــام ‪ ......‬ويســكن بالباحــة‬\n     ‫ويعمــل ‪ ........................................................‬وليــس لــه أي عالقــة أو صلــة‬\n     ‫باملدعــى عليــه ثــم شــهد قائــا أنــه يف أحــد األيــام ال أتذكــر التاريــخ‬\n     ‫بالضبــط انتقلــت مــع احملقــق مــن هيئــة التحقيــق ومعنــا املدعــى عليــه‬\n\n\n‫‪69‬‬\n\f‫وتوجــه بنــا املدعــى عليــه إلــى محــل إقامتــه ثــم انتقلنــا إلــى مزرعــة يف‬\n‫الباحــة حتــت احملــل املســروق وقمنــا بالبحــث عــن املســروقات داخــل‬\n‫الغرفــة املوجــودة باملزرعــة فوجدنــا املســروقات يف ثالجــة تالفــة وهــي‬\n‫مبلــغ مالــي ال أعلــم قــدره وبطاقــات شــحن للجــواالت هــذا مــا لــدي وبــه‬\n‫أشــهد كمــا أحضــر املدعــي العــام كال مــن ‪ ......‬بنغالديشــي اجلنســية‬\n‫مبوجــب رخصــة اإلقامــة الصــادرة مــن جــوازات الريــاض برقــم (‪ )......‬و‬\n‫‪ ......‬بنغالديشــي اجلنســية مبوجــب رخصــة اإلقامــة الصــادرة مــن جــوازات‬\n‫الريــاض ‪ ........‬وهمــا يجيــدان التحــدث باللغــة العربيــة وبســؤالهما عمــا‬\n‫لديهمــا شــهدا بــأن الشــاهد املدعــو ‪ ........‬معــروف لديهــم وأنــه عــدل‬\n‫هكــذا شــهدا فســألنا املدعــي العــام هــل لديــه مزيــد بينــة فأجــاب قائــا‬\n‫ليــس لــدي ســوى مــن أحضــرت ومــا يف أوراق املعاملــة هكــذا أجــاب‬\n‫فأفهــم بإحضــار مزكــي للشــاهد الثانــي فاســتعد بذلــك ثــم رفعــت‬\n‫اجللســة إلحضــار املترجــم وعــرض مــا جــاء يف شــهادة الشــاهد علــى‬\n‫املدعــى عليــه عــن طريقــه ورفعــت اجللســة لذلــك إلــى يــوم األثنــن املوافــق‬\n‫‪1433/7/28‬ه ـ الســاعة التاســعة ويف املوعــد احملــدد افتتحــت اجللســة‬\n‫وفيهــا حضــر املدعــي العــام واملدعــى عليــه واملترجم ‪ .....‬ويف هذه اجللســة‬\n‫جــرى عــرض مــا جــاء يف شــهادة الشــاهد املدونــة بجلســة ســابقة علــى‬\n                                                                     ‫املدعى عليه‬\n‫احلمــد هلل وحــده وبعــد ويف يــوم االثنــن املوافــق ‪1433/5/24‬ه ـ افتتحــت‬\n‫اجللســة الثانيــة الســاعة الثانيــة عشــرة نظــرا للتأخــر يف اجللســة الســابقة‬\n‫وفيهــا حضــر املدعــي العــام واملدعــى عليــه ولــم يحضــر املترجــم وبســؤال‬\n‫املدعــي العــام عــن بينتــه التــي وعــد بهــا أجــاب قائــا مت إبالغهــم‬\n‫باحلضــور يف هــذه اجللســة وال أعلــم ســبب تخلفهــم عــن احلضــور وأطلــب‬\n\n\n                                                                                      ‫‪70‬‬\n\f     ‫إمهالــي إلحضارهــم هكــذا أجــاب ورفعــت اجللســة إلمهالــه إلــى يــوم‬\n     ‫االثنــن املوافــق ‪1433/6/2‬ه ـ وختمــت اجللســة الســاعة الثانيــة عشــر‬\n     ‫وعشــر دقائــق وصلــى اهلل علــى نبينــا محمــد وآلــه وصحبــه وســلم‪.‬‬\n                                                                ‫حرر‪1433/5/24‬ه ـ‬\n     ‫احلمــد هلل وحــده وبعــد ففــي يــوم اإلثنــن املوافق‪1433/06/02‬ه ـ‬\n     ‫افتتحــت اجللســة الثالثــة الســاعة التاســعة وفيهــا حضــر املدعــي العــام‬\n     ‫واملدعــى عليــه واملترجــم ‪ .......‬وبســؤال املدعــي العــام عــن بينتــه التــي‬\n     ‫وعــد بهــا أحضــر للشــهادة املدعــو ‪ ......‬هنــدي اجلنســية مبوجــب رخصــة‬\n     ‫اإلقامــة الصــادرة مــن جــوازات الريــاض برقــم (‪ )......‬وبســؤاله عمــا لديــه‬\n     ‫مــن شــهادة عــن طريــق املترجــم عــرف بنفســه بأنــه هنــدي اجلنســية ومــن‬\n     ‫مواليــد عــام ‪1986‬ه ـ ويعمــل بــإدارة ســجون املنطقــة عامــل نظافــة ويف‬\n     ‫املســاء يعمــل يف مطعــم الريــان وال يعــرف املدعــى عليــه وليــس لــه بــه أي‬\n     ‫عالقــة ثــم شــهد قائــا أشــهد أنــه يف أحــد األيــام ال أتذكــر التاريــخ‬\n     ‫كنــت خارجــا مــن مطعــم الريــان الســاعة الواحــدة والنصــف مســاء‬\n     ‫فرأيــت شــخصا يقــوم بكســر بــاب البقالــة املجــاورة للمطعــم بحديــدة‬\n     ‫أو شــاكوش فتوجهــت إليــه ألمســك بــه فهــرب ولــم أمتكــن مــن رؤيــة‬\n     ‫وجهــه إال أننــي رأيتــه يعــرج يف مشــيته هكــذا شــهد وبعــرض مــا جــاء يف‬\n     ‫شــهادة الشــاهد علــى املدعــى عليــه عــن طريــق املترجــم أجــاب بقولــه مــا‬\n     ‫جــاء يف شــهادته كلــه غيــر صحيــح وأمــا الشــاهد فــا يعرفــه هكــذا‬\n     ‫أجــاب عــن طريــق املترجــم كمــا أحضــر املدعــي العــام للشــهادة املدعــو‬\n     ‫‪ .......‬ســعودي اجلنســية مبوجــب الســجل املدنــي رقــم (‪ ).....‬وبســؤاله عمــا‬\n     ‫لديــه مــن شــهادة عــرف بنفســه بأنــه مــن مواليــد عــام ‪1403‬ه ـ ويعمــل‬\n     ‫بالدوريــات األمنيــة بالباحــة برتبــة عريــف ويســكن مبحافظــة ‪ .....‬وال‬\n\n\n‫‪71‬‬\n\f‫يعــرف املدعــى عليــه وليــس لــه بــه عالقــة ثــم شــهد قائــا أشــهد أنــه يف‬\n‫أحــد األيــام وردنــا بــاغ عــن تعــرض أحــد احملــات للســرقة فانتقلــت‬\n‫مــع أحــد ضبــاط امليــدان للمحــل فوجدنــا أحــد أبــواب احملــل غيــر البــاب‬\n‫الرئيســي قــد كســر زجاجــه والقفــل غيــر موجــود وبالدخــول اتضــح أن‬\n‫درج احملاســب املعــد مــن األملنيــوم مكســور وليــس فيــه شــيء هــذا مــا‬\n‫لــدي وبــه أشــهد وبعــرض مــا جــاء يف شــهادته علــى املدعــى عليــه أجــاب‬\n‫عــن طريــق املترجــم قائــا مــا جــاء يف الشــهادة ال أعلــم عنــه ألننــي لــم‬\n‫أســرق احملــل ولــم أتعــرض لــه هكــذا أجــاب وبســؤال املدعــي العــام هــل‬\n‫لديــك مزيــد بينــة أجــاب قائــا نعــم لــدي شــهادة ‪ ......‬و‪ ......‬علمــا بأنــه‬\n‫بطلــب الشــاهد الثانــي وردنــا خطــاب مديــر شــرطة املدينــة املتضمــن‬\n‫أن املذكــور لديــه دورة ملــدة إحــدى عشــر شــهرا يف مدينــة الريــاض‬\n‫مــن بدايــة هــذا العــام ولــذا فإننــي أطلــب الرجــوع إلــى شــهادته املدونــة‬\n‫باملعاملــة وإمهالــي إلحضــار الشــاهد اآلخــر هكــذا أجــاب ثــم رفعــت‬\n                                                                            ‫اجللســة‬\n‫ويف يــوم األحــد املوافــق‪ 1433/06/15‬ه ـ افتتحــت اجللســة اخلامســة‬\n‫الســاعة التاســعة وفيهــا حضــر املدعــي العــام واملدعــى عليــه ولــم يحضــر‬\n‫املترجــم ثــم أحضــر املدعــي العــام للشــهادة املدعــو ‪ ......‬ســعودي اجلنســية‬\n‫مبوجــب الســجل املدنــي رقــم (‪ )......‬وبســؤاله عمــا لديــه من شــهادة عرف‬\n‫بنفســه بأنــه مــن مواليــد عــام ‪1395‬ه ـ ويســكن بالباحــة ويعمــل بشــرطة‬\n‫منطقــة الباحــة برتبــة وكيــل رقيــب وليــس لــه أي عالقــة أوصلــه باملدعى‬\n‫عليــه ثــم شــهد قائــا أنــه يف أحــد األيــام ال أتذكــر التاريــخ بالضبــط‬\n‫انتقلــت مــع احملقــق مــن هيئــة التحقيــق ومعنــا املدعــى عليــه وتوجــه بنــا‬\n‫املدعــى عليــه إلــى محــل إقامتــه ثــم انتقلنــا إلــى مزرعــة يف الباحــة حتــت‬\n\n\n                                                                                       ‫‪72‬‬\n\f     ‫احملــل املســروق وقمنــا بالبحــث عــن املســروقات داخــل الغرفــة املوجــودة‬\n     ‫باملزرعــة فوجدنــا املســروقات يف ثالجــة تالفــة وهــي مبلــغ مالــي ال أعلــم‬\n     ‫قــدره وبطاقــات شــحن للجــواالت هــذا مــا لــدي وبــه أشــهد كمــا أحضــر‬\n     ‫املدعــي العــام كال مــن ‪ ......‬بنغالديــش اجلنســية مبوجــب رخصــة اإلقامة‬\n     ‫الصــادرة مــن جــوازات الريــاض برقــم (‪ )......‬و ‪......‬بنغالديــش اجلنســية‬\n     ‫مبوجــب رخصــة اإلقامــة الصــادرة مــن جــوازات الريــاض (‪ )....‬وهمــا‬\n     ‫يجيــدان التحــدث باللغــة العربيــة وبســؤالهما عمــا لديهمــا شــهدا بــأن‬\n     ‫الشــاهد املدعــو ‪ ......‬معــروف لديهــم وأنــه عــدل هكــذا شــهدا فســألنا‬\n     ‫املدعــي العــام هــل لديــه مزيــد بينــة فأجــاب قائــا ليــس لــدي ســوى مــن‬\n     ‫أحضــرت ومــا يف أوراق املعاملــة هكــذا أجــاب فأفهــم بإحضــار مزكــي‬\n     ‫للشــاهد الثانــي فاســتعد بذلــك ثــم رفعــت اجللســة إلحضــار املترجــم‬\n     ‫وعــرض مــا جــاء يف شــهادة الشــاهد علــى املدعــى عليــه عــن طريقــه‬\n     ‫ورفعــت اجللســة لذلــك إلــى يــوم األثنــن املوافــق ‪1433/7/28‬ه ـ الســاعة‬\n     ‫التاســعة وختمــت اجللســة الســاعة التاســعة والنصــف وبــاهلل التوفيــق‬\n     ‫‪ ،‬وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم ‪ .‬حــرر يف‬\n                                                                   ‫‪1433/06/15‬ه ـ‬\n     ‫احلمــد هلل وحــده والصــاة والســام علــى مــن ال نبــي بعــده وبعــد ففــي‬\n     ‫يــوم اإلثنــن املوافق‪1433/07/28‬ه ـ افتتحــت اجللســة السادســة الســاعة‬\n     ‫التاســعة وفيهــا حضــر املدعــي العــام واملدعــى عليــه ونظــرا ألن فضيلــة‬\n     ‫الشــيخ ‪ ........‬يف إجــازة اعتياديــة لهــذا األســبوع لــذا رفعــت اجللســة إلــى‬\n     ‫يــوم االثنــن املوافــق ‪1433/8/19‬ه ـ الســاعة التاســعة وختمــت اجللســة‬\n     ‫الســاعة التاســعة والربــع وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه‬\n                                   ‫وصحبــه وســلم ‪ .‬حــرر يف ‪ 1433/07/28‬ه ـ‬\n\n\n‫‪73‬‬\n\f‫احلمــد هلل وحــده والصــاة والســام علــى مــن ال نبــي بعــده وبعــد ففــي‬\n‫يــوم اإلثنــن املوافق‪1433/8/19‬ه ـ افتتحــت اجللســة الســابعة الســاعة‬\n‫التاســعة ولــم يحضــر املدعــي العــام وأمــا املدعــى عليــه فقــد جــرت‬\n‫مخاطبــة إدارة الســجون بعــدم إحضــاره هــذا اليــوم نظــرا ألن فضيلــة‬\n‫الشــيخ ‪ ......‬املشــارك يف نظــر هــذه القضيــة يف إجــازة اعتياديــة لهــذا‬\n‫األســبوع ‪ ،‬لــذا رفعــت اجللســة إلــى يــوم االثنــن املوافــق ‪1433/9/4‬ه ـ‬\n‫الســاعة احلادية عشــرة ‪ ،‬وختمت اجللســة الســاعة التاســعة والربع وصلى‬\n‫اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم ‪ .‬حــرر يف ‪1433/8/19‬‬\n                                                                                 ‫هـ‬\n‫احلمــد هلل وحــده وبعــد ويف يــوم ‪1433/09/04‬ه ـ افتتحــت اجللســة‬\n‫وحضــر الطرفــان وجــرى ســؤال املدعــى عليــه مــن الشــاهد وشــهادته‬\n‫عــن طريــق املترجــم فأجــاب قائــا مــا جــاء يف شــهادة الشــاهد كلــه‬\n‫غيــر صحيــح هكــذا أجــاب ثــم جــرى ســؤال املدعــي العــام عــن شــهادة‬\n‫الشــاهد ‪ .....‬حيــث لــم جندهــا مدونــة يف املعاملــة فأجــاب قائــا بعــد‬\n‫متكينــه مــن االطــاع علــى أوراق املعاملــة‪ :‬بــأن الشــهادة املشــار إليهــا‬\n‫هــي مــا دون علــى الصحيفــة رقــم ‪ 2‬مــن امللــف املرفــق باملعاملــة لفــة رقــم‬\n‫‪ 1‬وهــو عبــارة عــن محضــر انتقــال ومعاينــة هكــذا أجــاب فجــرى منــا‬\n‫االطــاع عليــه فوجدنــاه تضمــن وصفــا للمحــل املســروق وأن الفتحــة‬\n‫األولــى للمحــل تعــرض ســياجها احلديــدي لنــزع القفــل وســحب الســياج‬\n‫والزجــاج مكســور ولــم يتــم العثــور علــى القفــل هــذا مــا تضمنــه ‪،‬‬\n‫فســألنا املدعــي العــام هــل أحضــر مزكــن للشــاهد ‪ ......‬فأجــاب‬\n‫قائــا لقــد قمــت مبخاطبتهــم إلحضارهــم يف هــذه اجللســة واســتعدوا‬\n‫بذلــك وال أعلــم ســبب عــدم حضورهــم وأطلــب إمهالــي إلحضارهــم يف‬\n\n\n                                                                                      ‫‪74‬‬\n\f     ‫اجللســة القادمــة هكــذا أجــاب ثــم جــرى منــا الرجــوع إلــى أوراق املعاملــة‬\n     ‫لالطــاع عليهــا فوجدنــا بــن طياتهــا وعلــى الصحيفــة رقــم ‪ 4-3‬مــن‬\n     ‫ملــف التحقيــق املرفــق باملعاملــة لفــة رقــم ‪ 93‬إقــرار ًا للمدعــى عليــه‬\n     ‫مؤرخـ ًا يف ‪1433/1/15‬ه ـ تضمــن إقــراره بأنــه يف متــام الســاعة الواحــدة‬\n     ‫والنصــف مــن ليلــة األربعــاء املوافــق ‪1432/12/27‬ه ـ قــام بكســر قفــل‬\n     ‫بــاب ســوبر ماركــت الرمــال مبطرقــة ثــم قــام بكســر الزجــاج ويف هــذه‬\n     ‫األثنــاء شــاهد شــخص يصيــح بــه ليتوقــف فنــزل للبــدروم حيــث مقــر‬\n     ‫ســكنه وبعــد نصــف ســاعة صعــد شــريكه ‪ ......‬حســب االتفــاق معــه‬\n     ‫وقــام بســرقة املبالــغ املاليــة وبطاقــات شــحن مــن احملــل املذكــور ونــزل‬\n     ‫بهــا إليــه يف البــدروم فقــام بإخفائهــا يف مزرعــة مجــاورة وأنــه قــام برمــي‬\n     ‫املطرقــة واملفتــاح والقفــل املســروق بحاويــة البلديــة انتهــى مضمونــه‬\n     ‫وبعرضــه علــى املدعــى عليــه أنكــر صــدوره منــه وقــرر بأنــه وضــع بصمة‬\n     ‫إبهامــه عليــه وال يعــرف محتــواه هكــذا قــرر ‪ ،‬كمــا جــرى االطــاع‬\n     ‫علــى التقريــر الفنــي رقــم ‪ 1/1‬لعــام ‪1433‬ه ـ الصــادر مــن إدارة األدلــة‬\n     ‫اجلنائيــة بالباحــة فوجدنــاه تضمــن أنــه مبضاهــاة بصمــات ‪ .....‬علــى‬\n     ‫آثــار البصمــات احملفوظــة لديهــم واملقيــدة ضــد مجهــول اتضــح أنهــا ال‬\n     ‫تنطبــق انتهــى مضمونــه كمــا جــرى االطــاع علــى احملضــر املــؤرخ يف‬\n     ‫‪1433/1/5‬ه ـ واملــدون الصحيفــة رقــم ‪ 2‬ملــف التحقيــق املرفــق باملعاملة‬\n     ‫لفــة رقــم ‪ 69‬فوجدنــاه تضمــن أن الكيــس النايلــون الــذي ضبــط مــع‬\n     ‫املســروقات بــه مبلغ ـ ًا مالي ـ ًا قــدره ســتة وثالثــون ألف ـ ًا وثالثــة وســبعون‬\n     ‫ريــا ًال انتهــى مضمونــه كمــا جــرى االطــاع علــى محضــر االنتقــال‬\n     ‫واملعاينــة املــدون علــى الصحيفــة رقــم ‪ 6-5‬مــن ملــف التحقيــق املرفــق‬\n     ‫باملعاملــة لفــة رقــم ‪ 20‬فوجدنــاه مطابقــا ملــا جــاء يف دعــوى املدعــي العــام‬\n\n\n‫‪75‬‬\n\f‫‪ ،‬ثــم جــرى االطــاع علــى صحيفــة ســوابق املدعــى عليه املرفقــة باملعاملة‬\n‫لفــة رقــم ‪ 53‬فوجدناهــا تضمنــت عــدم تســجيل ســوابق بحقــه ا‪.‬ه ـ ثــم‬\n‫رفعــت اجللســة إلمهــال املدعــي العــام لتزكيــة الشــاهد إلــى يــوم االثنــن‬\n‫املوافــق ‪1433/9/11‬ه ـ الســاعة الواحــدة ويف املوعــد احملــدد افتتحــت‬\n‫اجللســة وفيهــا حضــر املدعــي العــام واملدعــى عليــه ‪ ،‬وأحضــر املدعــي‬\n‫ال مــن ‪ ......‬ســعودي اجلنســية مبوجــب الســجل املدنــي رقــم (‪).....‬‬ ‫العــام ك ً‬\n‫و ‪ .....‬ســعودي اجلنســية مبوجــب الســجل املدنــي رقــم(‪ )....‬وبســؤالهما‬\n‫عمــا لديهمــا شــهد كل منهمــا مبعرفتــه للشــاهد ‪ ........‬معرفــة تامــة‬\n‫وأنــه عــدل ثقــة هكــذا شــهدا ونظــرا للحاجــة إلــى تأمــل القضيــة‬\n‫اســتعدادا للحكــم فيهــا قررنــا رفــع اجللســة ويف يــوم االثنــن املوافــق‬\n‫‪1433/12/27‬ه ـ افتتحــت اجللســة الســاعة احلاديــة عشــرة وفيهــا حضــر‬\n‫املدعــي العــام ‪ .....‬ســعودي اجلنســية مبوجــب الســجل املدنــي رقــم (‪).......‬‬\n‫مبوجــب خطــاب التكليــف الــوارد إلينــا مــن رئيــس فــرع هيئــة التحقيــق‬\n‫واالدعــاء العــام بالباحــة برقــم ه ـ ب ‪ 8399/2/1‬يف ‪1433/12/5‬ه ـ‬\n‫كمــا أحضــر املدعــى عليــه مــن قبــل إدارة الســجن ‪ ،‬وحضــر املترجــم‬\n‫املتعــاون مــع احملكمــة املدعــو ‪ ......‬باكســتاني اجلنســية مبوجب اإلقامة‬\n‫الصــادرة مــن جــوازات الباحــة برقــم (‪( )......‬ســارية املفعــول) ‪ ،‬ويف هــذه‬\n‫اجللســة جــرى اطــاع احلاضريــن علــى مــا ســبق ضبطــه وصادقــوا عليــه‬\n‫‪ ،‬ثــم جــرى ســؤال املدعــي العــام واملدعــى عليــه إن كان لــدى أي منهمــا‬\n‫إضافــة علــى مــا ســبق ضبطــه فقــررا بقولهمــا ليــس لدينــا ســوى مــا ســبق‬\n‫ضبطــه هكــذا قــررا فقفلنــا بــاب املرافعــة ‪ ،‬وبنــاء علــى مــا تقــدم مــن‬\n‫الدعــوى واإلجابــة ومــا قــرره الطرفــان وحيــث أنكــر املدعــى عليــه مــا‬\n‫نســبه إليــه املدعــي العــام يف دعــواه وبنــاء علــى مــا جــاء يف إقــرار املدعــى‬\n\n\n                                                                                         ‫‪76‬‬\n\f                                                                                ‫عليــه‬\n     ‫احلمــد هلل وحــده وبعــد ويف يــوم االثنــن املوافــق ‪1433/9/11‬ه ـ افتتحــت‬\n     ‫اجللســة التاســعة الســاعة الواحــدة وفيهــا حضــر املدعــي العــام واملدعــى‬\n     ‫عليــه واملترجــم وبســؤال املدعــي العــام عــن تزكيــة الشــاهد أجــاب قائال‬\n     ‫لقــد قمــت مبخاطبــة إدارة الشــرطة التــي يعمــل بهــا الشــاهد فأفــادوا بأن‬\n     ‫الشــاهد املذكــور بإجــازة اآلن ووعــدوا بإحضــار املزكــن هــذا اليــوم‬\n     ‫وال أعلــم ســبب تأخرهــم وأطلــب إمهالــي إلعــادة مخاطبتهــم وإحضــار‬\n     ‫املزكــن جللســة قادمــة هكــذا أجــاب فأفهــم بأنــه ســيتم إمهالــه إلــى‬\n     ‫اجللســة القادمــة وإذا لــم يتمكــن مــن إحضارهــم فســيعد عاجــزا عــن‬\n     ‫تزكيتــه ففهــم ذلــك ورفعــت اجللســة بذلــك إلــى يــوم األربعــاء املوافــق‬\n     ‫‪1433/9/13‬ه ـ الســاعة الواحــدة والنصــف وختمــت اجللســة الســاعة‬\n     ‫الواحــدة والنصــف وصلــى اهلل علــى نبينــا محمــد وآلــه وصحبــه وســلم ‪.‬‬\n                                                           ‫حــرر يف ‪1433/9/11‬ه ـ‬\n     ‫احلمــد هلل وحــده وبعــد ويف يــوم األربعــاء املوافــق‪ 1433/09/13‬ه ـ‬\n     ‫افتتحــت اجللســة العاشــرة الســاعة والواحــدة والنصــف وفيهــا حضــر‬\n     ‫ال مــن ‪......‬‬\n                 ‫املدعــي العــام واملدعــى عليــه ‪ ،‬وأحضــر املدعــي العــام ك ً‬\n     ‫ســعودي اجلنســية مبوجــب الســجل املدنــي رقــم (‪ ).......‬و ‪ .......‬ســعودي‬\n     ‫اجلنســية مبوجــب الســجل املدنــي رقــم(‪ ).......‬وبســؤالهما عمــا لديهمــا‬\n     ‫شــهد كل منهمــا مبعرفتــه للشــاهد ‪ .....‬معرفــة تامــة وأنــه عــدل ثقــة‬\n     ‫هكــذا شــهدا ونظــرا للحاجــة إلــى تأمــل القضيــة اســتعدادا للحكــم‬\n     ‫فيهــا قررنــا رفــع اجللســة إلــى يــوم االثنــن املوافــق ‪1433/10/16‬ه ـ‬\n     ‫الســاعة احلاديــة عشــرة وختمــت اجللســة الســاعة الواحــدة و وبــاهلل‬\n     ‫التوفيــق ‪ ،‬وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم ‪.‬‬\n\n\n‫‪77‬‬\n\f                                                   ‫حــرر يف ‪ 1433/09/13‬ه ـ‬\n‫احلمــد هلل وحــده والصــاة والســام علــى مــن ال نبــي بعــده وبعــد ففــي يوم‬\n‫اإلثنــن املوافق‪1433/10/16‬ه ـ افتتحــت اجللســة احلادية عشــرة الســاعة‬\n‫احلاديــة عشــرة ولــم يحضــر املدعــي العــام وأمــا املدعــى عليــه فقــد جــرت‬\n‫مخاطبــة إدارة الســجون بعــدم إحضــاره هــذا اليــوم نظــرا ألن فضيلــة‬\n‫الشــيخ ‪ .......‬املشــارك يف نظــر هــذه القضيــة يف إجــازة اعتياديــة لهــذا‬\n‫األســبوع وفضيلــة الشــيخ ناظــر القضيــة ‪ .......‬يف دورة ملــدة شــهرين ‪ ،‬لــذا‬\n‫رفعــت اجللســة إلــى يــوم االثنــن املوافــق ‪1433/10/23‬ه ـ الســاعة احلادية‬\n‫عشــرة ‪ ،‬وختمــت اجللســة الســاعة احلاديــة عشــرة والنصــف وصلــى اهلل‬\n‫علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم ‪ .‬حــرر يف ‪ 1433/10/16‬هـ‬\n‫احلمــد هلل وحــده وبعــد ويف يــوم االثنــن ‪1433/10/23‬ه ـ افتتحــت‬\n‫اجللســة وحضــر الطرفــان وجــرى االطــاع علــى القضيــة ودراســتها وبنــاء‬\n‫علــى اقــرار املدعــى عليــه املــدون أعــاه ومــا تضمنــه مــن وصــف للجانــي‬\n‫يتطابــق مــع املدعــى عليــه وداللتــه علــى املســروقات بجانــب مقــر ســكنه‬\n‫ونظــرا إلــى أن هــذه البينــات املقدمــة مــن املدعــي العــام غيــر موصلــة‬\n‫إلثبــات اإلدانــة مبــا جــاء يف الدعــوى وإمنــا تفيــد توجــه التهمــة للمدعــى‬\n‫عليــه بهــا ‪ ،‬ونظــرا إلــى أن هــذا العمــل محــرم شــرعا ومــن االعتــداء‬\n‫علــى األمــوال بغيــر حــق وقــد قــال عليــه الصــاة والســام (( كل املســلم‬\n‫علــى املســلم حــرام ودمــه ومالــه وعرضــه )) ونظــرا إلــى أن املدعــى عليــه‬\n‫يســتوجب العقوبــة لقــاء هــذه التهمــة طبقــا للقواعــد الشــرعية ولــكل مــا‬\n‫تقــدم فقــد توجهــت التهمــة للمدعــى عليــه مبــا نســب إليــه يف الدعــوى‬\n‫مــن ســرقة احملــل املذكــور وحكمنــا مبــا يلــي‪ :‬أوال‪ /‬درء إقامــة حــد‬\n‫الســرقة علــى املدعــى عليــه لعــدم ثبــوت موجبــه ‪ .‬ثانيــا ‪ /‬تعزيــر املدعــى‬\n\n\n                                                                                     ‫‪78‬‬\n\f     ‫عليــه لقــاء التهمــة وذلــك بســجنه مــدة ســنة تبــدأ مــن تاريــخ إيقافــه بســبب‬\n     ‫هــذه القضيــة وجلــده مائــة جلــدة مفرقــة علــى دفعتــن قــدر كل دفعــة‬\n     ‫خمســون جلــدة وبــن كل دفعــة وأخــرى عشــرة أيــام ‪ ،‬وبعــرض احلكــم‬\n     ‫علــى املدعــي العــام واملدعــى عليــه قــررا اعتراضهمــا علــى احلكــم‬\n     ‫مســتعدين بتقــدمي الئحــة اعتراضيــة فأفهمــا باملراجعــة يــوم الثالثــاء‬\n     ‫املوافــق ‪1433/12/28‬ه ـ الســتالم نســخة مــن القــرار وتقــدمي الئحتيهمــا‬\n     ‫االعتراضيــة عليــه خــال ثالثــن يومــا مــن تاريخــه وإذا لــم يتقدمــا‬\n     ‫باعتراضهمــا خاللهــا فســيتم رفــع كامــل أوراق املعاملــة حملكمــة‬\n     ‫االســتئناف بــدون الئحتيهمــا االعتراضيــة ففهمــا ذلــك وختمــت اجللســة‬\n     ‫الســاعة احلاديــة عشــرة والنصــف وصلــى اهلل علــى نبينــا محمــد وآلــه‬\n                                      ‫وصحبــه وســلم ‪ .‬حــرر يف ‪1433/12/27‬ه ـ‬\n     ‫احلمــد هلل وحــده والصــاة والســام علــى مــن ال نبــي بعــده وبعــد ويف‬\n     ‫هــذا اليــوم األحــد املوافــق ‪1434/03/22‬ه ـ افتتحــت اجللســة وقــد عــادت‬\n     ‫املعاملة من محكمة االستئناف برقم ‪ 34383710‬يف ‪1434/03/17‬هـ‬\n     ‫وبرفقهــا قــرار التصديــق الصــادر مــن الدائــرة اجلزائيــة اخلماســية‬\n     ‫األولــى مبحكمــة االســتئناف مبكــة املكرمــة برقــم ‪ 3450181‬يف‬\n     ‫‪1434/02/30‬ه ـ واملتضمــن بعــد املقدمــة مــا نصــه « وبدراســة احلكــم‬\n     ‫وصــورة ضبطــه والئحتــه االعتراضيــة تقــررت املوافقــة علــى احلكــم‬\n     ‫وبــاهلل التوفيــق وصلــى اهلل علــى نبينــا محمــد وآلــه وصحبــه وســلم‬\n     ‫قاضــي اســتئناف ‪........‬ختــم وتوقيــع ‪ ،‬قاضــي اســتئناف ‪ .........‬ختــم‬\n     ‫وتوقيــع ‪ ،‬قاضــي اســتئناف ‪ ........‬ختــم وتوقيــع ‪ ،‬قاضــي اســتئناف ‪......‬‬\n     ‫ختــم وتوقيــع ‪ ،‬قاضــي اســتئناف ‪ .......‬ختــم وتوقيــع « انتهــى نصــه ‪،‬‬\n     ‫وللعلــم جــرى حتريــره وصلــى اهلل علــى نبينــا محمــد وآلــه وصحبــه وســلم‬\n                                                        ‫‪ .‬حــرر يف ‪1434/03/22‬ه ـ‬\n‫‪79‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"d790af0e-7af1-509b-8d33-8ecc09f91096","source_page_start":62,"source_page_end":79,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"1373df815b1cd903016e4ede9e4b2c4e8f3b2e75e6eb96ef02ed543e07613b70","normalized_text_hash":"44d1d123c93561c97ae83c2dbbafb00f106d5f6751fe9042aa182ac9184ad847","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v25-p62-33481065"},{"id":"9236f3d5-d208-5c10-9d7c-ac148a1b85a4","document_type":"judgment","category":"judicial","subcategory":"general","title":"سرقة -سرقة نقود وأوراق من شركة -رجوع عن إقرار مصدق شرع ا -مقاومة قوات الشرطة -طلب إقامة حد السرقة -درء حد السرقة -التعزير بالسجن واجللد -مصادرة السيارتني املستخدمتني يف","document_number":"33337036","case_number":"3352942","judgment_number":null,"decision_number":null,"circular_number":null,"court":"المحكمة العامة بنجران و","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1433/07/12","year":"1434","subject":"سرقة -سرقة نقود وأوراق من شركة -رجوع عن إقرار مصدق شرع ا -مقاومة قوات الشرطة -طلب إقامة حد السرقة -درء حد السرقة -التعزير بالسجن واجللد -مصادرة السيارتني املستخدمتني يف","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"‫رقم الصك‪ 33337036 :‬تاريخه‪1433/07/12 :‬هـ‬\n                     ‫رقم الدعوى‪3352942 :‬‬\n    ‫رقم قرار التصديق من محكمة االستئناف ‪:‬‬\n           ‫‪ 34180803‬تاريخه‪1434/04/07 :‬هـ‬\n\n\n\n‫ســرقة ‪-‬ســرقة نقــود وأوراق مــن شــركة ‪-‬رجــوع عــن إقــرار مصدق شــرع ًا‬\n‫‪ -‬مقاومــة قــوات الشــرطة ‪ -‬طلــب إقامــة حــد الســرقة ‪ -‬درء حــد الســرقة‬\n‫‪ -‬التعزيــر بالســجن واجللــد ‪ -‬مصــادرة الســيارتني املســتخدمتني يف‬\n                                                                  ‫الســرقة ‪.‬‬\n\n\n\n‫‪-1‬مــا روى الزهــري عــن عائشــه رضــي اهلل عنهــا قالــت قــال رســول اهلل‬\n‫صلــى اهلل عليــه وســلم «ادرؤوا احلــدود عــن املســلمني مــا اســتطعتم وقد‬\n ‫روى ذلــك عــن عبــداهلل بــن مســعود ومعــاذ بــن جبل»رضــي اهلل عنهــم‪.‬‬\n‫‪-2‬مــا قــرره جمــع مــن أهــل العلــم أن مــن شــرط إقامــة حــد مــن حــدود‬\n‫اهلل باإلقــرار البقــاء عليــه إلــى متــام احلــد فــإن رجــع عــن إقــراره أو هــرب‬\n                                                                       ‫كــف عنــه ‪.‬‬\n\n\n\n\n‫توجيــه االتهــام خلمســة أشــخاص بســرقة شــركتني وأخــذ خزنتيهمــا ‪،‬‬\n‫حيــث ورد بــاغ مــن شــركتني يف نفــس املوقــع اليفصــل بينهمــا ســوى‬\n‫ثالثــن متــر ًا عــن تعرضهمــا للســرقه‪ ،‬مت االنتقــال للموقــع وأثنــاء مســح‬\n‫الدوريــة اشــتبهت الفرقــة يف ســيارة كان يبــدو أنهــا حتمــل حمولــة‬\n‫وكان زجــاج الســيارة بلــون قــامت ومتــت متابعتهــا حتى دخلت ورشــة وعند‬\n‫مالحظة الدورية قام بالفرار ومت اســتيقافه وســحب هويات األشــخاص‬\n                                                                                         ‫‪80‬‬\n\f     ‫الذيــن يســتقلونها‪ ،‬وحاولــوا مقاومــة رجــل األمــن إال أنــه متكــن املدعــى‬\n     ‫عليهمــا الثانــي والثالــث مــن الفــرار‪ ،‬ويف تاريــخ الحــق متــت مالحظتهمــا‬\n     ‫مــن قبــل دوريــة حــرس احلــدود و القبــض عليهمــا ‪ ،‬ومت ضبــط الســيارة‬\n     ‫وبداخلهــا اخلزنــة املســروقة وباســتجوابهم اعترفــوا مبــا نســب إليهــم و‬\n     ‫صدقــت اعترافاتهــم شــرع ًا ‪ ،‬وطلــب املدعــي العــام اثبــات مــا أســند‬\n     ‫إليهــم واحلكــم عليهــم بإقامــة حــد الســرقة والتعزيــر لقــاء مــا بــدر منهــم‬\n     ‫مــن محاولــة مقاومــة رجــال األمــن ومصــادره الســيارتني املســتخدمتني‬\n     ‫بالســرقة ‪ ،‬وقــد أنكــر املدعــى عليهــم مــا نســب إليهــم ‪ ،‬رجــع املدعــى‬\n     ‫عليهــم عــن اعترافاتهــم املصدقــه شــرع ًا ‪ ،‬لــذا صــدر احلكــم بــدرء حــد‬\n     ‫الســرقة وتعزيــر املدعــى عليهــم بالســجن واجللــد ومصــادرة الســيارتني ‪،‬‬\n                                        ‫وصــدق احلكــم مــن محكمــة االســتئناف ‪.‬‬    ‫ُ‬\n\n\n\n\n     ‫احلمــد هلل وحــده وبعــد فلدينــا نحــن ‪ .........‬رئيــس احملكمــة العامــة‬\n     ‫بنجــران و‪ .........‬و‪ .........‬القضــاة باحملكمــة العامــة بنجــران فقــد حضــر‬\n     ‫املدعــي العــام ‪ .........‬املكلــف مبوجــب خطــاب رئيس فــرع هيئة التحقيق‬\n     ‫واالدعــاء العــام مبنطقــة جنــران رقــم ‪ .........‬وتاريــخ ‪1432/12/23‬ه ـ‬\n     ‫وحضــر حلضــوره كل مــن ‪ .........‬ســعودي اجلنســية مبوجــب الســجل‬\n     ‫املدنــي رقــم ‪ .........‬و‪ ......... .........‬ســعودي اجلنســية مبوجــب الســجل‬\n     ‫املدنــي رقــم ‪ .........‬و‪ ......... .........‬ســعودي اجلنســية مبوجــب الســجل‬\n     ‫املدنــي رقــم ‪ .........‬و‪ .........‬ســعودي اجلنســية مبوجــب الســجل املدنــي رقــم‬\n     ‫‪ .........‬و‪ .........‬ســعودي اجلنســية مبوجــب الســجل املدنــي رقــم ‪.........‬‬\n     ‫ا ورد مبحضــر الدوريــات األمنيــة رقم (‪ ) .........‬وتاريخ‬ ‫وادعــى األول قائـ ً‬\n\n‫‪81‬‬\n\f‫‪1431/10/20‬ه ـ أنــه وردهــم بــاغ ســرقة وباالنتقــال للموقــع تبــن‬\n‫كســر بــاب شــركة ‪ .........‬وســرقة اخلزنــة ومبلــغ يقــدر بــ(‪)10000‬‬\n‫عشــرة آالف ريــال وأوراق تخــص الشــركة واحلالــة الثانيــة يف نفــس‬\n‫املوقــع وتبعــد ثالثــن متــر ًا وكان البــاب الرئيســي ملســتودع ‪.........‬‬\n‫للدهانــات مخلوع ـ ًا ومت ســرقة اخلزنــة ومبلــغ (‪ )4000‬أربعــة آالف ريــال‬\n‫وكمبيــاالت ومت التحفــظ علــى املوقــع وكان يوجــد باملوقــع كل مــن‬\n‫املبلغــن ‪ .........‬مصــري اجلنســية ( رخصــة إقامــة رقــم‪ ) ........./‬مبلغـ ًا عــن‬\n‫ســرقة شــركة ‪ .........‬لصناعــة األغذيــة و‪ .........‬مصــري اجلنســية (‪.........‬‬\n‫) مبلغ ـ ًا عــن ســرقة مؤسســة ‪ .........‬للتجــارة والصناعــة ومت العثــور يف‬\n‫املوقــع علــى ســيخ حديــدي ورافعــة تابعــة للشــركةكما ورد مبحضــر‬\n‫الدوريــات األمنيــة رقــم (‪ ) .........‬وتاريــخ ‪1431/10/20‬ه ـ أنــه عنــد‬\n‫ـس وأربعــن دقيقــة صباح ـ ًا وبنــاء علــى مــا ورد‬     ‫الســاعة الثامنــة وخمـ ٍ‬\n‫باحملضــر الســابق وأثنــاء مســح الدوريــة اشــتبهت الفرقــة يف ســيارة نــوع‬\n‫‪ ........‬حتمــل اللوحــة رقــم ‪ .........‬وكان يبــدو أنهــا حتمــل حمولــة وكان‬\n‫زجــاج الســيارة بلــون قــامت فتــم متابعتهــا حتــى دخــل ورشــة حــدادة مقابــل‬\n‫أســواق ‪ .........‬وعنــد مالحظــة الدوريــة قــام بالفــرار ومت اســتيقافه‬\n‫وســحب إثباتــات األشــخاص الذيــن يســتقلونها وحاولــوا مقاومــة رجــل‬\n‫األمــن ومتكــن املدعــى عليهمــا الثانــي والثالــث مــن الفــرار ومت‬\n‫مالحظتهمــا مــن قبــل دوريــة حــرس احلــدود والقبــض عليهمــا مــن قبلهــم‬\n‫ومت ضبــط الســيارةالعائدة للمدعــى عليهمــا وهــي مــن نــوع ‪ ........‬يحمــل‬\n‫اللوحــة رقــم ‪ .........‬وبهــا خزنــة حديديــة كبيــرة يف اخللــف وجهــازي‬\n‫جــوال ومت القبــض علــى الثانــي والثالــث مــن قبــل حــرس احلــدود بســقام‬\n‫ومت تســليمهم لقســم العريســة إلكمــال الــازم مــع مضبوطاتهــم وهــي‬\n\n\n                                                                                        ‫‪82‬‬\n\f     ‫(محفظــة ‪ +‬وجــوال ‪500 +‬خمســمائة ريــال ‪ +‬مفتــاح شــفر ‪ +‬مفتــاح آخــر)‬\n     ‫كمــا ورد مبحضــر الدوريــات األمنيــة رقــم ‪ 43301‬وتاريــخ‬\n     ‫‪1431/10/20‬ه ـ أنــه ورد بــاغ مــن ‪ , ......... /‬ســعودي اجلنسية‪,‬ســجل‬\n     ‫مدنــي رقــم‪ ) ......... /‬يفيــد بأنــه عثــر علــى بعــض املفقــودات بالقــرب مــن‬\n     ‫اجلبــل ‪ .........‬وهــي (خزنــة مكســورة و‪ 7‬أشــرطة ســيدي وشــهادة كفالــة‬\n     ‫رســمية وكشــف دهانــات وختــم وإســطنبة وشــيك للبنــك مببلــغ‬\n     ‫(‪ )113000‬مائــة وثالثــة عشــر ألــف ريــال وأوراق شــخصية منوعــة مــع‬\n     ‫جــواز ســفر كمــا ورد مبحضــر الدوريــات األمنيــة رقــم ‪ 44020‬وتاريــخ‬\n     ‫‪1431/10/25‬ه ـ أنــه أثنــاء اســتالم الدوريــة بالتاريــخ الســابق مت العثــور‬\n     ‫علــى ثــاث أوراق وهــي عبــارة عــن تفويــض بقيــادة ســيارة وصــك وكالــه‬\n     ‫خــاص وصــورة صــك وكالــه خــاص تابــع لشــركة ‪ .........‬للتجــارة‬\n     ‫والصناعــة وذلــك علــى أثــر ســرقة خزنــة تابعــة للشــركة حيــث مت العثــور‬\n     ‫عليهــا بالقــرب مــن حــي ‪ , .........‬شــارع األميــر ‪ .........‬كمــا ورد بخطــاب‬\n     ‫شــركة ‪ .........‬اســتالمهم للخزينــة املســروقة بعــد العثــور عليهــا وفتحهــا‬\n     ‫مــن قبــل احلــداد ضابــط القضيــة ومســاعديه ولكامــل محتوياتهــا دون‬\n     ‫نقــص واملتمثلــة يف مبلــغ (‪ )5500‬خمســة آآلف وخمســمائة ريــال‬\n     ‫ومصرفــات مســتندات نثريــة مببلــغ (‪ )10500‬عشــرة آالف وخمســمائة‬\n     ‫ريــال وبضبــط بــاغ‪( ......... /‬مصــري اجلنســية) مبوجــب رخصــة اإلقامــة‬\n     ‫رقــم (‪ ) .........‬يعمــل منــدوب مبيعــات مبؤسســة ‪ .........‬للدهانــات (‪.........‬‬\n     ‫) أفــاد بأنــه اتصــل عليــه صديقــه يف متــام الســاعة الســابعة مــن صبــاح يــوم‬\n     ‫األربعــاء ‪1431/10/20‬هـ ـ يبلغــه بأن باب املؤسســة مكســور وبحضوره‬\n     ‫إلــى املوقــع وجــد البــاب اخلارجــي للمؤسســة مكســور ًا وقــد ســرق مــن‬\n     ‫املســتودع اخلزنــة التــي حتتــوي علــى شــيكات لعمــاء املؤسســة‬\n\n\n‫‪83‬‬\n\f‫وكمبيــاالت وشــهادة مؤهــل دراســي ومبلــغ قــدره(‪ )4000‬أربعــة آالف‬\n‫ريــال إضافــة إلــى ألفــي (‪ )2000‬ريــال مــن درج املكتــب وعــدد مــن‬\n‫العقــود وبضبــط بــاغ‪( ........./‬مصــري اجلنســية) مبوجــب رخصة اإلقامة‬\n‫رقــم (‪ ) .........‬ويعمــل حتــت كفالــة شــركة ‪ .........‬فأفــاد أنــه يف يــوم‬\n‫األربعــاء املوافــق ‪1431/10/20‬ه ـ حضــر ملقــر عملــه فوجــد البــاب‬\n‫اخلارجــي للمســتودع مكســور ًا واملكاتــب الداخليــة كانــت مفتوحــة‬\n‫ومكســورة األقفــال ووجــد اخلزنــة التابعــة للشــركة مســروقة والتــي‬\n‫بداخلهــا أوراق ومســتندات ومبالــغ ماليــة ومت االنتقــال يف متــام الســاعة‬\n‫الســابعة والنصــف مــن صبــاح يــوم األربعــاء املوافــق ‪1431/10/20‬ه ـ‬\n‫بعــد تلقــي البــاغ إلــى املســتودعات املســروقة وتبينأنــه عبــارة عــن مبنــى‬\n‫كبيــر بطــول ‪ 50‬متــر تقريب ـ ًا بهــا مســتودعان ‪ -‬وبهــا بــاب خارجــي‬\n‫كبيــر بطــول أربعــة أمتــار تقريبـ ًا وبهــا بــاب صغيــر بارتفــاع متريــن وجــد‬\n‫مكســور ًا مــن ناحيــة القفــل بعتلــة حديديــة وجــدت باملوقــع ومت الفتــح‬\n‫بواســطتها وكان مفتوح ـ ًا وبالدخــول إلــى احملــل وعلــى اليســار غرفــة‬\n‫زجاجيــة لهــا بــاب أملنيــوم مكســور قفلــه ومســروق منــه خزنــة حديديــة‬\n‫فضيــة اللــون كمــا تضمــن البــاغ ‪ -‬ووجــدت محتويــات الغرفــة مبعثــرة‬\n‫ووجــد زيــت مســكوب يف الغرفــة مــع آلــة حديديــة اســتعملها اجلنــاة يف‬\n‫الكســر وبالغرفــة مكتــب مفتــوح األدراج ويوجــد غرفــة أخــرى بجــوار‬\n‫الغرفــة املشــار إليهــا مفتوحــة البــاب بعــد كســر القفــل ووجــد بهــا‬\n‫مكتــب مســروق منــه كاميــرا (‪ ).........‬كمــا تضمــن البــاغ وكانــت‬\n‫مبعثــرة األوراق ووجــد بالغرفــة رأس مطرقــة وآثــار ســحب علــى أرض‬\n‫املســتودع لســحب اخلزنــة للخــارج وباالنتقــال ملســتودع ‪ .........‬للدهانــات‬\n‫(‪ ) .........‬وجــد بابــه مفتوح ـ ًا بعتلــة حديديــة مــن الطــرف وبدخــول‬\n\n\n                                                                                      ‫‪84‬‬\n\f     ‫املســتودع وتبــن أن بــاب إحــدى الغــرف الداخليــة مكســور القفــل‬\n     ‫وبالدخــول إليهــا وجــدت آثــار ســحب للخزنــة إلــى اخلــارج وهــي التــي‬\n     ‫ســرقت منهــا اخلزنــة كمــا جــاء يف البــاغ ومت تصويــر املوقعــن‬\n     ‫املتعرضــن للســرقة وســيارة اجلنــاة واخلزنــة املكســورة وصــدرت بذلــك‬\n     ‫التقاريــر الفنيــة رقــم ‪ .........‬وتاريــخ ‪1431/10/20‬ه ـ ورقــم ‪ .........‬وتاريخ‬\n     ‫‪1431/10/20‬ه ـ ورقــم ‪ 1199‬وتاريــخ ‪1431/10/20‬ه ـ وباســتجواب‬\n     ‫املدعــى عليــه األول‪ ......./‬أقــر بأنــه يف يــوم األربعــاء املوافــق‬\n     ‫‪1431/10/20‬ه ـ حضــر إلــى مســتودع ‪, ..............‬للمــواد الغذائيــة‬\n     ‫ومســتودع ‪ .........‬للدهانــات (‪ ) .........‬لقصــد الســرقة ويرافقــه املدعــى‬\n     ‫عليــه الثانــي والثالــث واخلامــس ونــزل هــو والثانــي إلــى مســتودع ‪.........‬‬\n     ‫للدهانــات (‪ ) .........‬وبقــي الثالــث واخلامــس يف الســيارة للمراقبــة وقــام‬\n     ‫بكســر البــاب اخلارجــي ملســاعدة املدعــى عليــه الثانــي وســرقا اخلزنــة‬\n     ‫التــي يف املكتــب الداخلــي للمؤسســة وأخرجاهــا إلــى الشــارع ولــم يجــد‬\n     ‫املدعــى عليهمــا الثالــث واخلامــس ‪ -‬فطلــب مــن الرابــع املجــيء إليــه عنــد‬\n     ‫املســتودع وبحضــوره قامــوا بتحميــل اخلزنــة يف ســيارته مــن نــوع ‪.........‬‬\n     ‫حتمــل اللوحــة رقــم ‪ .........‬وذهبــوا بهــا إلــى جبــل قريــب مــن ‪ , .........‬هنــاك‬\n     ‫أنزلوهــا ومتكنــوا مــن كســرها ووجــدوا فيهــا مبلــغ(‪ )1200‬ألــف‬\n     ‫ومائتــي ريــال ســلموها للثانــي وتركــوا اخلزنــة يف املوقــع بعــد ذلــك عــاد‬\n     ‫الثالثــة إلــى مســتودع ‪ .........‬للمــواد الغذائيــة واتصلــوا علــى املدعــى عليــه‬\n     ‫الثالــث واخلامــس فحضــروا إليهــم وقــام مبســاعدة الثانــي بكســر البــاب‬\n     ‫اخلارجــي للمســتودع ودخــل اخلمســة جميعهــم للداخــل فوجــدوا باب ـ ًا‬\n     ‫زجاجي ـ ًا قامــوا بفكــه بحديــدة ودخلــوا للغرفــة التــي عثــروا بداخلهــا‬\n     ‫علــى خزنــه كبيــرة قامــوا بدفعهــا وأخرجوهــا خــارج املســتودع ثــم‬\n\n\n‫‪85‬‬\n\f‫ســحبوها بالســيارة ‪ .....‬العائــدة لــه حتــى وصلــوا بهــا إلــى وادي ‪.........‬‬\n‫وهنــاك قــام بإحضــار رافعــة وقاموابتحميلهــا إلــى داخــل الســيارة‬\n‫بواســطتها وذهبــوا بهــا إلــى ورشــة يريــدون فتحهــا فتــم القبــض عليهــم‬\n‫بالورشــة وصدقــت أقوالــه شــرع ًا وباســتجواب املدعــى عليــه الثانــي أقــر‬\n‫بأنــه يف يــوم األربعــاء املوافــق ‪1431/10/20‬ه ـ جــاء لسرقةمســتودع‬\n‫‪ ..............‬للدهانــات حيــث قــام بكســر البــاب اخلارجــي ملســاعدة األول‬\n‫وســرقوا خزنــة حديديــة مــن داخلــه وبعدهــا جاءهــم املدعــى عليــه الرابــع‬\n‫الــذي كان ينتظرهــم يف ســيارته وحملــوا اخلزنــة بســيارته وذهبــوا بهــا‬\n‫إلــى جبــل يف ‪ .........‬وهنــاك كســرها هنــاك وأخــذ مبلــغ ألــف ومائتــي‬\n‫ريــال منهــا وبعدهــا رجــع مــع األول والرابــع إلــى مســتودعات ‪.........‬‬\n‫وكســر هــو واألول البــاب اخلارجــي للمســتودع وجاءهــم وقتهــا املدعــى‬\n‫عليهمــا الثالــث واخلامــس بعــد االتصــال عليهمــا ودخــل اجلميــع إلــى داخل‬\n‫املســتودع وقامــوا بفــك البــاب الزجاجــي إلحــدى الغــرف التــي وجــدوا‬\n‫داخلهــا خزنــة حديديــة كبيــرة قامــوا بربطهــا وعندمــا لــم يتمكنــوا مــن‬\n‫ا مــن الزيــت يف الغرفــة ودفعــوا اخلزنة إلى الســيارة‬ ‫ســحبها ســكبوا قليـ ً‬\n‫ثم ســحبوها بالســيارة إلى وادي ‪ .........‬بعدها طلب األول رافعة وعندما‬\n‫حضــرت قامــوا برفــع اخلزنــة بواســطتها داخــل الســيارة وذهبــوا بهــا إلــى‬\n‫إحــدى الــورش لكــي يفتحوهــا ومت القبــض عليهــم هنــاك وصدقــت‬\n‫أقوالــه شــرع ًا وباســتجواب املدعــى عليــه الثالــث‪ /‬أقــر بأنــه اتفــق مــع‬\n‫األول والثانــي واخلامــس علــى ســرقة مســتودع ‪ .........‬للدهانــات فلمــا‬\n‫وصلــوا إلــى املســتودع نــزل األول والثانــي وكســروا بــاب املســتودع بينمــا‬\n‫بقــى يف الســيارة هــو واخلامــس وعنــد تأخــر املذكوريــن داخــل املســتودع‬\n‫غــادر املوقــع بصحبــة اخلامــس بعــد ذلــك قــدم الرابــع إلــى األول والثانــي‬\n\n\n                                                                                    ‫‪86‬‬\n\f     ‫بعــد اتصالهمــا عليــه وركبــا معــه وذهبــوا إلــى حــدود ‪ .........‬ومعهــم‬\n     ‫اخلزنــة التــي ســرقوها مــن املســتودع والتــي قامــوا بكســرها ثــم قامــوا‬\n     ‫باالتصــال عليــه وأخبــر أنهــم يريــدون أن يدخلــوا املســتودع اآلخــر العائــد‬\n     ‫لشــركة ‪ .........‬فحضــر لهــم فوجدهــم قــد كســروا البــاب الداخلــي‬\n     ‫ودخلــوا جميع ـ ًا للمكتــب فوجــدوا خزنــة كبيــرة فــأرادوا حملهــا فلــم‬\n     ‫يســتطيعوا قامــوا بســكب بعــض الزيــت ودفعهــا علــى األرض حتــى بــاب‬\n     ‫املســتودع وعندمــا لــم يســتطيعوا حتميلهــا يف الســيارة قامــوا بربطهــا‬\n     ‫وســحبها بالســيارة العائــدة لــأول حتــى أوصلوهــا إلــى وادي ‪ .........‬ثــم‬\n     ‫أحضــر األول رافعــة وقــام بتحميلهــا علــى ســيارته وركــب البقيــة معــه‬\n     ‫وذهبــوا إلــى إحــدى الــورش لفتحهــا فتمــت مداهمتهــم مــن قبــل الشــرطة‬\n     ‫هنــاك ومت القبــض علــى املدعــى عليــه األول يف املوقــع وهــرب الباقــون‬\n             ‫ومت القبض عليهم من قبل حرس احلدود وصدقت أقواله شرع ًا ‪0‬‬\n     ‫وباســتجواب املدعــى عليــه الرابــع‪ /‬أقــر أن املدعــى عليــه األول وطلــب‬\n     ‫منــه املجــيء إليــه عنــد مســتودع ‪ .........‬للدهانــات(‪ ) .........‬فلمــا جاءهــم‬\n     ‫حمــل األول والثانــي اخلزنــة التــي ســرقوها وتوجهــو معــه إلــى الشــرفة‬\n     ‫يف منطقــة مهجــورة وهنــاك قامــوا بكســرها جميعـ ًا ووجــدوا بداخلهــا‬\n     ‫مبلــغ ألــف ومائتــي ريــال وبعــض األوراق وأخــذوا النقــود وتركــوا‬\n     ‫األوراق مرميــة يف املوقــع ثــم اتفقــوا علــى الرجــوع إلــى مســتودع ‪.........‬‬\n     ‫لســرقته فاتصلــوا علــى الثالــث واخلامــس فجــاءوا إليــه عنــد املســتودع‬\n     ‫حيــث وقــام كل مــن األول والثانــي بكســر البــاب اخلارجــي ثــم دخــل‬\n     ‫اجلميــع إلــى املســتودع وكســروا بــاب املكتــب الداخلــي ووجــدوا خزنــة‬\n     ‫كبيــرة لــم يســتطيعوا حملهــا فقامــوا بســكب بعــض الزيــت يف األرض‬\n     ‫وقامــوا بدفعهــا حتــى وصلــوا إلــى البــاب اخلارجــي للمســتودع ثــم قامــوا‬\n\n\n‫‪87‬‬\n\f‫بربطهــا بســيارة األول وســحبها إلــى وادي ‪ .........‬حيــث أحضــر األول‬\n‫رافعــة قامــوا بتحميلهــا يف الســيارة بواســطتها وذهبــوا بهــا إلــى إحــدى‬\n‫الــورش لفتحهــا فجاءتهــم الشــرطة ومت القبــض عليهــم هنــاك وصدقــت‬\n‫أقوالــه شــرع ًا وباســتجواب املدعــى عليــه اخلامــس‪ /‬أقــر بأنــه حضــر إلــى‬\n‫مســتودع ‪ .........‬هو والثالث على ســيارة اجليب التابعة لألول بعد اتصاله‬\n‫عليهمــا طالب ـ ًا منهمــا احلضــور ملســتودع ‪ .........‬للمــواد الغذائيــة وبعــد‬\n‫وصولهمــا وجــدوا البــاب اخلارجــي للمســتودع مفتوح ـ ًا وقــام بالدخــول‬\n‫إلــى داخــل املســتودع مــع بقيــة املدعــى عليهــم ومتكنــوا مــن ســحب خزنــة‬\n‫كبيــرة مــن داخــل املكتــب الداخلــي واخلــروج بهــا إلــى البــاب اخلارجــي‬\n‫ثــم قامــوا بســحبها بســيارة األول (‪ )..........‬إلــى وادي حيــث قــام األول‬\n‫عنــد وصولهــم باالتصــال علــى صاحــب رافعــة فحضــر لهــم فقامــوا‬\n‫بتحميــل اخلزنــة بواســطة الرافعــة إلــى داخــل الســيارة والذهــاب بهــا إلــى‬\n‫إحــدى الــورش فتــم القبــض عليهــم عنــد ذلــك اإلجــراءات املتخــذة ‪ .1‬مت‬\n‫تســليم اخلزنــة املســروقة التــي ضبطــت مــع املدعــى عليهم لشــركة ‪.........‬‬\n‫بكامل محتوياتها ‪ -2‬مت تســليم اخلزنة املســروقة ملؤسســة ‪ -3 .........‬مت‬\n‫حجــز الســيارات املســتخدمة يف حجــز املــرور حلــن صــدور التوجيهــات‬\n‫حيالهــا وبالبحــث عمــا إذا كان لهــم ســوابق لــم يعثــر لهــم علــى ســوابق‬\n‫جنائيــة مســجلة وقــد انتهــى التحقيــق الــى توجيــه االتهــام لــ‪ ........... /‬و‬\n‫‪ .........‬بالدخــول ملســتودع شــركة ‪ .........‬للدهانــات بعــد كســر أبوابــه‬\n‫بعتل ـ ٍة حديدي ـ ٍة وســرقة خزن ـ ٍة مــن داخلــه كان بداخلهــا مبلــغ (‪)1200‬‬\n‫ألــف ومائتــي ريــال واتهــام ‪ .........‬مبســاعدتهما يف حملهــا بواســطة‬\n‫ســيارته ومشــاركته بكســر اخلزنــة املســروقة واتهــام ‪ ......... .........‬و‬\n‫‪ .........‬و‪ .........‬و‪ ......... .........‬و‪ .........‬باالشــتراك بالدخــول إلــى مســتودع‬\n\n\n                                                                                            ‫‪88‬‬\n\f     ‫شــركة ‪ .........‬وســرقة خزنــة حتتــوي علــى مبلــغ (‪ )16,000‬ســتة عشــر‬\n     ‫ألــف ريــال بعــد متكــن األول والثانــي مــن كســر بابــه بحديــد ٍة كانــت‬\n     ‫معهمــا وذلــك لألدلــة والقرائــن التاليــة ‪ .1‬إقراراتهــم املصدقــة شــرع ًا‬\n     ‫املنــوه عنهــا املدونــة ص (‪ )15,14,13,12,5‬مــن دفتــر التحقيــق املرفــق‬\n     ‫لفــة (‪ )3‬وص (‪ )12‬مــن دفتــر التحقيــق املرفــق لفــة (‪ )1‬وص (‪)16,15,9‬‬\n     ‫مــن دفتــر التحقيــق املرفــق لفــة (‪ -2 )2‬مــا جــاء يف أقوالهــم املنــوه عنهــا‬\n     ‫املدونــة علــى ص (‪ )16,15,14,13‬مــن دفتــر التحقيــق املرفــق لفــة (‪)1‬‬\n     ‫وصفحــة (‪ )14,13,12,11,10,8,7,6,5,4,3,2‬مــن دفتــر التحقيــق‬\n     ‫املرفــق لفــة (‪ )2‬وص (‪ )12,11,10,9,8,7,6,4,3,2‬مــن دفتــر التحقيــق‬\n     ‫املرفــق لفــة (‪ )3‬وص(‪ )9,5,4,3,2‬مــن دفتــر التحقيــق املرفــق لفــة (‪-3 )2‬‬\n     ‫محاضــر الدوريــات األمنيــة املنــوه عنهــا املرفقــة لفــة (‪)72,11,10,9,8‬‬\n                               ‫‪ -4‬احملضــر املشــترك املنــوه عنــه املرفــق لفــة (‪)14‬‬\n     ‫‪ -5‬مــا جــاء مبحضــر املعاينــة املنــوه عنــه املــدون علــى ص ـ (‪ )4,3,2‬مــن‬\n     ‫دفتــر التحقيــق املرفــق لفــة (‪ .6.)1‬ماجــاء بتقاريــر التصويــر اجلنائــي املنوه‬\n     ‫عنهــا املرفقــة لفــة (‪ .7.)65,64,63,62,60,59‬ماجــاء بتقريــر فنــي‬\n     ‫البصمــات املنــوه عنــه املرفــق لفــة (‪ .8.)58‬ماجــاء بخطــاب الشــركة‬\n     ‫املنــوه عنــه املرفــق لفــة (‪ .09 )100‬ماجــاء بإخباريــة املدعــي األول املنــوه‬\n     ‫عنهــا املــدون ص(‪ )7,6‬مــن ملــف التحقيــق املرفــق لفــة(‪ .010 )1‬ماجــاء‬\n     ‫بإخباريــة املدعــي الثانــي املنــوه عنهــا املــدون ص (‪ )10,9‬مــن ملــف‬\n     ‫التحقيــق املرفــق لفــة(‪ )1‬وحيــث إن مــا أقــدم عليــه املذكــورون وهــم‬\n     ‫بكامــل أهليتهــم املعتبــرة شــرع ًا مــن ســرقتهم مــا ًال محترم ـ ًا بالــغ‬\n     ‫النصــاب ال شــبهة لهــم فيــه مــن حــرزه بعــد هتكــه فعــل محــرم ومعاقــب‬\n     ‫عليــه شــرع ًا ‪ -‬اطلــب إثبــات إدانتهــم مبــا أســند إليهــم واحلكــم عليهــم‬\n\n\n‫‪89‬‬\n\f‫مبــا يلي‪-1‬بحــد الســرقة الــوارد ذكــره يف اآليــة الكرميــة رقــم (‪ )38‬مــن‬\n‫ســورة املائــدة ‪-2.‬تعزيرهــم شــرع ًا لقــاء مابــدر منهــم من محاولــة مقاومة‬\n‫رجــال األمــن وهــروب الثانــي والثالــث مــن رجــال األمــن ‪-3 0‬مصــادرة‬\n‫الســيارة مــن نــوع ‪........‬يحمــل اللوحــة رقــم ‪ .........‬العائــدة للمدعــى عليــه‬\n‫األول ‪ -‬ومصــادرة الســيارة مــن نــوع ‪ .........‬حتمــل اللوحــة رقــم ‪.........‬‬\n‫العائــدة للمدعــى عليــه الثانــي لكونهــا اســتخدمت يف الســرقة (علم ـ ًا‬\n‫بــأن احلــق اخلــاص الزال قائمـاً) وبســؤال املدعــى عليــه األول عمــا جــاء يف‬\n‫ا ال صحــة ملــا جــاء يف دعــوى املدعــي‬        ‫دعــوى املدعــي العــام أجــاب قائ ـ ً‬\n‫العــام مــن قيامــي بالدخــول ملســتودع شــركة ‪ .........‬للدهانــات وكســر‬\n‫أبوابــه وســرقة خزنــة منــه وال صحــة أيضـ ًا ملــا جــاء يف دعــواه مــن قيامــي‬\n‫باالشــتراك والدخــول إلــى مســتودع شــركة ‪ .........‬وكســر أبوابــه‬\n‫وســرقة خزنــة منــه فأنــا لــم أقــم بكســر أي بــاب مطلقـ ًا وال أعــرف شــيء‬\n‫عــن الــذي حــدث والــذي حصــل أنــه يف اليــوم الــذي ذكــر املدعــي العــام‬\n‫أردت الذهــاب ملدينــة الريــاض أنــا وزميلي ‪ .........‬و‪ .........‬لســحب الســجل‬\n‫األكادميــي مــن جامعــة امللــك ســعود وأردنــا إصــاح الســيارة ويف أثنــاء‬\n‫ســيرنا علــي طريــق ‪ .........‬وجدنــا خزنــة مربوطــة بحبــال وملقــاة علــى‬\n‫جانــب الطريــق فتوقفــت أنــا وزميلــي ‪ .........‬وأخــي ‪ .........‬فحاولنــا حمــل‬\n‫اخلزنــة إلــى ســيارتنا فلــم نســتطع وقمــت باالتصــال علــى ‪ .........‬إلحضــار‬\n‫ســيارتي التــي معــه وهــي مــن نــوع ‪............‬فجــاء إلينــا هــو و‪ .........‬فقمنــا‬\n‫باســتئجار ونــش مــن شــخص باكســتاني مببلــغ وقــدره مائةريــال وبعــد‬\n‫حتميــل اخلزنــة اجتهنــا مباشــرة للورشــة لغــرض فتحهــا ومعرفــة مــا بهــا‬\n‫فتــم مالحظتنــا مــن قبــل الدوريــات األمنيــة ومت القبــض علينــا حينهــا‬\n‫ونحــن يف الورشــة هكــذا أجــاب وبســؤال املدعــى عليــه الثانــي ‪.........‬‬\n\n\n                                                                                            ‫‪90‬‬\n\f     ‫ا ال صحــة ملــا جــاء يف دعــوى املدعــي العــام مــن قيامــي‬       ‫أجــاب قائ ـ ً‬\n     ‫بالدخــول ملســتودع شــركة ‪ .........‬للدهانــات بعــد كســر أبوابــه بعتلــة‬\n     ‫حديديــة وســرقة خزنــة بداخلــه فذلــك كلــه غيــر صحيــح والصحيــح أنــه‬\n     ‫يف ذلــك اليــوم ويف أثنــاء ذهابنــا أنــا وزمالئــي املدعــى عليهــم جميع ـ ًا‬\n     ‫للورشــة إلصــاح ســيارة ‪ .........‬وكنــت أنــا و‪ .........‬و‪ .........‬يف نفــس‬\n     ‫الســيارة ويف طريقنــا وجدنــا خزنــة حديديــة ملقــاة علــى جانــب الطريــق‬\n     ‫فتوقفنــا حلملهــا فلــم نســتطع فقمنــا باســتئجار ونــش مــن شــخص‬\n     ‫باكســتاني قريــب مــن املنطقــة لتحميلهــا فقمنــا باالتصــال علــى زمالئنــا‬\n     ‫‪ .........‬و‪ .........‬إلحضــار ســيارة ‪ .........‬لتحميــل اخلزنــة عليهــا وبعــد‬\n     ‫وصولهــم مت حتميــل اخلزنــة عليهــا فذهبنــا جميع ـ ًا نحــن اخلمســة علــى‬\n     ‫ســيارة ‪ .........‬إلــى الورشــة لغــرض فتــح اخلزنــة ومت القبــض علينــا مــن قبــل‬\n     ‫الدوريــات األمنيــة وحــرس احلــدود ولــم نتمكــن بعــد مــن فتــح اخلزنــة‬\n     ‫هكــذا أجــاب وبســؤال املدعــى عليــه الثالــث‪ .........‬عمــا جــاء يف دعــوى‬\n     ‫ا ال صحــة ملــا جــاء يف دعــوى املدعــي العــام مــن‬ ‫املدعــي العــام أجــاب قائـ ً‬\n     ‫قيامي باالشــتراك بالدخول ملســتودع شــركة ‪ .........‬بعد كســر أبوابه‬\n     ‫وســرقة خزنــة منــه والصحيــح أنــه يف اليــوم الــذي ذكــر املدعــي العــام‬\n     ‫ويف متــام الســاعة السادســة صباحـ ًا قــام ‪ .........‬باالتصــال علي أنا وزميلي‬\n     ‫‪ .........‬وطلــب منــا إحضــار ســيارته التــي كانــت معنــا فأحضرناهــا لــه‬\n     ‫للمــكان املطلــوب علــى طريــق ‪ .........‬وقمنــا بتحميــل اخلزنــة أنــا وزمالئي‬\n     ‫جميعـ ًا ثــم توجهنــا إلــى الورشــة جميعـ ًا لكــي نقــوم بفتحهــا ومعرفــة مــا‬\n     ‫بهــا فتــم القبــض علينــا هنــاك هكــذا أجــاب وبســؤال املدعــى عليــه‬\n     ‫ا ال صحــة ملــا جــاء يف دعــوى املدعــي العــام مــن قيامــي‬‫الرابــع أجــاب قائـ ً‬\n     ‫باالشــتراك يف كســر خزنــة مســروقة مــن مســتودع لشــركة ‪.........‬‬\n\n\n‫‪91‬‬\n\f‫للدهانــات وســرقة مــا بداخلهــا وال صحــة أيضـ ًا ملــا ذكــره املدعــي العــام‬\n‫مــن قيامــي بالدخــول إلــى مســتودع شــركة ‪ .........‬وســرقة خزنــة بداخلــه‬\n‫بعــد كســر أبوابــه والصحيــح أننــا كنــا ذاهبــن أنــا وزمالئــي ‪.........‬‬\n‫و‪ .........‬إلــى الصناعيــة إلصــاح ســيارتي وعلــى طريــق ‪ .........‬وجدنــا‬\n‫خزنــة علــى جانــب الطريــق مربوطــة فتوقفنــا حلملهــا فلــم نســتطع وقمنــا‬\n‫باالتصــال علــى ‪ .........‬و‪ .........‬إلحضــار ســيارة ‪ .........‬لتحميــل اخلزنــة ألن‬\n‫ســيارتي صغيــرة وال ميكــن حتميــل اخلزنــة عليهــا وبعــد وصــول الســيارة‬\n‫قمنــا بتحميــل اخلزنــة بعــد رفعهــا بواســطة ونــش قمنــا باســتئجاره مــن‬\n‫شــخص باكســتاني مببلــغ قــدره مائــة ريــال وتوجهنــا بها للورشــة لفتحها‬\n‫وبعــد وصولنــا مت القبــض علينــا مــن قبــل الدوريــات األمنيــة وحــرس‬\n‫ا ال‬‫احلــدود هكــذا أجــاب وبســؤال املدعــى عليــه اخلامــس أجــاب قائ ـ ً‬\n‫صحــة ملــا جــاء يف دعــوى املدعــي العــام فلــم أقــم باالشــتراك بالدخــول‬\n‫ملســتودع ‪ .........‬وســرقة خزنــة منــه فذلــك غيــر صحيــح والــذي حصــل أنــه‬\n‫يف ذلــك اليــوم اتصــل‪ ......... .........‬علــى ‪ .........‬وكنــت عنــده فطلــب‬\n‫إحضــار الســيارة التــي كانــت مــع ‪ .........‬فركبنــا الســيارة وذهبنــا إليهم‬\n‫علــى طريــق ‪ .........‬وهنــاك قمنــا بتحميــل اخلزنــة بالونــش داخــل الســيارة‬\n‫وذهبنــا بهــا إلــى إحــدى الــورش حتــى نفتحهــا ومت القبــض علينــا هنــاك‬\n‫هكــذا أجــاب فجــرى ســؤال املدعــي العــام عــن بينتــه فقــال بينتــي مــا‬\n‫ذكرتــه يف الئحــة الدعــوى ومــا هــو موجــود يف أوراق املعاملــة فجــرى‬\n‫االطــاع علــى أوراق املعاملــة فوجدنــا فيهــا إقــرارا للمدعــى عليــه األول‬\n‫ومصدقــا شــرعا علــى دفتــر التحقيــق اللفــة رقــم (‪ )1‬صفحــة (‪ )12‬ونصه‬\n‫«اقــر أنــا ‪ .........‬ســعودي اجلنســية بالســجل املدنــي رقــم ‪ .........‬مصدرهــا‬\n‫جنــران وتاريخهــا ‪1423/03/24‬ه ـ أبلــغ مــن العمــر ‪ 23‬وعشــرون ســنة‬\n\n\n                                                                                         ‫‪92‬‬\n\f     ‫أعــزب وأســكن ‪ .........‬حاصــل علــى دبلــوم األجهــزة الطبيــة بأنــه يف يــوم‬\n     ‫األربعــاء متــام الســاعة الثالثــة فجــر ًا ذهبــت أنــا واملواطــن ‪ .........‬واملواطــن‬\n     ‫‪ .........‬واملواطــن‪ .........‬إلــى مســتودعات خلــف إشــارة ‪ .........‬ثــم دخلنــا‬\n     ‫املســتودع شــركة ‪ .........‬للدهانــات حيــث قمنــا بكســر البــاب اخلارجــي‬\n     ‫كلنــا األربعــة ثــم دخلنــا إلــى املســتودع أنــا واملدعــو ‪ .........‬وكســرنا‬\n     ‫اخلزنــة وســرقنا ألــف ومائتــا ريــال فقــط ثــم خرجنــا ودخلنــا شــركة‬\n     ‫‪ .........‬بعــد أن كســرنا البــاب نحــن األربعــة وكســرنا بــاب املكتــب‬\n     ‫ودخلنــا املكتــب وأخذنــا اخلزنــة الكبيــرة حيث ســكبنا زيــت ودفيناها‬\n     ‫إلــى الســيارة نحــن األربعــة وركبناهــا ثــم اتصلنــا علــى املواطــن ‪.........‬‬\n     ‫وجاءنــا علــى ســيارة مــن نــوع أفيــون بــل لــم نركبهــا يف الســيارة وإمنــا‬\n     ‫ســحبناها حيــث ربطناهــا بحبــل ثــم ســحبناها إلــى وادي ‪ .........‬ثــم جبــت‬\n     ‫شــخص باكســتاني عنــده ونــش قــام بتحميلهــا مببلــغ مائــة ريــال فقــط‬\n     ‫ثــم ذهبنــا إلــى الورشــة نريــد قطعهــا ولكــن قبــض علينــا هــذا اعتــرايف‬\n     ‫أوقــع عليــه وأنــا بكامــل قــواي العقليــة املعتبــرة شــرع ًا غيــر مكــره وال‬\n     ‫مجبــر» كمــا جــرى االطــاع علــى دفتــر التحقيــق املرفــق لفــة رقــم (‪)3‬‬\n     ‫صفحــة (‪ )12‬فوجدنــا فيهــا إقــرارا آخــر للمدعــى عليــه ويتضمــن قيــام‬\n     ‫املدعــى عليــه األول والثانــي بكســر بــاب مســتودعات‪ .........‬للدهانــات‬\n     ‫وســرقة خزنــة صغيــرة منــه وأن املدعــى عليــه األول قــام باالتصــال علــى‬\n     ‫الرابــع فقامــوا بتحميلهــا وســرقة مبلــغ قــدره ألــف ومائتــا ريــال ثــم عــاد‬\n     ‫الثالثــة إلــى مســتودع ‪ .........‬بعــد االتصــال علــى املدعىعليهمــا الثالــث‬\n     ‫واخلامــس فقامــوا بكســر بــاب احملــل وســرقة اخلزنــة املوجــودة بــه كمــا‬\n     ‫جــرى االطــاع علــى إقــرار للمدعــى عليــه الثانــي ومصــدق شــرعا علــى‬\n     ‫دفتــر التحقيــق اللفــة رقــم (‪ )3‬صفحــة (‪ )14‬ويتضمن إقراره هو واملدعى‬\n\n\n‫‪93‬‬\n\f‫عليــه األول بكســر بــاب مســتودع شــركة ‪ .......‬للدهانــات وســرقة‬\n‫خزنــة حتــوي علــى مبلــغ ألــف ومائتــي ريــال مبســاعدة املدعــى عليــه‬\n‫الرابــع وذهابهــم إلــى مســتودع شــركة ‪ .....‬بعــد اإلتصــال علــى املدعــى‬\n‫عليهمــا الثالــث واخلامــس والقيــام بكســر أبوابــه وســرقة خزنــة منــه‬\n‫كمــا جــرى االطــاع علــى إقــرار آخــر للمدعــى عليــه الثانــي مصــدق‬\n‫شــرع ًا علــى دفتــر التحقيــق اللفــة رقــم (‪)2‬صفحــة (‪ )9‬ونصــه «اقــر أنــا‬\n‫‪ .........‬ســعودي اجلنســية بالســجل املدنــي رقــم ‪ .........‬مصدرهــا الريــاض‬\n‫وتاريخهــا ‪1422/09/09‬ه ـ أبلــغ مــن العمــر ‪ 20‬عشــرون ســنة أســكن‬\n‫الريــاض متــزوج أعمــل بشــركة ‪ .........‬بأنــه يف يــوم األربعــاء املوافــق‬\n‫‪1431/10/20‬ه ـ متــام الســاعة الثالثــة فجــرا تقريبــا قمت بكســر الباب‬\n‫اخلارجــي للمســتودعات ‪ ..............‬للمــواد الغذائيــة وكان معــي ‪.........‬‬\n‫وكان معي كذلك ‪ .........‬وكان معي كذلك ‪ .........‬و‪ .........‬والدخول‬\n‫إلــى مســتودع ‪.....‬للمــواد الغذائيــة وكســرنا اخلزنــة الكبيــرة مــن اجلــدار‬\n‫وســحبناها للخــارج جميعــا نحــن اخلمســة حيــث ربطناهــا بحبــل‬\n‫وســحبناها للخــارج وهــذا اعتــراف بكامــل قــواي العقليــة املعتبــرة‬\n‫شــرع ًا وعليهــا أوقع»كمــا جــرى االطــاع علــى إقــرار املدعــى عليــه‬\n‫الثالــث واملصــدق شــرعا علــى دفتــر التحقيــق اللفــة رقــم (‪ )4‬صفحــة (‪)4‬‬\n‫ونصــه «أقــر أنــا‪ .........‬ســعودي اجلنســية مبوجــب الســجل املدنــي رقــم‬\n‫‪ .........‬مصدرهــا جنــران وتاريخهــا ‪1423/07/09‬ه ـ أعــزب أســكن‬\n‫‪ .........‬أمــي ال أقــرأ وال أكتــب بأنــه يف يــوم األربعــاء يف متــام الســاعة‬\n‫الثانيــة فجــرا ذهبنــا إلــى املســتودع‪ .........‬للدهانــات ‪ .........‬أنــا و‪.........‬‬\n‫و‪ .........‬و‪ .........‬وجلسنا أنا و‪ .........‬يف السيارة يف اخلارج فقاموا بكسر‬\n‫بــاب املســتودع الدهانــات ‪ .........‬للدهانــات املســمى ‪ .........‬ثــم ذهبــت أنــا‬\n\n\n                                                                                           ‫‪94‬‬\n\f     ‫و‪ .........‬وتركناهــم فلمــا تأخرنــا عليهــم اتصلــوا على أخــي‪ .........‬املدعو‬\n     ‫‪ .........‬فجاءهــم علــى ســيارته مــن نــوع ‪ ......‬وركبــوا معــه وذهبــوا إلــى‬\n     ‫حــدود ‪ .........‬ومعهــم اخلزنــة املســروقة مــن مســتودع ‪ .........‬للدهانــات‬\n     ‫وكســروها الثالثــة ثــم اتصلــوا علــي أنــا و‪ .........‬فرجعنــا لهــم وقالــوا‬\n     ‫نريــد أن ندخــل املســتودع الثانــي العائــد لشــركة ‪ .........‬للمــواد الغذائيــة‬\n     ‫وجيــت لهــم وقــد كســروا البــاب فدخلنــا اخلمســة وكســرنا بــاب‬\n     ‫املكتــب ووجدنــا اخلزنــة الكبيــرة فأردنــا أن نحملهــا فلــم نســتطع‬\n     ‫فقمنــا بســكب زيــت علــى األرض ثــم قمنــا بدفهــا علــى األرض حتــى‬\n     ‫بــاب املســتودع وملــا أردنــا أن نركبهــا يف الســيارة لــم نســتطع فأخذنــا‬\n     ‫حبــل وربطناهــا يف اجليــب العائــد ل‪ .........‬وســحبناها إلــى وادي ‪ .........‬ثــم‬\n     ‫ذهــب ‪ .........‬وأحضــر ونــش فقــام بتحميلهــا ثــم ركبنــا اخلمســة يف اجليــب‬\n     ‫وتركنــا الســيارة ‪ .....‬يف الــوادي ألنهــا غــرزت يف الــوادي واجتهنــا إلــى‬\n     ‫‪ .........‬ودخلنــا ورشــة حــداده نريــد قصهــا فشــاهدنا الدوريــة ومســكت‬\n     ‫‪ .........‬وهربنــا الباقــن وهــذا إقــراري بطوعــي واختيــاري غيــر مجبــر وال‬\n     ‫مكــره وبكامــل قــواي العقليــة املعتبــرة شــرعا املقــر مبــا فيــه ‪.........‬‬\n     ‫بصمتــه» كمــا جــرى االطــاع علــى إقــرار املدعــى عليــه الرابــع واملصدق‬\n     ‫شــرعا علــى دفتــر التحقيــق املرفــق لفــة رقــم (‪ )4‬صفحــة (‪ )2‬ونصــه «أقــر‬\n     ‫وأعتــرف أنــا ‪ .........‬ســعودي اجلنســية مبوجــب الســجل املدنــي رقــم ‪.........‬‬\n     ‫مصدرهــا جنــران وتاريخهــا ‪1427/11/19‬ه ـ عمــري ‪ 21‬ســنة أعــزب‬\n     ‫وأســكن يف ‪ .........‬وطالــب بجامعــة ‪ .....‬بأنــه يف صبــاح يــوم األربعــاء‬\n     ‫حوالــي الســاعة الثالثــة فجــر ًا اتصــل علــي أخــي ‪ .........‬وقــال مرنــي بعــد‬\n     ‫إشــارة ‪ ..............‬ثــم جيتهــم بعــد اإلشــارة وجلســت يف الســيارة حوالــي‬\n     ‫ربــع ســاعة ثــم قالــوا تعــال عنــد مســتودع ‪ .........‬للدهانــات املســمى ‪.........‬‬\n\n\n‫‪95‬‬\n\f‫فلمــا جئتهــم قامــوا بتحميــل خزنــة معــي وقالــوا ودنــا ل‪ .........‬فذهبنــا‬\n‫إلــى ‪ .........‬قريــب مــن مركــز حــرس احلــدود ســابقا ثــم نزلنــا أنــا و‪.....‬‬\n‫أخــي و‪ .........‬وقمنــا بكســرها جميعــا وبقينــا يف املوقــع حوالــي ســاعة‬\n‫والــذي كان معــي أخــي ‪ .........‬واملدعــو ‪ .........‬فقــط ووجدنــا بداخلهــا‬\n‫مبلــغ ألــف ومائتــي ريــال فقــط وأوراق وإقامات وأخذنــا الفلوس وتركنا‬\n‫باقــي األوراق ثــم اتفقنــا نرجــع إلــى مســتودع ‪ .........‬لنســرقه واتصلنــا‬\n‫علــى ‪ .........‬و‪ .........‬فجاءونــا علــى علــى ســيارة أخــي ‪ .........‬ثــم قمنــا‬\n‫بكســر بــاب مســتودع ‪ .........‬وقــام بكســره ‪ .........‬و‪ .........‬فقــط ثــم‬\n‫دخلنــا جميعنــا اخلمســة لســرقة اخلزنــة ولــم نســتطع حملهــا فقمنــا‬\n‫بســكب الزيــت يف األرض وقمنــا بدفهــا حتــى وصلناهــا إلــى البــاب‬\n‫اخلارجــي للمســتودع ثــم قمنــا بربطهــا بســيارة أخــي ‪ .........‬وقمنا بســحبها‬\n‫بالســيارة إلــى وادي ‪ .........‬ثــم ســحبناها بونــش أحضــره أخــي ‪.........‬‬\n‫فقــام بحملهــا يف اجليــب وتركــت ســيارتي ‪ ....‬يف الــوادي ألنهــا غــرزت‬\n‫وركبنــا اخلمســة مــع أخــي ‪ .........‬إلــى أن وصلنــا الشــرفة ثــم دخلنا ورشــة‬\n‫حــداده نريــد قــص اخلزنــة فجــاءت الشــرطة فمســكت أخــي ‪.........‬‬\n‫وهــرب ‪ .........‬و‪ .........‬وهــذا إقــراري بطوعــي واختيــاري وغيــر مجبــر وال‬\n‫مكــره وبكامــل قــواي العقليــة املعتبــرة شــرعا وعليــه أوقــع املقــر مبــا‬\n‫فيــه ‪ .........‬بصمته»كمــا جــرى االطــاع علــى إقــرار آخــر للمدعــى عليــه‬\n‫الرابــع ومصــدق شــرعا علــى دفتــر التحقيــق املرفــق لفــة رقــم (‪ )2‬صفحــة‬\n‫(‪ )16‬ويتضمــن مــا تضمنــه األول كمــا جــرى االطــاع علــى إقــرار‬\n‫املدعــى عليــه اخلامــس واملصــدق شــرعا علــى دفتــر التحقيــق املرفــق لفــة‬\n‫رقــم (‪ )4‬صفحــة (‪ )9‬ونصــه «أقــر واعتــرف أنــا ‪ .........‬ســعودي اجلنســية‬\n‫باجلــواز رقــم ‪ .........‬أبلــغ مــن العمــر ‪ 15‬ســنة أســكن بالريــاض ‪.........‬‬\n\n\n                                                                                       ‫‪96‬‬\n\f     ‫متعلــم حاصــل علــى الشــهادة االبتدائيــة ولــم أكمــل دراســتي حاليــا‬\n     ‫أعــزب كنــا أنــا و‪ .........‬يف الشــقة بعدهــا صحانــي‪ .........‬وقــال العيــال‬\n     ‫كلمونــي فقــال خــاص نــروح لهــم بعدهــا حضرنــا إلــى املوقــع علــى‬\n     ‫الســيارة أنــا و‪ .........‬إلــى املســتودع التابــع ل‪ .........‬للمــواد الغذائيــة‬\n     ‫وحصلنــا البــاب مفتــوح ومكســور وقمــت بالدخــول معهــم ‪ .........‬و‪.........‬‬\n     ‫و‪ .........‬و‪ .........‬وســحبت اخلزنــة معهــم مــن الداخــل إلــى أن أطلعناهــا يف‬\n     ‫اخلارج وســحبناها بالســيارة إلى وادي ‪ .........‬وكان يقود الســيارة ‪.........‬‬\n     ‫ثــم جــاء ‪ .........‬وجــاب ونــش وقــام بتحميلهــا إلــى داخــل الســيارة وذهبنــا‬\n     ‫بهــا إلــى ورشــة لكــي نفتحهــا وجــاءت الشــرطة ونحــن هنــاك وقبضــوا‬\n     ‫علينــا وهــذا إقــراري بطوعــي واختيــاري غير مجبــر وال مكره وبكامل‬\n     ‫قــواي العقليــة املعتبــرة شــرعا وعليــه أوقــع ‪ .........‬بصمته»كمــا جــرى‬\n     ‫االطــاع علــى إقــرار آخــر للمدعــى عليــه اخلامــس ومصــدق شــرعا علــى‬\n     ‫دفتــر التحقيــق املرفــق لفــة رقــم (‪ )3‬صفحــة (‪ )5‬ويتضمــن مــا تضمنــه‬\n     ‫إقــراره الســابق كمــا جــرى االطــاع علــى محاضــر الدوريــات األمنيــة‬\n     ‫املرفقــة باملعاملــة علــى اللفــة رقــم (‪ )72,11,10,9,8‬وتتضمــن ورود بــاغ‬\n     ‫للدوريــات األمنيــة بوجــود ســرقة وبحضورهــم للموقــع وجــدوا كســر يف‬\n     ‫بــاب شــركة ‪ .........‬وســرقة خزنــة منــه ووجــود حالــة ثانيــة للســرقة تبعــد‬\n     ‫عــن األولــى ثالثــن متــرا حملــل متعــرض خللــع بابــه وســرقة حزنــة فيــه ويف‬\n     ‫أثنــاء مســح الدوريــات لوحــظ ســيارة املدعــى عليهــم ومتــت متابعتهــا حتــى‬\n     ‫دخلــت الورشــة فتــم القبــض عليهــم بعــد محاولــة شــخصني منهــم الفــرار‬\n     ‫كمــا جــرى االطــاع علــى احملضــر املشــترك املرفــق باملعاملــة علــى اللفة‬\n     ‫رقــم (‪ )14‬واملــؤرخ ‪1431/10/20‬ه ـ ويتضمــن بأنــه عنــد اشــتباه‬\n     ‫الدوريــات األمنيــة بســيارة مــن نــوع ‪ .....‬رقــم اللوحــة‪ .........‬وفيهــا خمســة‬\n\n\n‫‪97‬‬\n\f‫أشــخاص مت القبــض علــى ســائقها وهــو املدعــى عليــه األول وعنــد‬\n‫مشــاهدة حــرس احلــدود مقاومــة املدعــى عليهــم للدوريــات األمنيــة متــت‬\n‫مســاندتهم والقبــض علــى مــن حــاول الهــرب وهــم املدعــى عليــه الرابــع‬\n‫واخلامــس كمــا جــرى االطــاع علــى محضــر املعاينــة املرفــق باملعاملــة‬\n‫علــى دفتــر التحقيــق اللفــة رقــم (‪ )1‬صفحــة (‪ )5,4,3‬كما جرى االطالع‬\n‫علــى تقاريــر التصويــر اجلنائــي املرفق لفــة رقــم ( ‪64,63‬و‪)62,61,60,59‬‬\n‫ويتضمــن توثيقــا مصــورا للمــكان بعــد حــدوث الســرقة كمــا جــرى‬\n‫االطــاع علــى مذكــرة انتقــال يف البصمــات املرفــق علــى لفــة رقــم (‪)58‬‬\n‫وتتضمــن أنــه مت العثــور علــى أثريــن صاحلــن للمقارنــة ولــم تتبــن النتيجــة‬\n‫وبســؤال املدعــى عليهــم عــن اإلقــرارات التــي أخــذت عليهــم واملدونــة‬\n‫ا لقــد أخــذت‬    ‫علــى دفاتــر التحقيــق أجــاب كل واحــد منهــم مبفــرده قائـ ً‬\n‫منــا هــذه االعترافــات جبــر ًا وحتــت التهديــد خلوفنــا مــن اجلهــات األمنيــة‬\n‫وأمــا مــا أخــذ منــا مــن اعترافــات يف احملكمــة اجلزئيــة فهــي ألن اجلهــات‬\n‫األمنيــة هددتنــا بالضــرب والســجن ووعدونــا يف حــال مت املصادقــة علــى‬\n‫أقوالنــا بأنــه ســيطلق ســراحنا هكــذا أجابــوا فجــرى ســؤالهم عــن‬\n‫بينتهــم علــى اإلكــراه فأجــاب كل واحــد منهــم مبفــرده قائــا ال بينــة‬\n‫لــدي هكــذا أجابــوا ويف جلســة أخــرى حضــر املدعــي العــام وحضــر‬\n‫حلضــوره املدعــى عليهــم فجــرى ســؤال كل منهــم عــن أي إضافــة يــودون‬\n‫إضافهــا فأجــاب كل واحــد منهــم مبفــرده قائــا ال إضافــة لــدي هكذا‬\n‫أجابــوا فبنــاء علــى ماتقــدم مــن الدعــوى وإنــكار املدعــى عليهــم ملــا جــاء‬\n‫فيهــا جملــة وتفصيــا وملــا جــاء يف إقــرارات املدعــى عليهــم واملصدقــة‬\n‫شــرعا ورجوعهــم عنهــا جميعــا بدعــوى اإلكــراه والبينــة لهــم علــى ذلــك‬\n‫وملــا جــاء يف محاضــر الدوريــات األمنيــة واحملضــر املشــترك املعــد مــن‬\n\n\n                                                                                      ‫‪98‬‬\n\f     ‫قبــل الدوريــات األمنيــة وحــرس احلــدود وملــا جــاء يف محضــر املعاينــة‬\n     ‫املشــار إليــه وملــا ورد مــن أحاديــث وآثــار يف درء احلــدود بالشــبهات فقــد‬\n     ‫روى الزهــري أن عائشــة رضــي اهلل عنهــا قالــت ‪ :‬قــال رســول اهلل صلــى‬\n     ‫اهلل عليــه وســلم ‪« :‬ادرؤا احلــدود عــن املســلمني مــا اســتطعتم» وقــد روي‬\n     ‫ذلــك عــن عبــداهلل بــن مســعود ومعــاذ بــن جبــل وملــا قــرره جمــع مــن أهــل‬\n     ‫العلــم أن مــن شــرط إقامــة حــد مــن حــدود اهلل باإلقــرار البقــاء عليــه إلــى‬\n     ‫متــام احلــد فــإن رجــع عــن إقــراره أو هــرب كــف عنــه ولضعــف مادفــع بــه‬\n     ‫املدعــى عليهــم مــن أنهــم وجــدوا اخلزنــة ملقــاة علــى جانــب الطريــق وملــا‬\n     ‫أظهرتــه التحقيقــات وإقــرارات املدعــى عليهــم مــن أن املدعــى عليهمــا‬\n     ‫األول والثانــي همــا أكثــر مــن رتــب ونســق للســرقة وحلداثــة ســن املدعــى‬\n     ‫عليــه اخلامــس فقــد حكمنــا مبايلــي أوال إدانــة املدعــى عليهــم مبــا أســند‬\n     ‫إليهــم مــن قيامهــم بالســرقة ثانيــا رد طلــب املدعــي العــام إقامــة حــد‬\n     ‫الســرقة علــى املدعــى عليهــم ودرءه عنهــم لرجوعهــم عــن إقراراتهــم ثالثــا‬\n     ‫تعزيــر كل واحــد مــن املدعــى عليهمــا األول والثانــي بالســجن ملــدة ثمــان‬\n     ‫ســنوات تبــدأ مــن تاريــخ إيقافهمــا علــى ذمــة هــذه القضيــة وجلــد كل‬\n     ‫واحــد منهمــا ثمامنائــة جلــدة مفرقــة علــى دفعــات كل دفعــة خمســون‬\n     ‫جلــدة وبــن الدفعــة واألخــرى خمســة عشــر يومــا رابعــا تعزيــر كل واحــد‬\n     ‫مــن املدعــى عليهمــا الثالــث والرابــع بالســجن ملــدة ســت ســنوات وجلــد‬\n     ‫كل واحــد منهمــا ســتمائة جلــدة مفرقــة علــى دفعــات كل دفعــة‬\n     ‫خمســون جلــدة وبــن الدفعــة واألخــرى خمســة عشــر يومــا خامســا تعزيــر‬\n     ‫املدعــى عليــه اخلامــس بالســجن ملــدة خمــس ســنوات اعتبــارا مــن تاريــخ‬\n     ‫إيقافــه وجلــده خمســمائة جلــدة مفرقــة علــى دفعــات كل دفعــة خمســون‬\n     ‫جلــدة وبــن كل دفعــة واألخــرى خمســة عشــر يومــا سادســا مصــادرة‬\n\n\n‫‪99‬‬\n\f‫الســيارة مــن نوع‪........‬رقــم اللوحــة ‪ .........‬والســيارة ‪ .......‬التــي حتمــل‬\n‫اللوحــة رقــم ‪ .........‬الســتخدامها يف اجلرميــة وبعــرض ذلــك علــى كل مــن‬\n‫املدعــي العــام واملدعــى عليهــم قــرروا اعتراضهــم علــى احلكــم فجــرى‬\n‫إفهامهــم بتعليمــات االســتئناف وأن عليهــم مراجعتنــا بعــد أســبوع‬\n‫الســتالم نســخة مــن احلكــم لالعتــراض عليــه يف مــدة أقصاهــا ثالثــون‬\n‫يومــا وصلــى اهلل وســلم علــى عبــده ورســوله محمــد وصلــى اهلل وســلم‬\n          ‫على نبينا محمد وآله وصحبه وسلم حرر يف ‪1433/07/01‬هـ‪0‬‬\n‫احلمــد هلل وحــده وبعــد فقــد عــادت املعاملــة مــن محكمــة االســتئناف‬\n‫مبوجــب اخلطــاب رقــم ‪ 332056377‬وتاريــخ ‪1434/01/12‬ه ـ ومرفــق‬\n‫بــه قــرار املالحظــة رقــم ‪ 33478335‬وتاريــخ ‪1433/12/26‬ه ـ ونــص‬\n‫احلاجــة منــه « وبدراســة القــرار الشــرعي وصــورة ضبطــه والالئحــة‬\n‫االعتراضيــة وأوراق املعاملــة لوحــظ أن الالئحــة االعتراضيــة املرفقــة‬\n‫ـاض واحــد وال بــد مــن اطــاع صاحبــي‬    ‫لــم يوقــع عليهــا باالطــاع إال قـ ٍ‬\n‫الفضيلــة املشــاركني يف احلكــم علــى الالئحــة والتوقيــع مبــا يفيــد‬\n‫ذلــك فعلــى أصحــاب الفضيلــة مالحظــة مــا ذكــر وإحلــاق مــا يجرونــه‬\n‫يف القــرار الشــرعي والضبــط وصورتــه ثــم إعــادة املعاملــة إلكمــال‬\n‫الــازم واهلل املوفــق وصلــى اهلل وســلم علــى نبينــا محمــد وآلــه وصحبــه‬\n‫وســلم قاضــي اســتئناف ‪ .........‬ختمــه وتوقيعــه قاضــي اســتئناف ‪.........‬‬\n‫ختمــه وتوقيعــه قاضــي اســتئناف ‪ .........‬ختمــه وتوقيعــه قاضــي اســتئناف‬\n‫‪ .........‬ختمــه وتوقيعــه رئيــس الدائــرة ‪ .........‬ختمــه وتوقيعه»وعليــه جنيــب‬\n‫علــى مــا ذكــره أصحــاب الفضيلــة يف مالحظتهــم بأنــا قــد اطلعنــا علــى‬\n‫الالئحــة االعتراضيــة جميعــا كمــا هــو ظاهــر يف ضبــط القضيــة وقــد‬\n‫ـاء علــى ذلــك فقــد أمرنــا بإحلــاق‬\n                                   ‫مت إجــراء الــازم بشــأن التوقيعــات وبنـ َ‬\n\n                                                                                      ‫‪100‬‬\n\f      ‫ذلــك بالضبــط وقــراره ومــن ثــم إعادتــه حملكمــة االســتئناف واهلل‬\n      ‫املوفــق وصلــى اهلل وســلم علــى نبينــا محمــد وآلــه وصحبــه وســلم حــرر يف‬\n                                                                    ‫‪1434/01/21‬هــ‪.‬‬\n      ‫احلمــد هلل وحــده وبعــد احلمــد هلل وحــده وبعــد فقــد عــادت املعاملــة‬\n      ‫مــن محكمــة االســتئناف مبوجــب اخلطــاب رقــم ‪ 34539812‬وتاريــخ‬\n      ‫‪1434/04/22‬ه ـ ومرفــق بــه قــرار املالحظــة رقــم ‪ 34180803‬وتاريــخ‬\n      ‫‪1434/04/07‬ه ـ ونــص احلاجــة منــه « وحيــث ســبق دراســة القــرار‬\n      ‫وصــورة ضبطــه والالئحــة االعتراضيــة وأوراق املعاملــة وباالطــاع علــى‬\n      ‫مــا أجــاب بــه أصحــاب الفضيلــة وأحلقــوه بالقــرار وصــورة ضبطــه بنــاء‬\n      ‫علــى القــرار رقــم ‪ 33478335‬وتاريــخ ‪1433/12/26‬ه ـ تقــررت املوافقــة‬\n      ‫علــى احلكــم بعــد اإلجــراء األخيــر واهلل املوفــق وصلــى اهلل وســلم علــى‬\n      ‫نبينــا محمــد وآلــه وصحبــه وســلم قاضي اســتئناف ‪ .........‬ختمه وتوقيعه‬\n      ‫قاضــي اســتئناف ‪ .........‬ختمــه وتوقيعــه قاضــي اســتئناف ‪ .........‬ختمــه‬\n      ‫وتوقيعــه قاضــي اســتئناف ‪ .........‬ختمــه وتوقيعــه رئيــس الدائــرة ‪.........‬‬\n      ‫ختمــه وتوقيعــه» ولبيــان ذلــك جــرى إثباتــه واهلل املوفــق وصلــى اهلل وســلم‬\n           ‫علــى نبينــا محمــد وآلــه وصحبــه وســلم حــرر يف ‪1434/05/07‬هــ‪0‬‬\n\n\n\n\n‫‪101‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"d790af0e-7af1-509b-8d33-8ecc09f91096","source_page_start":80,"source_page_end":101,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"20cfeb588ac51d452fda07d6f4fe95505ab414fe2ed489db1f50e6b2c36b473f","normalized_text_hash":"49a0ac530bdb017eb4a62e4433e47bfb53273444fceff4f0fd9825f5505f8c31","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v25-p80-33337036"},{"id":"eead44b7-b4ee-5fb8-8f64-09efe4015ea8","document_type":"judgment","category":"judicial","subcategory":"general","title":"سرقة -انتهاك حرمة منزل -سرقة من منزل -سرقة صور خاصة وشهادات -مساعدة يف السرقة -تغليظ العقوبة يف حق املباشر للسرقة -عدم انطباق شروط احلد -صرف النظر عن طلب إقامة حد السرقة -تعزير لقوة التهمة -تعزير بالسجن واجللد -إيقاف","document_number":"33321721","case_number":"3366441","judgment_number":null,"decision_number":null,"circular_number":null,"court":"المحكمة العامة مبكة املكرمة حا ال وباالشتراك مع فضيلة الشيخ","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1433/06/30","year":"1434","subject":"سرقة -انتهاك حرمة منزل -سرقة من منزل -سرقة صور خاصة وشهادات -مساعدة يف السرقة -تغليظ العقوبة يف حق املباشر للسرقة -عدم انطباق شروط احلد -صرف النظر عن طلب إقامة حد السرقة -تعزير لقوة التهمة -تعزير بالسجن واجللد -إيقاف","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":" ‫رقم الصك‪ 33321721 :‬تاريخه‪1433/06/30 :‬هـ‬\n                      ‫رقم الدعوى‪3366441 :‬‬\n     ‫رقم قرار التصديق من محكمة االستئناف ‪:‬‬\n               ‫‪ 3318653‬تاريخه ‪1434/1/20:‬ه‬\n\n\n\n‫ســرقة ‪-‬انتهــاك حرمــة منــزل ‪ -‬ســرقة مــن منــزل ‪ -‬ســرقة صــور خاصــة‬\n‫وشــهادات ‪ -‬مســاعدة يف الســرقة ‪ -‬تغليــظ العقوبــة يف حــق املباشــر‬\n‫للســرقة ‪ -‬عــدم انطبــاق شــروط احلــد ‪ -‬صــرف النظــر عــن طلــب إقامــة‬\n‫حــد الســرقة ‪ -‬تعزيــر لقــوة التهمــة ‪ -‬تعزيــر بالســجن واجللــد ‪ -‬إيقــاف‬\n                                                                     ‫عقوبــة ‪.‬‬\n\n\n\n\n‫‪-1‬أجمع أهل العلم على أن قطع الســارق إمنا يجب إذا شــهد بالســرقة‬\n‫شــاهدان حــران مســلمان ووصفــا مــا يوجــب القطــع‪ .‬انظــر ‪ :‬اإلجمــاع‬\n‫البــن املنــذر‪ .‬كتــاب أحــكام الســراق (ص‪ )86‬واملغنــى البــن قدامــه‪ ،‬بــاب‬\n                                                  ‫القطــع يف الســرقة (‪.)463/12‬‬\n‫‪-2‬جاء يف الشــرح الكبير (‪ ( : )555/6‬الشــرط الســادس ‪ :‬ثبوت الســرقة‬\n      ‫بشــهادة عدلــن أو إقــرار مرتــن وال ينــزع عــن إقــراره حتــى يقطــع ) ‪.‬‬\n‫‪-3‬جــاء عــن الشــيخ محمــد بــن إبراهيــم أنــه قــال يف قضيــة ســرقة ‪ ( :‬مــا‬\n‫دام أن الســارق رجــع عــن اعترافــه فإنــه يــدرأ عنــه احلــد ألنــه ليــس فيــه‬\n             ‫بينــة ســوى إقــراره وقــد زال قبــل اســتيفائه فســقط القطــع ) ‪.‬‬\n\n\n\n\n                                                                                     ‫‪102‬‬\n\f      ‫توجيــه االتهــام للمدعــى عليهمــا األول بالســرقة و الثانــي باملشــاركة ‪،‬‬\n      ‫وتبــن وجــود ســوابق علــى املدعــى عليــه األول دون الثانــي‪ ،‬حيــث أبلــغ‬\n      ‫أحــد الوافديــن عــن قيــام شــخص بالدخــول ملنزلــه عن طريــق النافذة بعد‬\n      ‫كســرها‪ ،‬و ســرقة شــنطة بهــا مبلــغ مالــي و صــور خاصــة و شــهادات‬\n      ‫‪ ،‬وقــرر اتهامــه للمدعــى عليــه األول ‪ ،‬ومت االنتقــال للموقــع ووصفــه‬\n      ‫‪،‬وباســتجوابهما اعترفــا مبــا نســب إليهمــا ‪ ،‬وصــدق اعترافهمــا شــرع ًا‬\n      ‫‪،‬وطلــب املدعــي العــام إثبــات مــا أســند إليهمــا ‪ ،‬وحكمــت احملكمــة‬\n      ‫علــى األول بحــد الســرقة‪ ،‬وعلــى الثانــي بعقوبــة تعزيريــة‪ ،‬أقــر املدعــى‬\n      ‫عليهمــا مبــا نســب إليهمــا‪ ،‬ثــم رجعــا عــن اعترافهمــا‪ ،‬وصــدر احلكــم‬\n      ‫بتعزيــر املدعــى عليهمــا بالســجن و اجللــد‪ ،‬وتقــرر إيقــاف العقوبــة عــن‬\n      ‫املدعــى عليــه الثانــي ملــدة خمــس ســنوات فــإن صــدرت منــه جنايــة فإنــه‬\n      ‫ينفــذ عليــه احلكــم يف هــذه اجلنايــة‪ ،‬وإن لــم تصــدر منــه جنايــة فــإن‬\n      ‫وصــدق احلكــم مــن‬   ‫تنفيــذ هــذا احلكــم يســقط لثبــوت اعتدالــه‪ُ ،‬‬\n                                                           ‫محكمــة االســتئناف ‪.‬‬\n\n\n\n\n‫‪103‬‬\n\f‫احلمــد هلل وحــده والصــاة والســام علــى مــن ال نبــي بعــده وبعــد ‪ .‬لدي إنا‬\n‫‪ ........‬القاضــي باحملكمــة العامــة مبكــة املكرمــة حــا ًال وباالشــتراك‬\n‫مــع فضيلــة الشــيخ ‪ ........‬وفضيلــة الشــيخ ‪ ........‬القضــاة باحملكمــة‬\n‫العامــة مبكــة املكرمــة حــا ًال وبنــاء علــى املعاملــة احملالــة لنــا مــن‬\n‫فضيلــة رئيــس احملكمــة العامــة مبكــة املكرمــة برقــم ‪3366441‬‬\n‫وتاريــخ ‪ 1433/01/25‬ه ـ املقيــدة باحملكمــة برقــم ‪ 33172019‬وتاريخ‬\n‫‪ 1433/01/25‬ه ـ ففــي يــوم األحــد املوافــق‪ 1433/06/15‬ه ـ افتتحــت‬\n‫ا‬\n‫اجللســة الســاعة ‪ 10 : 14‬وفيهــا حضــر املدعــي العــام ‪ ........‬وادعــى قائـ ً‬\n‫بصفتــي مدعي ـ ًا عام ـ ًا بدائــرة االدعــاء العــام مبكــة املكرمــة أدعــي‬\n‫ال مــن ‪ 23 ........ -1‬ســنة ســعودي اجلنســية مبوجــب الســجل‬       ‫علــى ك ً‬\n‫املدنــي رقــم ‪ ........‬أوقــف بالســجن العــام مبوجــب أمــر التمديــد رقــم‬\n‫‪ 55784‬وتاريــخ ‪1432/12/23‬ه ـ ‪ 25 ........ -2 .‬ســنة ســعودي اجلنســية‬\n‫مبوجــب الســجل املدنــي رقــم ‪ ........‬مفــرج عنــه بكفالــة حضوريــة بتاريــخ‬\n‫‪1432/12/06‬هــ‪ .‬إنــه بتاريــخ ‪1432/10/29‬ه ـ أبلــغ الوافــد ‪27 ........‬‬\n‫عام ـ ًا مينــي اجلنســية عــن قيــام شــخص بالدخــول إلــى منزلــه عــن طريــق‬\n‫النافــذة بعــد كســرها وســرقة شــنطة دبلوماســية عوديــة اللــون بهــا‬\n‫مبلــغ مالــي قــدره ‪ 45000‬ريــال ســعودي وصــور خاصــة وشــهادات وقــرر‬\n‫اتهامــه للمدعــى عليــه ‪ ........‬وباالنتقــال إلــى منــزل املجنــي عليــه الكائــن‬\n‫بحــي ‪ ........‬مبدخــل جبــل ‪ ........‬مقابــل بقالــة ‪ ........‬لوحــظ زجــاج النافــذة‬\n‫بالغرفــة اليمنــى مكســور ًا وكان الزجــاج متناثــر بالداخــل وأن اجلانــي‬\n‫دخــل الغرفــة اليســرى وســرق منهــا شــنطة دبلوماســية عوديــة اللــون‬\n\n                                                                                         ‫‪104‬‬\n\f      ‫مــن حتــت الســرير باجلهــة اليســرى مــن البــاب وباســتجواب املدعــى‬\n      ‫عليــه األول ‪ ........‬أقــر بأنــه يف مســاء االثنــن ‪1432/10/28‬ه ـ وبعــد‬\n      ‫صــاة العشــاء وأثنــاء جلوســه مــع أخيــه املدعــى عليــه الثانــي عــرض‬\n      ‫عليــه فكــرة ســرقة منــزل الوافــد اليمنــي ‪ ........‬وأخبــره أنــه يوجــد بــه‬\n      ‫شــنطة بهــا مبلــغ مالــي واتفقــا علــى ســرقته ســوي ًا فذهــب أو ًال للتأكــد‬\n      ‫مــن أن ‪ ........‬باحملــل الــذي يعمــل فيــه فوجــداه يف احملــل ثــم ذهبــا إلــى‬\n      ‫ا فكســر هــو زجــاج‬       ‫منزلــه وعنــد وصولهمــا إليــه وجــدا البــاب مقف ـ ً‬\n      ‫النافــذة املطلــة علــى الشــارع ممــا أدى إلــى جــرح قطعــي ونــزف الــدم‬\n      ‫مــن يــده ثــم دخــا مــن تلــك النافــذة إلــى املنــزل وســرقا الشــنطة وخرجــا‬\n      ‫مــن املــكان الــذي دخــا منــه واجتهــا إلــى منزلهمــا وعنــد وصولهمــا‬\n      ‫طلــب منــه املدعــى عليــه ‪ ........‬أن يدخــل املنــزل ويبقــى هــو يف خارجــه‬\n      ‫ملعرفــة مــا إذا كان بداخلــه أحــد أم ال وفعــل ذلــك وعنــد خروجــه وجــد‬\n      ‫املدعــى عليــه الثانــي ‪ ........‬قــد فتــح الشــنطة وبيــده املبلــغ املالــي فأخبــره‬\n      ‫بــأن املبلــغ الــذي بهــا تســعة وعشــرين ألــف وســبعمائة ريــال فتقاســماه‬\n      ‫ال منهمــا أربعــة عشــر ألــف وثمامنائــة وخمســن ريــال وحفــر‬          ‫فأخــذ ك ً‬\n      ‫هــو حفــرة يف الشــارع وأخفــى بهــا املبلــغ ومــن ثــم دخــل منزلــه وصــدق‬\n      ‫اعترافــه شــرع ًا وباســتجواب املدعــى عليــه الثانــي ‪ ........‬أقــر بأنــه يف‬\n      ‫مســاء االثنــن ‪1432/10/28‬ه ـ وبعــد صــاة العشــاء وأثنــاء جلوســه‬\n      ‫مــع أخيــه املدعــى عليــه األول عــرض عليــه فكــرة ســرقة منــزل الوافــد‬\n      ‫اليمنــي ‪ ........‬وأخبــره أنــه يوجــد بــه شــنطة بهــا مبلــغ مالــي واتفقــا علــى‬\n      ‫ســرقته ســوي ًا فذهــب أو ًال للتأكــد مــن أن ‪ ........‬باحملــل الــذي يعمــل فيــه‬\n      ‫فوجــداه يف احملــل ثــم ذهبــا إلــى منزلــه وعنــد وصولهمــا إليــه وجــدا الباب‬\n      ‫ا فكســر أخــوه ‪ ........‬زجــاج النافــذة املطلــة علــى الشــارع ممــا أدى‬      ‫مقفـ ً‬\n\n\n‫‪105‬‬\n\f‫إلــى جــرح قطعــي بيــده ونــزف الــدم منهــا ثــم دخــل أخــوه ‪ ........‬مــن تلــك‬\n‫النافــذة إلــى املنــزل وســرق الشــنطة وخــرج مــن املــكان الــذي دخــل منــه‬\n‫بينمــا هــو كان يف اخلــارج يقــوم بــدور املراقبــة واجتهــا إلــى منزلهمــا‬\n‫وعنــد وصولهمــا دخــل هــو املنــزل وبقــي ‪ ........‬باخلــارج ومعــه الشــنطة‬\n‫وأخــذ مفــك وســكني مــن املنــزل وفتــح الشــنطة ووجــد بهــا مبلــغ تســعة‬\n‫ال منهمــا أربعــة‬ ‫وعشــرين ألــف وســبعمائة ريــال فتقاســماه فأخــذ ك ً‬\n‫عشــر ألــف وثمامنائــة وخمســن ريــال ومــن ثــم دخــا املنــزل وخبــا ذلــك‬\n‫املبلــغ يف حفــرة حفرهــا يف غرفــة نــوم أخيــه وصــدق اعترافــه شــرع ًا‬\n‫وبإجــراء املواجهــة بــن املدعــى عليهمــا حيــث ذكــر األول أن الثانــي‬\n‫دخــل معــه املنــزل وســرقه بينمــا ذكــر الثانــي أنــه لــم يدخــل فأصــر‬\n‫الثانــي علــى أقوالــه فيمــا عــدل األول عــن أقوالــه وذكــر أن الثانــي لــم‬\n‫يدخــل إلــى املنــزل وقــد أســفر التحقيــق عــن توجــه االتهــام للمدعــى عليــه‬\n‫األول ‪ ........‬بســرقة مبالــغ ماليــة ومشــاركة املدعــى عليــه الثانــي ‪........‬‬\n‫باملســاعدة واملراقبــة واملؤيــد بقــرار جلنــة إدارة الهيئــة رقــم ‪/33‬م لعــام‬\n‫‪1433‬ه ـ وذلــك لألدلــة والقرائــن اآلتيــة ‪ -1 :‬مــا جــاء يف إقــرار املدعــى‬\n‫عليــه األول املصــدق شــرع ًا املنــوه عنــه املرفــق ص ‪ 15‬لفــة ‪ -2 . 9‬مــا‬\n‫جــاء بإقــرار لثانــي املصــدق شــرع ًا ص ‪ 7‬لفــة ‪-3 . 1‬مــا جــاء مبحضــر‬\n‫املواجهــة املشــار إليــه ص‪ 9‬لفــة ‪ -4 .1‬مــا جــاء يالتقريــر الطبــي لفــة ‪. 15‬‬\n‫‪ -5‬مــا جــاء بســند اســتالم املجنــي عليــه بحقــه اخلــاص املــدون لفــة ‪. 11‬‬\n‫‪ -6‬مــا جــاء يف محضــر االنتقــال املعاينــة املــدون ص ‪ 2‬لفــة ‪ . 9‬وبالبحــث‬\n‫عــن ســوابقهماعثر لــأول علــى ســت ســوابق أربــع ســرقات واثنتــن نصب‬\n‫واحتيــال ولــم يعثــر للثانــي علــى ســوابق وحيــث إن مــا قــام بــه املدعــى‬\n‫عليهمــا فعــل محــرم ومعاقــب عليــه شــرع ًا مــن قيــام األول بســرقة مــال‬\n\n\n                                                                                       ‫‪106‬‬\n\f      ‫محتــرم مــن حــرزه ال شــبهة لــه فيــه يزيــد عــن النصــاب وهــو مكلــف‬\n      ‫مختــار ومشــاركة الثانــي لــه باملســاعدة لــذا أطلــب إدانتهمــا مبــا أســند‬\n      ‫إليهمــا واحلكــم علــى األول بحــد الســرقة الــوارد يف اآليــة الكرميــة ‪38‬‬\n      ‫مــن ســورة املائــدة واحلكــم علــى الثانــي بعقوبــة تعزيريــة علم ـ ًا أن احلــق‬\n      ‫اخلــاص إنتهــى باســتالم صاحبــه لــه واهلل املوفــق وبعــرض ذلــك علــى‬\n      ‫املدعــى عليهمــا صادقــا علــى صحــة مــا جــاء يف دعــوى املدعــي العــام‬\n      ‫كمــا صادقــا علــى صحــة اعترافهمــا املــدون بعاليــه ثــم قــرر املدعــي‬\n      ‫األول ‪ ........‬قائ ًــا إن زجــاج النافــذة كان مكســور ًا مــن األصــل فدفعته‬\n      ‫بكلتــا يــدي فســقط وأنــا الــذي دفعــت وأخــذت الشــنطة وكان املدعــى‬\n      ‫عليــه الثانــي يف اخلــارج هكــذا قــال وللتأمــل رفعــت اجللســة ويف اجللســة‬\n      ‫التاليــة حضــر املدعــى عليهمــا ‪ ........‬و‪ ........‬فجــرى عــرض إقرارهمــا‬\n      ‫املــدون بعاليــه عليهمــا فقــاال إن إقرارهمــا هــذا غيــر صحيــح فالقضيــة‬\n      ‫كانــت عنــد أحــد احملققــن ونقلــت إلــى محقــق آخــر وقــد مــارس معنــا‬\n      ‫هــذا احملقــق الضــرب والتهديــد وقــد حبســنا يف ســجن إنفــرادي ملــدة‬\n      ‫أســبوعني أو أكثــر ولــم يخرجنــا حتــى اعترفنــا علــى أنفســنا كذب ـ ًا‬\n      ‫والصحيــح أننــا كنــا نعمــل لــدى شــخص مينــي اجلنســية يقــال لــه ‪........‬‬\n      ‫وقــد عملنــا عنــده أكثــر مــن ثمــان ســنوات ونطلبــه مبالــغ ماليــة وهــي‬\n      ‫أجــرة عملنــا فقمــت أنــا ‪ ........‬بكســر زجــاج النافــذة فســقط وذلــك‬\n      ‫برميــه بحجــر وهــذا هــو احلاصــل فقــط وقــد قلنــا لهــم إننــا ســنقفل احملــل‬\n      ‫فذهبــوا واشــتكوا كذب ـ ًا وإال فإنــه ال أحــد يتنــازل عــن مبلــغ خمســة‬\n      ‫وأربعــن ألــف ريــال و‪ ........‬قــد تنــازل وســافر إلــى اليمــن هكــذا قــاال‬\n      ‫ا ليس لدي‬      ‫وبســؤال املدعــي العــام هــل لديــة بينــه علــى دعــواه أجــاب قائـ ً‬\n      ‫ســوى ما جاء يف أوراق املعاملة وللتأمل رفعت اجللســة ويف اجللســة التالية‬\n\n\n‫‪107‬‬\n\f‫حضــر املدعــي العــام كمــا حضــر املدعــى عليهمــا ‪ ........‬و‪ ........‬فجــرى‬\n‫ســؤال املدعــى عليهمــا عــن اعترافهمــا يف مجلــس احلكــم بطوعهمــا‬\n‫واختيارهمــا ولــم يلحقهمــا إكــراه مــن قبلنــا نحــن نظــار القضيــة فقــاال‬\n‫إننــا اعترفنــا بذلــك ألننــا كنــا نريــد أن ننهــي القضيــة ولــم نتصــور أنهــا‬\n‫ســتطول إلــى هــذا احلــد هكــذا أجابــا فبعــد ســماع الدعــوى واإلجابــة‬\n‫ونظــرا لرجــوع املدعــى عليهمــا عــن إقرارهمــا إال أنــه قرينــة قويــة موجبــة‬\n‫لتغليــظ العقوبــة يف حقهمــا ونظــرا ألن املدعــي العــام يطالــب بإقامــة‬\n‫حــد الســرقة علــى املدعــى عليهمــا وقــد أجمــع أهــل العلــم علــى أن قطــع‬\n‫الســارق إمنــا يجــب إذا شــهد بالســرقة شــاهدان حــران مســلمان ووصفــا‬\n‫مــا يوجــب القطــع ينظــر يف ذلــك اإلجمــاع البــن املنــذر كتــاب أحــكام‬\n‫الســراق صــ‪ 68‬و املغنــي بــاب القطــع يف الســرقة جــ‪ 463/12‬وقد جاء يف‬\n‫الشــرح الكبيــر جــ‪ 555/26‬الشــرط الســادس ‪ :‬ثبــوت الســرقة بشــهادة‬\n‫عدلــن أو إقــرار مرتــن وال ينــزع عــن إقــراره حتــى يقطــع وقــد جــاء عــن‬\n‫الشــيخ محمــد بــن إبراهيــم أنــه قــال يف قضيــة ســرقة [ مــا دام أن الســارق‬\n‫رجــع عــن اعترافــه فإنــه يــدرأ عنــه احلــد ألنــه ليــس فيــه بينــة ســوى إقــراره‬\n‫وقــد زال قبــل اســتيفاءه فســقط القطــع ] ونظــرا ألن إقــرار املدعــى‬\n‫عليهمــا قــد تضمــن مباشــرا وهــو ‪ ........‬واآلخــر متســتر وهــو ‪ ........‬ممــا‬\n‫يوجــب تغليــظ العقوبــة يف حــق املباشــر دون املتســتر ونظــرا ألن املقصــود‬\n‫بالعقوبــة والتعزيــر الــردع والتأديــب وكــف اجلانــي عــن العــودة ملثــل مــا‬\n‫صــدر منــه وبعــد الرجــوع إلــى أوراق املعاملــة وجــد أن املدعــى عليــه ‪........‬‬\n‫قــد قيــدت يف حقــه ســت ســوابق أربــع منهــا مــن جنــس مــا ادعــي بــه‬\n‫عليــه وهــذا يــدل علــى ســوء ســيرته وســلوكه وأنــه لــم يرتــدع بالعقوبــات‬\n‫الســابقة بينمــا املدعــى عليــه الثانــي ســجله نظيــف مــن الســوابق لــذا‬\n\n\n                                                                                           ‫‪108‬‬\n\f      ‫فقــد ثبــت لدينــا قــوة التهمــة املوجهــه للمدعــى عليهمــا مــن قبــل املدعــي‬\n      ‫العــام وقررنــا مــا يلــي أوال ‪ :‬صــرف النظــر عــن إقامــة حــد الســرقة علــى‬\n      ‫املدعــى عليهمــا لعــدم ثبــوت موجبهــا ‪.‬ثانيــا ‪ :‬تعزيــر املدعــى عليــه األول‬\n      ‫‪ ........‬بســجنه خمــس ســنوات مــن تاريــخ إيقافــه وجلــده ألــف جلــدة‬\n      ‫مفرقــة علــى فتــرات بــن كل فتــرة والتــي تليهــا مــا ال يقــل عــن أســبوع‬\n      ‫مبقــدار خمســن جلــدة لــكل فتــرة ثالثــا ‪ :‬تعزيــر املدعــى عليــه الثانــي‬\n      ‫‪ ........‬بســجنه ملــدة ســنة مــن تاريــخ إيقافــه وجلــده مائتــن جلــدة مفرقــة‬\n      ‫علــى فتــرات بــن كل فتــرة والتــي تليهــا مــا ال يقــل عــن أســبوع مبقــدار‬\n      ‫خمســن جلــدة لــكل فتــرة ثالثــا ‪ :‬إيقــاف تنفيــذ احلكــم علــى املدعــى‬\n      ‫عليــه الثانــي ملــدة خمــس ســنوات فــإن صــدر منــه جنايــة مماثلــة أو غيــر‬\n      ‫مماثلــة خــال مــدة إيقــاف تنفيــذ احلكــم فإنــه ينفــذ عليــه احلكــم يف‬\n      ‫هــذه اجلنايــة إضافــة إلــى مــا ســيحكم عليــه يف اجلنايــات األخــرى وإن‬\n      ‫مضــت مــدة اإليقــاف ولــم يصــدر منــه أي جنايــة فــإن تنفيــذ احلكــم‬\n      ‫يســقط يف حقــه لثبــوت اعتدالــه ومحافظتــه طيلــة ســنوات اإليقــاف‬\n      ‫املذكــورة ‪ .‬وبعــرض ذلــك علــى املدعــى عليهمــا قنــع بــه املدعــى عليــه‬\n      ‫‪ ........‬وقــرر املدعــى عليــه ‪ ........‬و املدعــي العــام اعتراضهمــا بالئحــة‬\n      ‫اعتراضيــة فجــرى إفهامهمــا بتعليمــات االســتئناف حيــال ذلــك ففهمــا ‪.‬‬\n      ‫وبــاهلل التوفيــق ‪ .‬وصلــى اهلل علــى نبينــا محمــد وغلــى آلــه وصحبــه وســلم‬\n                                                 ‫تســليما ‪ .‬حــرر يف ‪1433/06/18‬ه ـ‬\n             ‫احلمد هلل وحده والصالة والسالم على من ال نبي بعده ‪ ،‬وبعد ‪-:‬‬\n      ‫فقــد جــرى منــا نحــن قضــاة الدائــرة اجلزائيــة اخلماســية الثالثــة مبحكمة‬\n      ‫االســتئناف مبنطقــة مكــة املكرمــة االطــاع علــى املعاملــة الــواردة مــن‬\n      ‫فضيلــة رئيــس احملكمــة العامــة مبكــة املكرمــة برقــم ‪33/172019‬‬\n\n\n‫‪109‬‬\n\f‫وتاريــخ ‪1434/1/10‬ه ـ املرفــق بهــا القــرار رقــم ‪ 33321721‬وتاريــخ‬\n‫‪1433/6/30‬ه ـ الصــادر مــن أصحــاب الفضيلــة القضــاة باحملكمــة‬\n‫العامــة مبكــة املكرمــة الشــيخ‪ ........ /‬والشــيخ‪ ........ /‬والشــيخ‪........ /‬‬\n‫املتضمــن دعــوى املدعــي العــام ضــد‪ ........ /‬ورفيقــه ‪ ،‬املتهمــن يف‬\n                                     ‫ســرقة‪ ،‬احملكــوم فيــه مبــا دون باطنــه‬\n‫وبدراســة احلكــم وصــورة ضبطــه والئحته اإلعتراضيــة تقرر باألكثرية‬\n‫املوافقــة علــى احلكــم ‪ .‬وبــاهلل التوفيــق ‪ ،‬وصلــى اهلل علــى نبينــا محمــد‬\n                                                      ‫وعلــى آلــه وصحبــه وســلم ‪.‬‬\n\n\n\n\n                                                                                      ‫‪110‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"d790af0e-7af1-509b-8d33-8ecc09f91096","source_page_start":102,"source_page_end":110,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"746ce3470c5320d42364c9748e9063ccb4b15c578ef6bf1cf336304c25047589","normalized_text_hash":"eae00ea548fde799e8a7ca0828f0f074e28c714eb119300934ac9cfb5e88e27c","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v25-p102-33321721"}]$archive_payload$::jsonb AS data)
INSERT INTO public.legal_documents (
  id,document_type,category,subcategory,title,document_number,case_number,judgment_number,decision_number,
  circular_number,court,circuit,issuing_authority,document_date,hijri_date,year,subject,summary,facts,claims,
  reasoning,ruling,principle_text,full_text,legal_articles,source_id,source_file_id,source_page_start,
  source_page_end,original_source,acquisition_source,source_url,content_hash,normalized_text_hash,status,review_status
)
SELECT (x->>'id')::uuid,x->>'document_type',x->>'category',x->>'subcategory',x->>'title',x->>'document_number',
       x->>'case_number',x->>'judgment_number',x->>'decision_number',x->>'circular_number',x->>'court',x->>'circuit',
       x->>'issuing_authority',(x->>'document_date')::date,x->>'hijri_date',x->>'year',x->>'subject',x->>'summary',
       x->>'facts',x->>'claims',x->>'reasoning',x->>'ruling',x->>'principle_text',x->>'full_text',
       COALESCE(x->'legal_articles','[]'::jsonb),(x->>'source_id')::uuid,(x->>'source_file_id')::uuid,
       (x->>'source_page_start')::integer,(x->>'source_page_end')::integer,x->>'original_source',
       x->>'acquisition_source',x->>'source_url',x->>'content_hash',x->>'normalized_text_hash',x->>'status',x->>'review_status'
FROM payload CROSS JOIN LATERAL jsonb_array_elements(payload.data) AS x
LIMIT 25
ON CONFLICT (id) DO NOTHING;

